import { normalizeExternalCode } from './instructionMerge.js'

/** 部屋タブマトリクス: ルーム数・行数・特殊指示列 */
export const ROOM_MATRIX_ROW_COUNT = 4
export const ROOM_MATRIX_ROOM_COUNT = 10
export const SPECIAL_COLUMN_KEYS = ['special1', 'special2', 'special3', 'special4', 'special5']

/**
 * user_profile ごとの special1〜5 → contractor 解決
 * @returns {{ columns: Record<string, string|null>, headers: Record<string, string>, contractorIds: Set<string> }}
 */
export function buildSpecialContractorColumnMap(contractors, userProfileId) {
  const columns = Object.fromEntries(SPECIAL_COLUMN_KEYS.map((k) => [k, null]))
  const headers = Object.fromEntries(SPECIAL_COLUMN_KEYS.map((k) => [k, '']))
  const pool = (contractors || []).filter((c) => {
    if (!c?.is_special) return false
    if (userProfileId != null && Number(c.user_profile_id) !== Number(userProfileId)) return false
    const desc = String(c.description || '').trim()
    return SPECIAL_COLUMN_KEYS.includes(desc)
  })
  for (const key of SPECIAL_COLUMN_KEYS) {
    const hit = pool.find((c) => String(c.description || '').trim() === key)
    if (hit) {
      columns[key] = String(hit.id)
      headers[key] = String(hit.label || '').trim()
    }
  }
  const contractorIds = new Set(Object.values(columns).filter(Boolean))
  return { columns, headers, contractorIds }
}

export function cellToPayloadKey(colKey, roomOrder, rowIndex) {
  return `${colKey}${roomOrder}-${rowIndex}`
}

export function parseSpecialPayloadKey(key) {
  const m = String(key || '').match(/^(special[1-5])(\d+)-(\d+)$/)
  if (!m) return null
  return {
    colKey: m[1],
    roomOrder: Number(m[2]),
    rowIndex: Number(m[3]),
  }
}

/** 表示専用ダミー（draft 配列には入れない） */
export function isMatrixDummyRow(row) {
  return Boolean(row?._matrixDummy)
}

export function createMatrixDummyRow(contractorId) {
  return {
    external_code: '',
    quantity: null,
    is_quantity: false,
    description: '',
    content: '',
    contractor_id: contractorId != null ? String(contractorId) : null,
    _matrixDummy: true,
  }
}

export function isPhotoLinkRowBlank(row) {
  if (!row || isMatrixDummyRow(row)) return true
  if (String(row.external_code || '').trim()) return false
  if (row.quantity != null && String(row.quantity).trim() !== '') return false
  if (String(row.content || '').trim()) return false
  if (row.contractor_id) return false
  if (String(row.description || '').trim()) return false
  if (row.is_quantity) return false
  return true
}

export function stripLegacyMatrixDummyRows(links) {
  return (links || []).filter((row) => !isMatrixDummyRow(row))
}

function contractorIdMatches(row, contractorId) {
  return row?.contractor_id != null && String(row.contractor_id) === String(contractorId)
}

function matrixRowTag(row) {
  const n = Number(row?._matrixRow)
  return Number.isFinite(n) && n >= 1 && n <= ROOM_MATRIX_ROW_COUNT ? n : null
}

function defaultEmptyLinkRow() {
  return {
    external_code: '',
    quantity: null,
    is_quantity: false,
    description: '',
    content: '',
    contractor_id: null,
    _k: Math.random().toString(36).slice(2),
  }
}

/** 依頼先 contractor_id が一致する link の配列インデックス（出現順） */
export function collectContractorLinkIndices(links, contractorId) {
  const indices = []
  for (let i = 0; i < (links || []).length; i++) {
    const row = links[i]
    if (isMatrixDummyRow(row)) continue
    if (contractorIdMatches(row, contractorId)) indices.push(i)
  }
  return indices
}

/**
 * マトリクス表示用: 依頼先ごとに最大4スロット。空スロットは仮想ダミーのみ（draft には追加しない）。
 */
export function buildMatrixSlotsForContractor(links, contractorId, rowCount = ROOM_MATRIX_ROW_COUNT) {
  const cid = String(contractorId)
  const cleanLinks = stripLegacyMatrixDummyRows(links)
  const slots = Array.from({ length: rowCount }, () => createMatrixDummyRow(cid))
  const untagged = []

  for (const row of cleanLinks) {
    if (!contractorIdMatches(row, cid)) continue
    const tag = matrixRowTag(row)
    if (tag != null) {
      slots[tag - 1] = { ...row }
    } else {
      untagged.push({ ...row })
    }
  }

  for (const row of untagged) {
    const emptySlot = slots.findIndex((s) => isMatrixDummyRow(s))
    if (emptySlot < 0) break
    slots[emptySlot] = row
  }

  for (let i = 0; i < rowCount; i++) {
    const row = slots[i]
    if (isMatrixDummyRow(row)) continue
    const hasCode = Boolean(String(row.external_code || '').trim())
    const hasContent = Boolean(String(row.content || '').trim())
    if (!hasCode && !hasContent) slots[i] = createMatrixDummyRow(cid)
  }

  const filledCount = slots.filter(
    (s) => !isMatrixDummyRow(s) && Boolean(String(s.external_code || '').trim())
  ).length
  return { slots, filledCount }
}

/** 次に追加できる最終尾行（1〜4）。4行すべてコードありなら null */
export function findNextMatrixTailRowIndex(links, contractorId) {
  const { slots, filledCount } = buildMatrixSlotsForContractor(links, contractorId)
  if (filledCount >= ROOM_MATRIX_ROW_COUNT) return null
  for (let i = 0; i < ROOM_MATRIX_ROW_COUNT; i++) {
    const code = String(slots[i]?.external_code || '').trim()
    if (!code) return i + 1
  }
  return null
}

/**
 * ルームバケット内の表示行数: 占有行の最大 + 1（最低1、上限 ROOM_MATRIX_ROW_COUNT）
 */
export function getMatrixVisibleRowCountForRoom(links, columnMap) {
  let maxRow = 0
  const cleanLinks = stripLegacyMatrixDummyRows(links)

  for (const colKey of SPECIAL_COLUMN_KEYS) {
    const contractorId = columnMap?.columns?.[colKey]
    if (!contractorId) continue
    const { slots } = buildMatrixSlotsForContractor(cleanLinks, contractorId)
    for (let i = 0; i < ROOM_MATRIX_ROW_COUNT; i++) {
      if (extractMatrixCellPatchFromRow(slots[i])) {
        maxRow = Math.max(maxRow, i + 1)
      }
    }
  }

  return Math.min(Math.max(maxRow + 1, 1), ROOM_MATRIX_ROW_COUNT)
}

export function isMatrixColumnFull(links, contractorId) {
  return findNextMatrixTailRowIndex(links, contractorId) == null
}

export function extractMatrixCellPatchFromRow(row) {
  if (!row || isMatrixDummyRow(row)) return null
  const code = String(row.external_code || '').trim()
  const content = String(row.content || '').trim()
  if (!code && !content) return null
  return {
    external_code: code,
    description: String(row.description ?? ''),
    content,
    quantity: row.quantity,
    is_quantity: Boolean(row.is_quantity),
  }
}

function extractMatrixCellPatch(slots, rowIndex) {
  return extractMatrixCellPatchFromRow(slots?.[rowIndex - 1])
}


/**
 * 部屋バケット保存用: 非 special を先頭（元順）、special1〜5 グループを後方、各列内は _matrixRow 順
 */
export function sortRoomBucketLinksForSave(links, columnMap) {
  const arr = stripLegacyMatrixDummyRows(links)
  const specialOrder = SPECIAL_COLUMN_KEYS.map((k) => columnMap?.columns?.[k]).filter(Boolean)
  const specialIdSet = new Set(specialOrder.map(String))

  const indexed = arr.map((row, i) => ({ row, i }))
  const nonSpecial = []
  const specialByCid = new Map(specialOrder.map((cid) => [String(cid), []]))
  const specialExtra = []

  for (const item of indexed) {
    const { row } = item
    if (isMatrixDummyRow(row)) {
      nonSpecial.push(item)
      continue
    }
    const cid = row.contractor_id != null ? String(row.contractor_id).trim() : ''
    if (!cid || !specialIdSet.has(cid)) {
      nonSpecial.push(item)
      continue
    }
    const bucket = specialByCid.get(cid)
    if (bucket) bucket.push(item)
    else specialExtra.push(item)
  }

  const byMatrixRow = (a, b) => {
    const ra = matrixRowTag(a.row) ?? ROOM_MATRIX_ROW_COUNT + 1
    const rb = matrixRowTag(b.row) ?? ROOM_MATRIX_ROW_COUNT + 1
    if (ra !== rb) return ra - rb
    return a.i - b.i
  }

  const out = []
  for (const { row } of nonSpecial.sort((a, b) => a.i - b.i)) {
    out.push(row)
  }
  for (const cid of specialOrder) {
    const group = specialByCid.get(String(cid)) || []
    group.sort(byMatrixRow)
    for (const { row } of group) {
      out.push(row)
    }
  }
  for (const { row } of specialExtra.sort((a, b) => a.i - b.i)) {
    out.push(row)
  }
  return out
}

/**
 * 同一列内の並べ替え（部屋タブのドロップ行を _matrixRow として反映）
 */
export function reorderMatrixColumnInBucket(links, contractorId, fromRowIndex, toRowIndex, options = {}) {
  const fromRow = Number(fromRowIndex)
  const toRow = Number(toRowIndex)
  if (
    !Number.isFinite(fromRow) ||
    !Number.isFinite(toRow) ||
    fromRow < 1 ||
    fromRow > ROOM_MATRIX_ROW_COUNT ||
    toRow < 1 ||
    toRow > ROOM_MATRIX_ROW_COUNT
  ) {
    return { links: stripLegacyMatrixDummyRows(links), changed: false, reason: 'invalid' }
  }
  if (fromRow === toRow) {
    return { links: stripLegacyMatrixDummyRows(links), changed: false, reason: 'same-cell' }
  }

  let arr = stripLegacyMatrixDummyRows(links)
  const { slots } = buildMatrixSlotsForContractor(arr, contractorId)
  const fromPatch = extractMatrixCellPatchFromRow(slots[fromRow - 1])
  if (!fromPatch) {
    return { links: arr, changed: false, reason: 'no-source' }
  }

  const rowPatches = new Map()
  for (let i = 0; i < ROOM_MATRIX_ROW_COUNT; i++) {
    const patch = extractMatrixCellPatchFromRow(slots[i])
    if (patch) rowPatches.set(i + 1, patch)
  }

  rowPatches.delete(fromRow)

  if (fromRow < toRow) {
    for (let r = fromRow + 1; r <= toRow; r++) {
      if (rowPatches.has(r)) {
        rowPatches.set(r - 1, rowPatches.get(r))
        rowPatches.delete(r)
      }
    }
  } else {
    for (let r = fromRow - 1; r >= toRow; r--) {
      if (rowPatches.has(r)) {
        rowPatches.set(r + 1, rowPatches.get(r))
        rowPatches.delete(r)
      }
    }
  }
  rowPatches.set(toRow, fromPatch)

  for (let r = 1; r <= ROOM_MATRIX_ROW_COUNT; r++) {
    const cleared = clearRoomMatrixCellInBucket(arr, { contractorId, rowIndex: r }, options)
    arr = cleared.links
  }
  for (const rowNum of [...rowPatches.keys()].sort((a, b) => a - b)) {
    const upserted = upsertRoomMatrixCellInBucket(
      arr,
      { contractorId, rowIndex: rowNum, patch: rowPatches.get(rowNum) },
      options
    )
    arr = upserted.links
  }

  return { links: arr, changed: true, reason: null, toRowIndex: toRow }
}

/** @deprecated 同一列は reorderMatrixColumnInBucket を使用 */
export function moveRoomMatrixCellInBucket(
  links,
  { fromContractorId, fromRowIndex, toContractorId, toRowIndex },
  options = {}
) {
  if (String(fromContractorId) !== String(toContractorId)) {
    return { links: stripLegacyMatrixDummyRows(links), changed: false, reason: 'cross-contractor' }
  }
  return reorderMatrixColumnInBucket(links, fromContractorId, fromRowIndex, toRowIndex, options)
}

/**
 * マトリクス座標に対応する link インデックスを解決。未割当なら写真タブ同様に空行を再利用。
 */
export function resolveMatrixCellLinkIndex(links, { contractorId, rowIndex }, options = {}) {
  const rowNum = Number(rowIndex)
  if (!Number.isFinite(rowNum) || rowNum < 1 || rowNum > ROOM_MATRIX_ROW_COUNT) {
    return { index: -1, links: stripLegacyMatrixDummyRows(links), created: false }
  }

  const createEmptyRow = options.createEmptyRow || defaultEmptyLinkRow
  const maxRows = Number(options.maxRows) || 80
  const arr = stripLegacyMatrixDummyRows(links)
  const cid = String(contractorId)
  const slotIdx = rowNum - 1

  for (let i = 0; i < arr.length; i++) {
    const row = arr[i]
    if (isMatrixDummyRow(row)) continue
    if (contractorIdMatches(row, cid) && matrixRowTag(row) === rowNum) {
      return { index: i, links: arr, created: false }
    }
  }

  const contractorIndices = collectContractorLinkIndices(arr, cid)
  if (contractorIndices[slotIdx] !== undefined) {
    const candidate = arr[contractorIndices[slotIdx]]
    if (matrixRowTag(candidate) == null) {
      return { index: contractorIndices[slotIdx], links: arr, created: false }
    }
  }

  const emptyIx = arr.findIndex(
    (r) => !String(r.external_code || '').trim() && isPhotoLinkRowBlank(r)
  )
  if (emptyIx >= 0) {
    return { index: emptyIx, links: arr, created: false }
  }

  if (arr.length < maxRows) {
    arr.push(createEmptyRow())
    return { index: arr.length - 1, links: arr, created: true }
  }

  return { index: arr.length - 1, links: arr, created: false }
}

export function upsertRoomMatrixCellInBucket(links, { contractorId, rowIndex, patch }, options = {}) {
  const rowNum = Number(rowIndex)
  const createEmptyRow = options.createEmptyRow || defaultEmptyLinkRow
  const resolved = resolveMatrixCellLinkIndex(links, { contractorId, rowIndex }, options)
  if (resolved.index < 0) return { links: resolved.links, changed: false, targetIndex: -1 }

  const arr = [...resolved.links]
  const targetIx = resolved.index
  const cid = String(contractorId)
  const prev = arr[targetIx] || createEmptyRow()

  const merged = { ...prev, ...patch, contractor_id: cid, _matrixRow: rowNum }
  delete merged._matrixDummy

  const hasCode = Boolean(String(merged.external_code || '').trim())
  const hasContent = Boolean(String(merged.content || '').trim())
  if (hasCode) {
    if (merged.quantity == null || merged.quantity === '') merged.quantity = 1
    merged.is_quantity = false
  } else if (!hasContent) {
    arr[targetIx] = createEmptyRow()
    return { links: arr, changed: true, targetIndex: targetIx }
  }

  arr[targetIx] = merged
  return { links: arr, changed: true, targetIndex: targetIx }
}

export function clearRoomMatrixCellInBucket(links, { contractorId, rowIndex }, options = {}) {
  const rowNum = Number(rowIndex)
  if (!Number.isFinite(rowNum) || rowNum < 1 || rowNum > ROOM_MATRIX_ROW_COUNT) {
    return { links: stripLegacyMatrixDummyRows(links), changed: false, targetIndex: -1 }
  }

  const createEmptyRow = options.createEmptyRow || defaultEmptyLinkRow
  const arr = stripLegacyMatrixDummyRows(links)
  const cid = String(contractorId)
  let targetIx = -1

  for (let i = 0; i < arr.length; i++) {
    const row = arr[i]
    if (isMatrixDummyRow(row)) continue
    if (contractorIdMatches(row, cid) && matrixRowTag(row) === rowNum) {
      targetIx = i
      break
    }
  }

  if (targetIx < 0) {
    const contractorIndices = collectContractorLinkIndices(arr, cid)
    if (contractorIndices[rowNum - 1] !== undefined) {
      targetIx = contractorIndices[rowNum - 1]
    }
  }

  if (targetIx < 0) {
    return { links: arr, changed: false, targetIndex: -1 }
  }

  arr[targetIx] = createEmptyRow()
  return { links: arr, changed: true, targetIndex: targetIx }
}

/**
 * @param {object} opts
 * @param {number} opts.roomOrder
 * @param {Array} opts.links
 * @param {ReturnType<typeof buildSpecialContractorColumnMap>} opts.columnMap
 * @param {Map<string, string>|Record<string, string>} opts.templateByCode
 */
export function buildRoomMatrixView({ roomOrder, links, columnMap, templateByCode }) {
  const lookupTemplate = (code) => {
    const nk = normalizeExternalCode(code)
    if (!nk) return ''
    if (templateByCode instanceof Map) return String(templateByCode.get(nk) ?? '').trim()
    return String(templateByCode?.[nk] ?? '').trim()
  }

  const cleanLinks = stripLegacyMatrixDummyRows(links)

  const columns = SPECIAL_COLUMN_KEYS.map((colKey) => {
    const contractorId = columnMap.columns[colKey]
    const enabled = Boolean(contractorId)
    const cells = []
    if (enabled) {
      const { slots } = buildMatrixSlotsForContractor(cleanLinks, contractorId)
      for (let r = 0; r < ROOM_MATRIX_ROW_COUNT; r++) {
        const row = slots[r]
        const code = String(row?.external_code || '').trim()
        cells.push({
          rowIndex: r + 1,
          colKey,
          contractorId,
          payloadKey: cellToPayloadKey(colKey, roomOrder, r + 1),
          row,
          isDummy: isMatrixDummyRow(row) || (!code && !String(row?.content || '').trim()),
          templateInstruction: lookupTemplate(code),
          content: String(row?.content ?? ''),
          externalCode: code,
        })
      }
    } else {
      for (let r = 0; r < ROOM_MATRIX_ROW_COUNT; r++) {
        cells.push({
          rowIndex: r + 1,
          colKey,
          contractorId: null,
          enabled: false,
          isDummy: true,
          templateInstruction: '',
          content: '',
          externalCode: '',
        })
      }
    }
    return {
      colKey,
      contractorId,
      headerLabel: columnMap.headers[colKey] || '',
      enabled,
      cells,
    }
  })

  return { roomOrder, columns }
}
