const STORAGE_KEY = 'schedule_grid_filters_v4'
const LEGACY_STORAGE_KEY = 'schedule_grid_filters_v3'

export const SCHEDULE_GRID_SORT_KEYS = {
  CREATED_AT: 'created_at',
  ORDERED_ON: 'ordered_on',
  WORK_CODE: 'work_code',
}

/** 担当フィルター: 未入力（employee_id なし） */
export const SCHEDULE_GRID_EMPLOYEE_UNASSIGNED = '__unassigned__'

export function scheduleGridYearFromIso(value) {
  if (value == null || value === '') return null
  const text = String(value).trim()
  const match = text.match(/^(\d{4})/)
  if (match) return Number(match[1])
  const time = new Date(text).getTime()
  if (!Number.isFinite(time)) return null
  return new Date(time).getFullYear()
}

/** 最新トグル ON 時: 登録が新しい順の先頭 N 件 + 追加表示条件 */
export const SCHEDULE_GRID_LATEST_LIMIT = 150

export const SCHEDULE_GRID_LATEST_LIMIT_OPTIONS = [50, 100, 150, 300]

export function normalizeScheduleGridLatestLimit(value) {
  const n = Number(value)
  return SCHEDULE_GRID_LATEST_LIMIT_OPTIONS.includes(n) ? n : SCHEDULE_GRID_LATEST_LIMIT
}

export const SCHEDULE_GRID_LATEST_PAID_JKK_LABEL = '支払済'

export function defaultScheduleGridFilters() {
  return {
    mcIds: [],
    registrationYears: [],
    instructionYears: [],
    jkkStatusIds: [],
    employeeFilterValues: [],
    progressiveStatusIds: [],
    propertyNameQuery: '',
    sortKey: SCHEDULE_GRID_SORT_KEYS.CREATED_AT,
    sortAscending: true,
    /** true = 最新N件＋追加条件 / false = 全件（従来） */
    showLatestFilter: true,
    latestLimit: SCHEDULE_GRID_LATEST_LIMIT,
  }
}

function migrateLegacyScheduleGridFilters(parsed, sourceKey) {
  const next = { ...parsed }
  if (
    parsed.employeeId != null &&
    parsed.employeeId !== '' &&
    !Array.isArray(parsed.employeeFilterValues)
  ) {
    next.employeeFilterValues = [Number(parsed.employeeId)]
  }
  if (Array.isArray(parsed.orderYears) && !Array.isArray(parsed.registrationYears)) {
    if (sourceKey === 'schedule_grid_filters_v2') {
      next.registrationYears = parsed.orderYears
    } else {
      next.instructionYears = parsed.orderYears
    }
  }
  return next
}

function resolveHideCompletedProgressive(parsed) {
  if (typeof parsed.hideCompletedProgressive === 'boolean') {
    return parsed.hideCompletedProgressive
  }
  if (parsed.showCompletedProgressive === false) return true
  return false
}

function resolveHideKeyReturnProgressive(parsed) {
  if (typeof parsed.hideKeyReturnProgressive === 'boolean') {
    return parsed.hideKeyReturnProgressive
  }
  if (parsed.showKeyReturnProgressive === false) return true
  if (parsed.hideCompletedProgressive === true && parsed.showKeyReturnProgressive == null) {
    return true
  }
  return false
}

function normalizeProgressiveStatusIds(value) {
  if (!Array.isArray(value)) return []
  return value.map(Number).filter((n) => Number.isInteger(n))
}

/** チェックボックス絞り込み: 空または全選択 = 無効（全件表示） */
export function isScheduleGridMultiFilterActive(selected, allValues) {
  const all = [...new Set(allValues ?? [])]
  if (all.length === 0) return false
  const picked = selected ?? []
  if (picked.length === 0) return false
  const pickedSet = new Set(picked.map(String))
  if (all.every((value) => pickedSet.has(String(value)))) return false
  return true
}

/** 保存・適用時: 全選択は [] に正規化 */
export function normalizeScheduleGridMultiFilter(selected, allValues) {
  const all = [...new Set(allValues ?? [])]
  const picked = [...(selected ?? [])]
  if (all.length === 0 || picked.length === 0) return []
  const pickedSet = new Set(picked.map(String))
  if (all.every((value) => pickedSet.has(String(value)))) return []
  return picked
}

/** モーダル表示: 未設定 [] は全選択として見せる */
export function expandScheduleGridMultiFilterForModal(stored, allValues) {
  const all = [...new Set(allValues ?? [])]
  const picked = stored ?? []
  if (picked.length === 0) return [...all]
  return [...picked]
}

/** 適用: 0件選択は全選択扱い → [] */
export function applyScheduleGridMultiFilter(applied, allValues) {
  return normalizeScheduleGridMultiFilter(applied, allValues)
}

export function sanitizeScheduleGridFilters(filters, optionValues = {}) {
  const mcAll = optionValues.mcIds ?? []
  const registrationAll = optionValues.registrationYears ?? []
  const instructionAll = optionValues.instructionYears ?? []
  const jkkAll = optionValues.jkkStatusIds ?? []
  const progressiveAll = optionValues.progressiveStatusIds ?? []
  const employeeAll = optionValues.employeeFilterValues ?? []

  const next = {
    ...filters,
    mcIds: normalizeScheduleGridMultiFilter(filters.mcIds, mcAll)
      .map(Number)
      .filter((n) => Number.isInteger(n)),
    registrationYears: normalizeScheduleGridMultiFilter(filters.registrationYears, registrationAll)
      .map(Number)
      .filter((n) => Number.isInteger(n)),
    instructionYears: normalizeScheduleGridMultiFilter(filters.instructionYears, instructionAll)
      .map(Number)
      .filter((n) => Number.isInteger(n)),
    jkkStatusIds: normalizeScheduleGridMultiFilter(filters.jkkStatusIds, jkkAll)
      .map(Number)
      .filter((n) => Number.isInteger(n)),
    progressiveStatusIds: normalizeProgressiveStatusIds(
      normalizeScheduleGridMultiFilter(filters.progressiveStatusIds, progressiveAll),
    ),
    employeeFilterValues: normalizeScheduleGridMultiFilter(
      filters.employeeFilterValues,
      employeeAll,
    ),
  }

  if (next.showLatestFilter === true) {
    return resetScheduleGridLatestLockedFilters(next)
  }

  return next
}

export function resetScheduleGridFiltersToSelectAll(filters) {
  return {
    ...filters,
    registrationYears: [],
    instructionYears: [],
    jkkStatusIds: [],
    progressiveStatusIds: [],
    employeeFilterValues: [],
    propertyNameQuery: '',
    showLatestFilter: true,
  }
}

/** 最新トグル ON 時に無効化するフィルター（全選択 = []） */
export function resetScheduleGridLatestLockedFilters(filters) {
  return {
    ...filters,
    registrationYears: [],
    instructionYears: [],
    jkkStatusIds: [],
    progressiveStatusIds: [],
  }
}

export function isScheduleGridLatestLockedFilterKind(kind) {
  return kind === 'instructionYear'
    || kind === 'jkk'
    || kind === 'progressive'
    || kind === 'registrationYear'
}

/** v3 の完了/鍵返トグルを v4 の工事チェックボックスへ移行 */
export function migrateLegacyProgressiveHideFilters(
  filters,
  progressiveStatuses,
  constructionCompletedIds,
  keyReturnIds,
) {
  const next = { ...filters }
  if (normalizeProgressiveStatusIds(next.progressiveStatusIds).length > 0) {
    next.progressiveStatusIds = normalizeProgressiveStatusIds(next.progressiveStatusIds)
    delete next.hideCompletedProgressive
    delete next.hideKeyReturnProgressive
    return next
  }

  const hideCompleted = next.hideCompletedProgressive === true
  const hideKeyReturn = next.hideKeyReturnProgressive === true
  delete next.hideCompletedProgressive
  delete next.hideKeyReturnProgressive

  if (!hideCompleted && !hideKeyReturn) {
    next.progressiveStatusIds = []
    return next
  }

  const excluded = new Set()
  if (hideCompleted) {
    ;(constructionCompletedIds || []).forEach((id) => excluded.add(Number(id)))
  }
  if (hideKeyReturn) {
    ;(keyReturnIds || []).forEach((id) => excluded.add(Number(id)))
  }
  const allIds = (progressiveStatuses || [])
    .filter((st) => st.is_active !== false)
    .map((st) => Number(st.id))
    .filter((id) => Number.isInteger(id))
  next.progressiveStatusIds = allIds.filter((id) => !excluded.has(id))
  return next
}

export function loadScheduleGridFilters() {
  try {
    let raw = localStorage.getItem(STORAGE_KEY)
    let sourceKey = STORAGE_KEY
    if (!raw) {
      raw = localStorage.getItem(LEGACY_STORAGE_KEY)
      sourceKey = LEGACY_STORAGE_KEY
    }
    if (!raw) {
      raw = localStorage.getItem('schedule_grid_filters_v2')
      sourceKey = 'schedule_grid_filters_v2'
    }
    if (!raw) {
      raw = localStorage.getItem('schedule_grid_filters_v1')
      sourceKey = 'schedule_grid_filters_v1'
    }
    if (!raw) return defaultScheduleGridFilters()
    const parsed = migrateLegacyScheduleGridFilters(JSON.parse(raw), sourceKey)
    const employeeFilterValues = Array.isArray(parsed.employeeFilterValues)
      ? parsed.employeeFilterValues.map((value) => {
          if (value === SCHEDULE_GRID_EMPLOYEE_UNASSIGNED) return SCHEDULE_GRID_EMPLOYEE_UNASSIGNED
          const n = Number(value)
          return Number.isInteger(n) ? n : null
        }).filter((value) => value != null)
      : []
    const progressiveStatusIds = normalizeProgressiveStatusIds(parsed.progressiveStatusIds)
    const loaded = {
      ...defaultScheduleGridFilters(),
      mcIds: Array.isArray(parsed.mcIds) ? parsed.mcIds.map(Number) : [],
      registrationYears: Array.isArray(parsed.registrationYears)
        ? parsed.registrationYears.map(Number).filter((n) => Number.isInteger(n))
        : [],
      instructionYears: Array.isArray(parsed.instructionYears)
        ? parsed.instructionYears.map(Number).filter((n) => Number.isInteger(n))
        : [],
      jkkStatusIds: Array.isArray(parsed.jkkStatusIds) ? parsed.jkkStatusIds.map(Number) : [],
      employeeFilterValues,
      progressiveStatusIds,
      propertyNameQuery: String(parsed.propertyNameQuery ?? parsed.housingNameQuery ?? ''),
      sortKey: normalizeScheduleGridSortKey(parsed.sortKey),
      sortAscending: parsed.sortAscending !== false,
      showLatestFilter: resolveShowLatestFilter(parsed),
      latestLimit: normalizeScheduleGridLatestLimit(parsed.latestLimit),
    }
    if (sourceKey === LEGACY_STORAGE_KEY && progressiveStatusIds.length === 0) {
      loaded.hideCompletedProgressive = resolveHideCompletedProgressive(parsed)
      loaded.hideKeyReturnProgressive = resolveHideKeyReturnProgressive(parsed)
    }
    return loaded
  } catch {
    return defaultScheduleGridFilters()
  }
}

export function saveScheduleGridFilters(filters) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify({
    mcIds: filters.mcIds || [],
    registrationYears: filters.registrationYears || [],
    instructionYears: filters.instructionYears || [],
    jkkStatusIds: filters.jkkStatusIds || [],
    employeeFilterValues: filters.employeeFilterValues || [],
    progressiveStatusIds: normalizeProgressiveStatusIds(filters.progressiveStatusIds),
    propertyNameQuery: String(filters.propertyNameQuery ?? ''),
    sortKey: normalizeScheduleGridSortKey(filters.sortKey),
    sortAscending: filters.sortAscending !== false,
    showLatestFilter: filters.showLatestFilter !== false,
    latestLimit: normalizeScheduleGridLatestLimit(filters.latestLimit),
  }))
}

function resolveShowLatestFilter(parsed) {
  if (typeof parsed.showLatestFilter === 'boolean') return parsed.showLatestFilter
  if (typeof parsed.showAllScheduleItems === 'boolean') return parsed.showAllScheduleItems === false
  return true
}

function normalizeScheduleGridSortKey(value) {
  const key = String(value ?? '').trim()
  if (Object.values(SCHEDULE_GRID_SORT_KEYS).includes(key)) return key
  return SCHEDULE_GRID_SORT_KEYS.CREATED_AT
}

export function countActiveScheduleGridFilters(filters, optionValues = {}) {
  let count = 0
  if (isScheduleGridMultiFilterActive(filters.mcIds, optionValues.mcIds)) count += 1
  if (isScheduleGridMultiFilterActive(filters.registrationYears, optionValues.registrationYears)) {
    count += 1
  }
  if (isScheduleGridMultiFilterActive(filters.instructionYears, optionValues.instructionYears)) {
    count += 1
  }
  if (isScheduleGridMultiFilterActive(filters.jkkStatusIds, optionValues.jkkStatusIds)) count += 1
  if (
    isScheduleGridMultiFilterActive(filters.progressiveStatusIds, optionValues.progressiveStatusIds)
  ) {
    count += 1
  }
  if (
    isScheduleGridMultiFilterActive(filters.employeeFilterValues, optionValues.employeeFilterValues)
  ) {
    count += 1
  }
  if (String(filters.propertyNameQuery ?? '').trim()) count += 1
  return count
}

function scheduleGridItemLatestSortKey(item) {
  return item?.schedule_created_at ?? item?.ordered_on ?? ''
}

function isScheduleGridKeyReturnProgressive(item, keyReturnProgressiveStatusIds) {
  const statusId = Number(item?.large_progressive_status_id)
  if (!Number.isInteger(statusId)) return false
  return (keyReturnProgressiveStatusIds || []).includes(statusId)
}

function isScheduleGridJkkStatusIn(item, jkkStatusIds) {
  const statusId = Number(item?.large_jkk_status_id)
  if (!Number.isInteger(statusId)) return false
  return (jkkStatusIds || []).includes(statusId)
}

/** 最新トグル ON: 最新N件（常に表示）∪ N件外で（支払済以外 かつ 鍵返却以外） */
export function applyScheduleGridLatestLimit(
  items,
  filters,
  {
    keyReturnProgressiveStatusIds = [],
    paidJkkStatusIds = [],
  } = {},
) {
  if (filters?.showLatestFilter !== true) return items || []

  const list = items || []
  const limit = normalizeScheduleGridLatestLimit(filters.latestLimit)

  const sortedByLatest = [...list].sort((a, b) => {
    const cmp = String(scheduleGridItemLatestSortKey(b)).localeCompare(
      String(scheduleGridItemLatestSortKey(a)),
    )
    if (cmp !== 0) return cmp
    return String(b.work_id).localeCompare(String(a.work_id))
  })

  const topIds = new Set(
    sortedByLatest
      .slice(0, limit)
      .map((item) => String(item.work_id)),
  )

  return list.filter((item) => {
    const wid = String(item.work_id)
    if (topIds.has(wid)) return true

    if (isScheduleGridJkkStatusIn(item, paidJkkStatusIds)) return false
    return !isScheduleGridKeyReturnProgressive(item, keyReturnProgressiveStatusIds)
  })
}

function employeeFilterMatches(item, employeeFilterValues) {
  const selected = employeeFilterValues || []
  if (selected.length === 0) return true
  const employeeId = item?.employee_id
  const isUnassigned = employeeId == null || employeeId === ''
  return selected.some((value) => {
    if (value === SCHEDULE_GRID_EMPLOYEE_UNASSIGNED) return isUnassigned
    return Number(employeeId) === Number(value)
  })
}

/** 進捗グリッド一覧のクライアント側絞り込み */
export function filterScheduleGridItems(
  items,
  filters,
  propertySearchKeyFn,
) {
  const mcIds = filters?.mcIds || []
  const registrationYears = filters?.registrationYears || []
  const instructionYears = filters?.instructionYears || []
  const jkkStatusIds = filters?.jkkStatusIds || []
  const progressiveStatusIds = normalizeProgressiveStatusIds(filters?.progressiveStatusIds)
  const employeeFilterValues = filters?.employeeFilterValues || []
  const propertyQuery = String(filters?.propertyNameQuery ?? '').trim()

  return (items || []).filter((item) => {
    if (mcIds.length > 0 && !mcIds.includes(Number(item.mc_id))) return false
    if (registrationYears.length > 0) {
      const year = scheduleGridYearFromIso(item.schedule_created_at)
      if (year == null || !registrationYears.includes(year)) return false
    }
    if (instructionYears.length > 0) {
      const year = scheduleGridYearFromIso(item.ordered_on)
      if (year == null || !instructionYears.includes(year)) return false
    }
    if (jkkStatusIds.length > 0 && !jkkStatusIds.includes(Number(item.large_jkk_status_id))) {
      return false
    }
    if (
      progressiveStatusIds.length > 0
      && !progressiveStatusIds.includes(Number(item.large_progressive_status_id))
    ) {
      return false
    }
    if (!employeeFilterMatches(item, employeeFilterValues)) return false
    if (propertyQuery) {
      const key = propertySearchKeyFn ? propertySearchKeyFn(item) : ''
      if (!key.toLowerCase().includes(propertyQuery.toLowerCase())) return false
    }
    return true
  })
}
