<template>
  <Teleport to="body">
    <div
      v-if="state.open"
      class="app-dialog-overlay"
      role="presentation"
      @click.self="onOverlayClick"
    >
      <div
        class="app-dialog-content"
        :class="{ 'app-dialog-content--wide': isWideDialogBody }"
        role="dialog"
        aria-modal="true"
        :aria-labelledby="titleId"
        @click.stop
      >
        <div class="app-dialog-header" :class="headerClass">
          <h2 :id="titleId">{{ state.title }}</h2>
        </div>
        <div
          class="app-dialog-body"
          :class="{
            'app-dialog-body--dismissible': isSuccessAlert,
            'app-dialog-body--custom': isWideDialogBody
          }"
          @click="onSuccessBodyClick"
        >
          <div v-if="state.bodyKind === 'loading'" class="app-dialog-loading">
            <span class="app-dialog-spinner" aria-hidden="true"></span>
            <p class="app-dialog-message app-dialog-message--loading">{{ state.message }}</p>
          </div>
          <template v-else-if="isPreformattedText">
            <p
              v-if="state.message"
              class="app-dialog-message app-dialog-message--preview-header"
              :class="state.messageClass"
            >
              {{ state.message }}
            </p>
            <pre class="app-dialog-preformatted">{{ state.preview.text }}</pre>
          </template>
          <template v-else-if="isGridContentList && state.preview?.rows?.length">
            <div
              v-for="(row, idx) in state.preview.rows"
              :key="`grid-content-${idx}`"
              class="app-dialog-preview-line"
            >
              <span class="app-dialog-preview-bullet">・</span>
              <span class="app-dialog-item-code">{{ row.code }}</span>
              <span class="app-dialog-item-desc app-dialog-item-desc--wrap">{{ row.content }}</span>
            </div>
          </template>
          <template v-else-if="isMaterialLaborPreview && state.preview">
            <template v-if="state.preview.items?.length">
              <p
                v-if="state.message"
                class="app-dialog-message app-dialog-message--preview-header"
                :class="state.messageClass"
              >
                {{ state.message }}
              </p>
              <div
                v-for="(row, idx) in state.preview.items"
                :key="`item-${idx}`"
                class="app-dialog-preview-line"
              >
                <span class="app-dialog-preview-bullet">・</span>
                <span class="app-dialog-item-code">{{ displayPreviewItemCode(row, idx) }}</span>
                <span
                  class="app-dialog-item-type"
                  :class="[
                    getPriceTypeDisplayClass(row.priceType) || undefined,
                    { 'price-type--user': row.priceType === 'ユーザー' }
                  ]"
                >
                  {{ row.priceType }}
                </span>
                <span class="app-dialog-item-desc">{{ row.description }}</span>
                <span class="app-dialog-item-qty">{{ formatPreviewQuantity(row.quantity) }}</span>
              </div>
              <fieldset
                v-if="state.choiceOptions?.length"
                class="app-dialog-choice-group"
              >
                <legend class="app-dialog-choice-legend">コードの登録方法</legend>
                <label
                  v-for="option in state.choiceOptions"
                  :key="option.value"
                  class="app-dialog-choice-option"
                >
                  <input
                    v-model="state.choiceValue"
                    type="radio"
                    class="app-dialog-choice-radio"
                    :value="option.value"
                  />
                  <span>{{ option.label }}</span>
                </label>
              </fieldset>
            </template>
            <template v-else>
              <p class="app-dialog-preview-section-label">変更前</p>
              <div
                v-for="(row, idx) in state.preview.before"
                :key="`before-${idx}`"
                class="app-dialog-preview-line"
              >
                <span class="app-dialog-preview-bullet">・</span>
                <span class="app-dialog-item-code">{{ row.code }}</span>
                <span
                  class="app-dialog-item-type"
                  :class="getPriceTypeDisplayClass(row.priceType) || undefined"
                >
                  {{ row.priceType }}
                </span>
                <span class="app-dialog-item-desc">{{ row.description }}</span>
                <span class="app-dialog-item-qty">{{ formatPreviewQuantity(row.quantity) }}</span>
              </div>
              <p class="app-dialog-preview-section-label">変更後</p>
              <div
                v-for="(row, idx) in state.preview.after"
                :key="`after-${idx}`"
                class="app-dialog-preview-line"
              >
                <span class="app-dialog-preview-bullet">・</span>
                <span class="app-dialog-item-code">{{ row.code }}</span>
                <span
