                  :class="getPriceTypeDisplayClass(row.priceType) || undefined"
                >
                  {{ row.priceType }}
                </span>
                <span class="app-dialog-item-desc">{{ row.description }}</span>
                <span class="app-dialog-item-qty">{{ formatPreviewQuantity(row.quantity) }}</span>
              </div>
            </template>
          </template>
          <p
            v-if="state.message && !(isMaterialLaborPreview && state.preview?.items?.length) && !isPreformattedText"
            class="app-dialog-message"
            :class="[
              { 'app-dialog-message--custom-footer': isWideDialogBody },
              { 'app-dialog-message--with-choice': showTextChoiceOptions },
              state.messageClass
            ]"
          >
            {{ state.message }}
          </p>
          <fieldset
            v-if="showTextChoiceOptions"
            class="app-dialog-choice-group app-dialog-choice-group--text"
          >
            <label
              v-for="option in state.choiceOptions"
              :key="option.value"
              class="app-dialog-choice-option"
            >
              <input
                v-model="state.choiceValue"
                type="radio"
                class="app-dialog-choice-radio"
                :value="option.value"
              />
              <span class="app-dialog-choice-label-block">
                <span :class="{ 'app-dialog-choice-label--primary': option.labelPrimary }">{{ option.label }}</span>
                <span v-if="option.note" class="app-dialog-choice-note">{{ option.note }}</span>
              </span>
            </label>
          </fieldset>
        </div>
        <div v-if="!isSuccessAlert && state.bodyKind !== 'loading'" class="app-dialog-footer">
          <template v-if="state.type === 'confirm'">
            <button type="button" class="app-dialog-btn app-dialog-btn-secondary" @click="onCancel">
              {{ state.cancelText }}
            </button>
            <button type="button" class="app-dialog-btn app-dialog-btn-primary" @click="onOk">
              {{ state.confirmText }}
            </button>
          </template>
          <button
            v-else
            type="button"
            class="app-dialog-btn app-dialog-btn-primary"
            @click="onOk"
          >
            {{ state.okText }}
          </button>
        </div>
