</template>

<script setup>
import { computed } from 'vue'
import { getPriceTypeDisplayClass } from '../utils/materialLaborAJudge.js'

const props = defineProps({
  state: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['ok', 'cancel'])

const titleId = computed(() => 'app-dialog-title')

const isMaterialLaborPreview = computed(
  () => props.state?.bodyKind === 'materialLaborPreview' && props.state?.preview
)

const isGridContentList = computed(
  () => props.state?.bodyKind === 'gridContentList' && props.state?.preview?.rows?.length
)

const isPreformattedText = computed(
  () => props.state?.bodyKind === 'preformattedText' && props.state?.preview?.text != null
)

const isWideDialogBody = computed(
  () => isMaterialLaborPreview.value || isGridContentList.value || isPreformattedText.value
)

const headerClass = computed(() => {
  const tone = props.state?.titleTone || 'neutral'
  return {
    'app-dialog-header--success': tone === 'success',
    'app-dialog-header--error': tone === 'error',
    'app-dialog-header--confirm': tone === 'confirm',
    'app-dialog-header--interrupt': tone === 'interrupt',
    'app-dialog-header--neutral': tone === 'neutral'
  }
})

const isSuccessAlert = computed(() =>
  props.state?.type === 'alert' && props.state?.titleTone === 'success'
)

const showTextChoiceOptions = computed(
  () =>
    props.state?.type === 'confirm' &&
    props.state?.bodyKind === 'text' &&
    props.state?.choiceOptions?.length
)

function formatPreviewQuantity(qty) {
  if (qty == null || qty === '') return '-'
  return String(qty)
}

function displayPreviewItemCode(row, idx) {
  if (
    idx === 0 &&
    props.state?.choiceOptions?.length &&
    props.state?.preview?.userExternalCodeChoice
  ) {
    if (props.state.choiceValue === 'copy') {
      return props.state.preview.userExternalCodeChoice.sourceCode || '-'
    }
    if (props.state.choiceValue === 'assign_nu') {
      return '（自動採番）'
    }
  }
  return row.code
}

function onOk() {
  emit('ok')
}

function onCancel() {
  emit('cancel')
}

function onOverlayClick() {
  // エラーは OK ボタンのみで閉じる（外側タップでは閉じない）
  if (props.state.type === 'alert' && props.state.titleTone !== 'error') {
    emit('ok')
  }
}

function onSuccessBodyClick() {
  if (isSuccessAlert.value) {
    emit('ok')
  }
}
</script>

