<template>
  <div v-if="isOpen" class="modal-overlay" @click.self="handleCancel">
    <div class="modal-box" @click.stop>
      <div class="modal-header">
        <h3>絞り込み</h3>
        <button type="button" class="close-btn" @click="handleCancel">✕</button>
      </div>
      <div class="modal-body">
        <section class="settings-section">
          <div class="settings-section-head">
            <h4>MC</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAll('mcIds', mcOptions)">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('mcIds')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in mcOptions" :key="`mc-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.mcIds.includes(option.value)" @change="toggleNumber('mcIds', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section" :class="{ 'settings-section--disabled': showLatestFilter }">
          <div class="settings-section-head">
            <h4>年度</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="selectAll('instructionYears', instructionYearOptions)">すべて選択</button>
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="clearSection('instructionYears')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in instructionYearOptions" :key="`iy-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.instructionYears.includes(option.value)" :disabled="showLatestFilter" @change="toggleNumber('instructionYears', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section" :class="{ 'settings-section--disabled': showLatestFilter }">
          <div class="settings-section-head">
            <h4>状態</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="selectAll('jkkStatusIds', jkkStatusOptions)">すべて選択</button>
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="clearSection('jkkStatusIds')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in jkkStatusOptions" :key="`jk-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.jkkStatusIds.includes(option.value)" :disabled="showLatestFilter" @change="toggleNumber('jkkStatusIds', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section" :class="{ 'settings-section--disabled': showLatestFilter }">
          <div class="settings-section-head">
            <h4>工事</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="selectAll('progressiveStatusIds', progressiveStatusOptions)">すべて選択</button>
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="clearSection('progressiveStatusIds')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in progressiveStatusOptions" :key="`pg-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.progressiveStatusIds.includes(option.value)" :disabled="showLatestFilter" @change="toggleNumber('progressiveStatusIds', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section" :class="{ 'settings-section--disabled': showLatestFilter }">
          <div class="settings-section-head">
            <h4>登録</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="selectAll('registrationYears', registrationYearOptions)">すべて選択</button>
              <button type="button" class="link-btn" :disabled="showLatestFilter" @click="clearSection('registrationYears')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in registrationYearOptions" :key="`ry-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.registrationYears.includes(option.value)" :disabled="showLatestFilter" @change="toggleNumber('registrationYears', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section">
          <h4>物件名</h4>
          <input
            v-model="draft.propertyNameQuery"
            type="search"
            class="property-search"
            placeholder="物件名で検索"
          />
        </section>

        <section class="settings-section">
          <div class="settings-section-head">
            <h4>担当</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAllEmployees">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('employeeFilterValues')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in employeeOptions" :key="`emp-${option.value}`" class="option-item">
              <input
                type="checkbox"
                :checked="draft.employeeFilterValues.includes(option.value)"
                @change="toggleEmployee(option.value)"
              />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>
      </div>
      <div class="modal-footer">
        <button type="button" class="cancel-btn" @click="handleCancel">キャンセル</button>
        <button type="button" class="apply-btn" @click="handleApply">適用</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { reactive, watch } from 'vue'
import {
  applyScheduleGridMultiFilter,
  expandScheduleGridMultiFilterForModal,
  resetScheduleGridLatestLockedFilters,
} from '../utils/scheduleGridFilters.js'

const props = defineProps({
  isOpen: { type: Boolean, default: false },
  filters: { type: Object, required: true },
  showLatestFilter: { type: Boolean, default: false },
  mcOptions: { type: Array, default: () => [] },
  registrationYearOptions: { type: Array, default: () => [] },
  instructionYearOptions: { type: Array, default: () => [] },
  jkkStatusOptions: { type: Array, default: () => [] },
  progressiveStatusOptions: { type: Array, default: () => [] },
  employeeOptions: { type: Array, default: () => [] },
})

const emit = defineEmits(['close', 'apply'])

const draft = reactive({
  mcIds: [],
  registrationYears: [],
  instructionYears: [],
  jkkStatusIds: [],
  progressiveStatusIds: [],
  employeeFilterValues: [],
  propertyNameQuery: '',
})

function cloneFilters(source) {
  return {
    mcIds: [...(source.mcIds || [])],
    registrationYears: [...(source.registrationYears || [])],
    instructionYears: [...(source.instructionYears || [])],
    jkkStatusIds: [...(source.jkkStatusIds || [])],
    progressiveStatusIds: [...(source.progressiveStatusIds || [])].map(Number).filter((n) => Number.isInteger(n)),
    employeeFilterValues: [...(source.employeeFilterValues || [])],
    propertyNameQuery: source.propertyNameQuery ?? '',
  }
}

function optionValues(options) {
  return (options || []).map((option) => option.value)
}

function expandDraftFilters(source) {
  const base = cloneFilters(source)
  base.mcIds = expandScheduleGridMultiFilterForModal(base.mcIds, optionValues(props.mcOptions))
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.instructionYears = expandScheduleGridMultiFilterForModal(
    base.instructionYears,
    optionValues(props.instructionYearOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.jkkStatusIds = expandScheduleGridMultiFilterForModal(
    base.jkkStatusIds,
    optionValues(props.jkkStatusOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.progressiveStatusIds = expandScheduleGridMultiFilterForModal(
    base.progressiveStatusIds,
    optionValues(props.progressiveStatusOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.registrationYears = expandScheduleGridMultiFilterForModal(
    base.registrationYears,
    optionValues(props.registrationYearOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.employeeFilterValues = expandScheduleGridMultiFilterForModal(
    base.employeeFilterValues,
    optionValues(props.employeeOptions),
  )
  return base
}

function normalizeDraftFilters(source) {
  const base = cloneFilters(source)
  base.mcIds = applyScheduleGridMultiFilter(base.mcIds, optionValues(props.mcOptions))
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.instructionYears = applyScheduleGridMultiFilter(
    base.instructionYears,
    optionValues(props.instructionYearOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.jkkStatusIds = applyScheduleGridMultiFilter(base.jkkStatusIds, optionValues(props.jkkStatusOptions))
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.progressiveStatusIds = applyScheduleGridMultiFilter(
    base.progressiveStatusIds,
    optionValues(props.progressiveStatusOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.registrationYears = applyScheduleGridMultiFilter(
    base.registrationYears,
    optionValues(props.registrationYearOptions),
  )
    .map(Number)
    .filter((n) => Number.isInteger(n))
  base.employeeFilterValues = applyScheduleGridMultiFilter(
    base.employeeFilterValues,
    optionValues(props.employeeOptions),
  )
  return base
}

watch(
  () => [props.isOpen, props.filters],
  () => {
    if (!props.isOpen) return
    Object.assign(draft, expandDraftFilters(props.filters))
  },
  { immediate: true, deep: true },
)

function toggleNumber(key, value) {
  const num = Number(value)
  const list = draft[key]
  const index = list.indexOf(num)
  if (index >= 0) list.splice(index, 1)
  else list.push(num)
}

function toggleEmployee(value) {
  const list = draft.employeeFilterValues
  const index = list.indexOf(value)
  if (index >= 0) list.splice(index, 1)
  else list.push(value)
}

function selectAll(key, options) {
  draft[key] = options.map((option) => Number(option.value)).filter((n) => Number.isInteger(n))
}

function selectAllEmployees() {
  draft.employeeFilterValues = props.employeeOptions.map((option) => option.value)
}

function clearSection(key) {
  draft[key] = []
}

function handleCancel() {
  emit('close')
}

function handleApply() {
  const normalized = normalizeDraftFilters(draft)
  emit('apply', props.showLatestFilter ? resetScheduleGridLatestLockedFilters({
    ...props.filters,
    ...normalized,
    showLatestFilter: true,
  }) : normalized)
  emit('close')
}
</script>

