/** 段階補修未設定時のデフォルト（master_large_steps.id=4 / key=all） */
export const DEFAULT_LARGE_STEP_ID = 4
export const DEFAULT_LARGE_STEP_BASE_KEY = 'all'

/** セレクト key → 検査 ON 時の master key */
export const LARGE_STEP_BASE_TO_INSPECTION_KEY = {
  secondary: 'inspection_secondary',
  all: 'inspection_all',
  secondary_silver: 'inspection_secondary_silver',
  all_silver: 'inspection_all_silver',
  secondary_wheelchair: 'inspection_secondary_wheelchair',
  all_wheelchair: 'inspection_all_wheelchair',
}

/** inspection key → セレクト key */
export const LARGE_STEP_INSPECTION_TO_BASE_KEY = Object.fromEntries(
  Object.entries(LARGE_STEP_BASE_TO_INSPECTION_KEY).map(([base, inspection]) => [
    inspection,
    base,
  ]),
)

export function largeStepKeySupportsInspection(key) {
  if (!key) return false
  return Object.prototype.hasOwnProperty.call(LARGE_STEP_BASE_TO_INSPECTION_KEY, String(key))
}

export function resolveLargeStepLookupKey(baseKey, isInspection) {
  if (!baseKey) return null
  const k = String(baseKey)
  if (isInspection) {
    return LARGE_STEP_BASE_TO_INSPECTION_KEY[k] ?? null
  }
  return k
}

export function largeStepBaseKeyFromRow(row) {
  if (!row?.key) return null
  const key = String(row.key)
  if (row.is_inspection) {
    return LARGE_STEP_INSPECTION_TO_BASE_KEY[key] ?? null
  }
  return key
}

export function filterLargeStepBaseOptions(steps) {
  return (steps || [])
    .filter((s) => s?.is_active !== false && !s?.is_inspection)
    .sort((a, b) => Number(a.sort_order) - Number(b.sort_order))
}

export function resolveLargeStepId(steps, baseKey, isInspection) {
  const effectiveKey = baseKey || DEFAULT_LARGE_STEP_BASE_KEY
  const lookupKey = resolveLargeStepLookupKey(effectiveKey, Boolean(isInspection))
  if (!lookupKey) return DEFAULT_LARGE_STEP_ID
  const row = (steps || []).find(
    (s) => s?.is_active !== false && String(s.key) === lookupKey,
  )
  return row?.id ?? DEFAULT_LARGE_STEP_ID
}

export function largeStepUiFromId(steps, stepId) {
  if (stepId == null || stepId === '') {
    return { key: DEFAULT_LARGE_STEP_BASE_KEY, isInspection: false }
  }
  const row = (steps || []).find((s) => Number(s.id) === Number(stepId))
  if (!row) {
    return { key: DEFAULT_LARGE_STEP_BASE_KEY, isInspection: false }
  }
  const key = largeStepBaseKeyFromRow(row)
  if (!key) {
    return { key: DEFAULT_LARGE_STEP_BASE_KEY, isInspection: false }
  }
  return {
    key,
    isInspection: Boolean(row.is_inspection),
  }
}

export function formatLargeStepLabel(label) {
  return String(label ?? '').trim()
}

/** セレクト・同一住戸など UI 表示用: 空は '-' */
export function formatLargeStepLabelDisplay(label) {
  const text = formatLargeStepLabel(label)
  return text || '-'
}
