import { normalizeExternalCode, toNumberOrZero } from './instructionMerge'

/** 比較データの DB 保存時のみ除外（0〜1000 の純数字）。比較タブの表示組み立てでは含める */
export function shouldSkipComparisonCode(code) {
  const c = String(code ?? '').trim()
  if (!/^\d+$/.test(c)) return false
  const n = Number(c)
  return Number.isInteger(n) && n >= 0 && n <= 1000
}

function numOrNull(v) {
  if (v === null || v === undefined || v === '') return null
  const n = Number(v)
  return Number.isFinite(n) ? n : null
}

function decimalPlaces(v) {
  const s = String(v ?? '').trim().toLowerCase()
  if (!s || s.includes('e')) return 0
  const ix = s.indexOf('.')
  return ix >= 0 ? s.length - ix - 1 : 0
}

function addDecimal(a, b) {
  const n1 = numOrNull(a) ?? 0
  const n2 = numOrNull(b) ?? 0
  const scale = 10 ** Math.min(Math.max(decimalPlaces(a), decimalPlaces(b)), 10)
  return (Math.round(n1 * scale) + Math.round(n2 * scale)) / scale
}

/**
 * 指示タブ結合行からコード別に数量を合算し、初出の原本列テキストを保持する。
 * @param {Array<Record<string, unknown>>} instructionMergeRows
 * @returns {{ qtyByNorm: Map<string, number>, firstTemplateInstrByNorm: Map<string, string | null> }}
 */
function aggregateInstructionByNormCode(instructionMergeRows) {
  /** @type {Map<string, number>} */
  const qtyByNorm = new Map()
  /** @type {Map<string, string | null>} */
  const firstTemplateInstrByNorm = new Map()

  for (const r of instructionMergeRows || []) {
    const nk = r?.normCode || normalizeExternalCode(r?.external_code)
    if (!nk) continue
    qtyByNorm.set(nk, addDecimal(qtyByNorm.get(nk) || 0, toNumberOrZero(r?.quantity)))
    if (!firstTemplateInstrByNorm.has(nk)) {
      const t = String(r?.templateInstruction ?? '').trim()
      firstTemplateInstrByNorm.set(nk, t ? t : null)
    }
  }
  return { qtyByNorm, firstTemplateInstrByNorm }
}

/**
 * ラージ請求アイテムを正規化コードで束ねる（同一コードは数量加算・sort_order は最小を採用）
 * @param {Array<Record<string, unknown>>} billingItems
 */
function mergeBillingItemsByNormCode(billingItems) {
  /** @type {Map<string, { external_code: string, quantity: number | null, sort_order: number | null, description: string | null }>} */
  const map = new Map()

  for (const b of billingItems || []) {
    const raw = String(b?.external_code ?? '').trim()
    if (!raw) continue
    const nk = normalizeExternalCode(raw)
    if (!nk) continue
    const q = numOrNull(b?.quantity)
    const so = b?.sort_order != null && b?.sort_order !== '' ? Number(b.sort_order) : null
    const desc = b?.description != null ? String(b.description) : null

    const cur = map.get(nk)
    if (!cur) {
      map.set(nk, {
        external_code: raw,
        quantity: q,
        sort_order: Number.isFinite(so) ? so : null,
        description: desc
      })
    } else {
      const q1 = cur.quantity
      const q2 = q
      if (q1 != null && q2 != null) cur.quantity = addDecimal(q1, q2)
      else if (q1 == null) cur.quantity = q2
      if (Number.isFinite(so) && (cur.sort_order == null || so < cur.sort_order)) {
        cur.sort_order = so
      }
    }
  }
  return map
}

/**
 * 既存比較行に修正数量が保存されており、かつ当時の見積／請求いずれかに数量が入っていた行だけ
 * 修正欄を引き継ぐ（新規組み立てでは空のまま）
 */
function shouldPrefillRequestQuantity(existing) {
  if (!existing) return false
  const rq = existing.request_quantity
  if (rq === null || rq === undefined || rq === '') return false
  if (String(rq).trim() === '') return false
  const hadStoredQty =
    numOrNull(existing.billing_quantity) !== null ||
    numOrNull(existing.aggregated_quantity) !== null
  return hadStoredQty
}

/**
 * 大口請求比較の「比較実行」を Edge の compare と同等にローカル組み立てする。
 *
 * @param {{
 *   billingItems: Array<Record<string, unknown>>,
 *   instructionMergeRows: Array<Record<string, unknown>>,
 *   existingComparisons: Array<Record<string, unknown>>
 * }} params
 */
export function buildLocalBillingComparisonResults({
  billingItems,
  instructionMergeRows,
  existingComparisons
}) {
  const existingMap = new Map(
    (existingComparisons || []).map((c) => [normalizeExternalCode(c.external_code), c])
  )

  const { qtyByNorm, firstTemplateInstrByNorm } = aggregateInstructionByNormCode(instructionMergeRows)
  const billingByNorm = mergeBillingItemsByNormCode(billingItems)

  /** @type {Array<Record<string, unknown>>} */
  const comparisonResults = []
  const processedCodes = new Set()

  for (const [nk, billing] of billingByNorm) {
    processedCodes.add(nk)

    const existing = existingMap.get(nk)
    const aggQty = qtyByNorm.has(nk) ? qtyByNorm.get(nk) : null
    const billQty = billing.quantity
    const isMatch = aggQty !== null && billQty !== null && aggQty === billQty
    const estimateInstruction = firstTemplateInstrByNorm.get(nk) ?? null
    const status = aggQty === null ? 'new_from_billing' : 'active'

    const prefill = shouldPrefillRequestQuantity(existing)
    const request_quantity = prefill ? numOrNull(existing.request_quantity) : null

    comparisonResults.push({
      external_code: billing.external_code,
      aggregated_quantity: aggQty,
      billing_quantity: billQty,
      billing_sort_order: billing.sort_order,
      billing_description: billing.description,
      estimate_instruction: estimateInstruction,
      request_quantity,
      status,
      is_match: isMatch,
      slots: []
    })
  }

  for (const [nk, aggTotal] of qtyByNorm) {
    if (processedCodes.has(nk)) continue
    processedCodes.add(nk)

    const existing = existingMap.get(nk)
    const estimateInstruction = firstTemplateInstrByNorm.get(nk) ?? null
    const prefill = shouldPrefillRequestQuantity(existing)
    const request_quantity = prefill ? numOrNull(existing.request_quantity) : null

    comparisonResults.push({
      external_code: nk,
      aggregated_quantity: aggTotal,
      billing_quantity: null,
      billing_sort_order: null,
      billing_description: null,
      estimate_instruction: estimateInstruction,
      request_quantity,
      status: 'pending_add',
      is_match: false,
      slots: []
    })
  }

  comparisonResults.sort((a, b) => {
    if (a.status === 'pending_add' && b.status !== 'pending_add') return 1
    if (a.status !== 'pending_add' && b.status === 'pending_add') return -1
    return (a.billing_sort_order ?? 9999) - (b.billing_sort_order ?? 9999)
  })

  return {
    comparisons: comparisonResults,
    estimate_count: qtyByNorm.size,
    billing_count: billingByNorm.size
  }
}

function parseComparisonQuantity(value) {
  if (value === null || value === undefined || value === '') return null
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

/** 修正数量入力が有効な数値か（空文字・未入力は false） */
export function comparisonRequestQuantityHasNumericValue(item) {
  const v = item?.request_quantity
  if (v === null || v === undefined) return false
  const s = String(v).trim()
  if (s === '') return false
  return Number.isFinite(Number(s))
}

/**
 * 算出金額用の数量: 修正入力 → 公(comp-value)。見は含めない。
 */
export function getComparisonCalcQuantity(item) {
  if (comparisonRequestQuantityHasNumericValue(item)) {
    return parseComparisonQuantity(item.request_quantity)
  }
  return parseComparisonQuantity(item?.billing_quantity)
}

/** 単価×数量の行金額（端数処理＝円単位四捨五入） */
export function roundComparisonLineAmount(unitPrice, quantity) {
  const p = Number(unitPrice)
  const q = Number(quantity)
  if (!Number.isFinite(p) || !Number.isFinite(q)) return 0
  return Math.round(p * q)
}

/**
 * 請求比較の算出金額合計
 * @param {Array} comparisonItems
 * @param {Map<string, { unit_price?: number }>|Record<string, { unit_price?: number }>} priceByNormCode
 */
export function calculateComparisonTotalAmount(comparisonItems, priceByNormCode) {
  const lookup =
    priceByNormCode instanceof Map
      ? (code) => priceByNormCode.get(code)
      : (code) => priceByNormCode?.[code]

  let total = 0
  for (const item of comparisonItems || []) {
    if (shouldSkipComparisonCode(item?.external_code)) continue
    const nk = normalizeExternalCode(item?.external_code)
    if (!nk) continue
    const row = lookup(nk) || lookup(item.external_code)
    const unitPrice = row?.unit_price
    if (unitPrice === null || unitPrice === undefined || unitPrice === '') continue
    const qty = getComparisonCalcQuantity(item)
    if (qty === null) continue
    total += roundComparisonLineAmount(unitPrice, qty)
  }
  return total
}
