/** 大規模工程スケジュール: sort_order 0-13（14行） */
export const WORK_LARGE_SCHEDULE_COUNT = 14
export const WORK_LARGE_SCHEDULE_ORDER_MAX = 13
/** sort_order がこの値以上のテンプレは work 初期化に使わない（セレクト用予備行） */
export const SCHEDULE_LABEL_TEMPLATE_OVERFLOW_SORT_ORDER = 14

/** schedule_column_index を列番号に解釈（null / 空文字は未設定。0 は列0として有効） */
export function parseScheduleColumnIndex(value) {
  if (value == null || value === '') return null
  const index = Number(value)
  if (!Number.isInteger(index) || index < 0 || index > WORK_LARGE_SCHEDULE_ORDER_MAX) {
    return null
  }
  return index
}

export function emptyWorkLargeScheduleRows() {
  return Array.from({ length: WORK_LARGE_SCHEDULE_COUNT }, (_, sort_order) => ({
    sort_order,
    label: '',
    schedule_label_template_id: null,
    schedule_status_id: null,
    schedule_secondary_status_id: null,
    start_on: null,
    end_on: null,
    note: '',
  }))
}

export function padWorkLargeScheduleRows(rows) {
  const byOrder = new Map()
  for (const r of rows || []) {
    const o = Number(r?.sort_order)
    if (!Number.isFinite(o) || o < 0 || o > WORK_LARGE_SCHEDULE_ORDER_MAX) continue
    byOrder.set(o, normalizeScheduleRow(r, o))
  }
  return Array.from({ length: WORK_LARGE_SCHEDULE_COUNT }, (_, i) =>
    byOrder.get(i) ?? {
      sort_order: i,
      label: '',
      schedule_label_template_id: null,
      schedule_status_id: null,
      schedule_secondary_status_id: null,
      start_on: null,
      end_on: null,
      note: '',
    }
  )
}

/** 未保存 work: sort_order 一致テンプレの id のみセット（label は空） */
export function buildWorkLargeScheduleRowsFromTemplate(templates) {
  const base = emptyWorkLargeScheduleRows()
  for (const tpl of templates || []) {
    const o = Number(tpl?.sort_order)
    if (!Number.isFinite(o) || o < 0 || o > WORK_LARGE_SCHEDULE_ORDER_MAX) continue
    if (tpl?.id != null && tpl.id !== '') {
      base[o].schedule_label_template_id = String(tpl.id)
    }
  }
  return base
}

/** 工程行の created_at 最小値（スケジュール表の登録日） */
export function minScheduleCreatedAtFromRows(rows) {
  let minMs = null
  let minValue = null
  for (const row of rows || []) {
    const value = row?.created_at ? String(row.created_at) : null
    if (!value) continue
    const ms = new Date(value).getTime()
    if (!Number.isFinite(ms)) continue
    if (minMs == null || ms < minMs) {
      minMs = ms
      minValue = value
    }
  }
  return minValue
}

function formatScheduleCreatedAtParts(iso, options) {
  if (!iso) return null
  const ms = new Date(String(iso)).getTime()
  if (!Number.isFinite(ms)) return null
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Tokyo',
    ...options,
  }).formatToParts(new Date(ms))
}

/** timestamptz → type="date" 用 YYYY-MM-DD（JST） */
export function scheduleCreatedAtToDateInputValue(iso) {
  const parts = formatScheduleCreatedAtParts(iso, {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  })
  if (!parts) return ''
  const get = (type) => parts.find((p) => p.type === type)?.value ?? ''
  return `${get('year')}-${get('month')}-${get('day')}`
}

/** timestamptz → type="time" 用 HH:MM:SS（JST） */
export function scheduleCreatedAtToTimeInputValue(iso) {
  const parts = formatScheduleCreatedAtParts(iso, {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  })
  if (!parts) return '00:00:00'
  const get = (type) => parts.find((p) => p.type === type)?.value ?? '00'
  return `${get('hour')}:${get('minute')}:${get('second')}`
}

function normalizeScheduleCreatedAtTimeInput(timeStr) {
  const raw = String(timeStr ?? '').trim()
  if (!raw) return '00:00:00'
  const match = raw.match(/^(\d{2}):(\d{2})(?::(\d{2}))?$/)
  if (!match) return null
  return `${match[1]}:${match[2]}:${match[3] ?? '00'}`
}

/** 日付 + 時刻 → timestamptz（JST） */
export function dateTimeInputsToScheduleCreatedAtIso(dateStr, timeStr) {
  const date = String(dateStr ?? '').trim()
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null
  const time = normalizeScheduleCreatedAtTimeInput(timeStr)
  if (!time) return null
  return `${date}T${time}+09:00`
}

/** type="date" のみ → timestamptz（JST 0:00） */
export function dateInputToScheduleCreatedAtIso(dateStr) {
  return dateTimeInputsToScheduleCreatedAtIso(dateStr, '00:00:00')
}

function normalizeScheduleRow(row, sort_order) {
  const templateId = row?.schedule_label_template_id
  return {
    id: row?.id ?? null,
    sort_order,
    label: String(row?.label ?? ''),
    schedule_label_template_id:
      templateId == null || templateId === '' ? null : String(templateId),
    schedule_status_id: row?.schedule_status_id ?? null,
    schedule_secondary_status_id: row?.schedule_secondary_status_id ?? null,
    start_on: row?.start_on ?? null,
    end_on: row?.end_on ?? null,
    note: String(row?.note ?? ''),
    created_at: row?.created_at ?? null,
    updated_at: row?.updated_at ?? null,
  }
}

export function validateScheduleRowsForSave(rows) {
  if (!Array.isArray(rows) || rows.length !== WORK_LARGE_SCHEDULE_COUNT) {
    return '14行すべて入力してください'
  }
  for (const row of rows) {
    const start = row?.start_on ? String(row.start_on) : ''
    const end = row?.end_on ? String(row.end_on) : ''
    if (start && end && end < start) {
      return `終了日は開始日以降にしてください（行 ${Number(row.sort_order) + 1}）`
    }
  }
  return null
}

/**
 * 選択テンプレの schedule_column_index 重複を検出（null の INDEX は対象外）
 * @returns {{ message: string, conflictSortOrders: number[] } | null}
 */
export function findScheduleColumnIndexDuplicates(rows, templates) {
  const templateById = scheduleLabelTemplateById(templates)
  const indexToSortOrders = new Map()

  for (const row of rows || []) {
    const templateId = row?.schedule_label_template_id
    if (templateId == null || templateId === '') continue
    const tpl = templateById.get(String(templateId))
    const colIndex = parseScheduleColumnIndex(tpl?.schedule_column_index)
    if (colIndex == null) continue
    if (!indexToSortOrders.has(colIndex)) {
      indexToSortOrders.set(colIndex, [])
    }
    indexToSortOrders.get(colIndex).push(Number(row.sort_order))
  }

  const conflictSortOrders = []
  const duplicateIndices = []
  for (const [colIndex, sortOrders] of indexToSortOrders) {
    if (sortOrders.length > 1) {
      duplicateIndices.push(colIndex)
      conflictSortOrders.push(...sortOrders)
    }
  }

  if (duplicateIndices.length === 0) return null

  duplicateIndices.sort((a, b) => a - b)
  const indexLabel = duplicateIndices.join('、')
  return {
    message: `スケジュール表INDEX番号が重複しています（INDEX: ${indexLabel}）。テンプレの選択を修正してください。`,
    conflictSortOrders: [...new Set(conflictSortOrders)].sort((a, b) => a - b),
  }
}

/** schedule_label_templates.id → Map */
export function scheduleLabelTemplateById(templates) {
  const map = new Map()
  for (const tpl of templates || []) {
    if (tpl?.id != null && tpl.id !== '') {
      map.set(String(tpl.id), tpl)
    }
  }
  return map
}

/** 工程モーダルセレクト用: 0–13 は全件、14+ は category ありのみ */
export function scheduleLabelTemplatesForSelect(templates) {
  return (templates || []).filter((tpl) => {
    const sortOrder = Number(tpl?.sort_order)
    if (!Number.isFinite(sortOrder) || sortOrder < SCHEDULE_LABEL_TEMPLATE_OVERFLOW_SORT_ORDER) {
      return true
    }
    return String(tpl?.category ?? '').trim().length > 0
  })
}

/**
 * PDF 工程ラベル: テンプレあり → category(label) / category のみ、なし → label のみ
 * @param {{ label?: string, schedule_label_template_id?: string|null }} row
 * @param {Map<string, { category?: string|null }>} templateById
 */
export function formatSchedulePdfDisplayLabel(row, templateById) {
  const manualLabel = String(row?.label ?? '').trim()
  const templateId = row?.schedule_label_template_id
  if (templateId == null || templateId === '') {
    return manualLabel
  }
  const tpl = templateById?.get(String(templateId))
  const category = String(tpl?.category ?? '').trim()
  if (!category) {
    return manualLabel
  }
  if (manualLabel) {
    return `${category}(${manualLabel})`
  }
  return category
}

/** 【検査】物件名-号棟-号室 の表示幅上限（半角0.5・全角1。14以上で2行分割） */
export const SCHEDULE_GRID_WORK_NAME_MAX_DISPLAY_WIDTH = 14

function scheduleGridWorkCharDisplayWidth(char) {
  const code = char.charCodeAt(0)
  if (code <= 0x007f || (code >= 0xff61 && code <= 0xff9f)) return 0.5
  return 1
}

export function scheduleGridWorkDisplayWidth(text) {
  let width = 0
  for (const char of String(text ?? '')) {
    width += scheduleGridWorkCharDisplayWidth(char)
  }
  return width
}

function sliceScheduleGridWorkTitleByDisplayWidth(text, maxWidth) {
  let width = 0
  let index = 0
  for (const char of String(text ?? '')) {
    const charWidth = scheduleGridWorkCharDisplayWidth(char)
    if (width + charWidth > maxWidth) break
    width += charWidth
    index += 1
  }
  return {
    head: String(text ?? '').slice(0, index),
    tail: String(text ?? '').slice(index),
  }
}

export function scheduleGridWorkPropertySearchKey(item) {
  const housingName = String(item?.housing_name ?? item?.housing_details?.name ?? '').trim()
  const building = String(item?.housing_building ?? item?.housing_details?.building ?? '').trim()
  const room = String(item?.room ?? '').trim()
  const buildingRoom = [building, room].filter(Boolean).join('-')
  return [housingName, buildingRoom].filter(Boolean).join('-')
}

/** グリッド表示用の1行タイトル（【検査】/(閉鎖)物件名-号棟-号室） */
export function scheduleGridWorkFullDisplayTitle(item, prefix = '') {
  const key = scheduleGridWorkPropertySearchKey(item)
  if (!key) return `Work ${item?.work_id ?? ''}`
  return prefix ? `${prefix}${key}` : key
}

/** グリッド: 表示幅14以上で2行（1行目=プレフィックス+物件名、2行目=号棟-号室。半角0.5・全角1） */
export function scheduleGridWorkDisplayLines(item, prefix = '') {
  const housingName = String(item?.housing_name ?? item?.housing_details?.name ?? '').trim()
  const building = String(item?.housing_building ?? item?.housing_details?.building ?? '').trim()
  const room = String(item?.room ?? '').trim()
  const buildingRoom = [building, room].filter(Boolean).join('-')
  const prefixLabel = String(prefix ?? '')
  const fallback = `Work ${item?.work_id ?? ''}`
  const maxWidth = SCHEDULE_GRID_WORK_NAME_MAX_DISPLAY_WIDTH
  const fullTitle = scheduleGridWorkFullDisplayTitle(item, prefixLabel)

  if (!housingName && !buildingRoom) {
    return { line1: fallback, line2: '', title: fallback }
  }

  if (scheduleGridWorkDisplayWidth(fullTitle) < maxWidth) {
    return { line1: fullTitle, line2: '', title: fullTitle }
  }

  if (housingName) {
    const line1 = `${prefixLabel}${housingName}`
    if (buildingRoom) {
      return {
        line1,
        line2: buildingRoom,
        title: [line1, buildingRoom].filter(Boolean).join('\n'),
      }
    }
    const { head, tail } = sliceScheduleGridWorkTitleByDisplayWidth(fullTitle, maxWidth)
    return {
      line1: head,
      line2: tail,
      title: [head, tail].filter(Boolean).join('\n'),
    }
  }

  const { head, tail } = sliceScheduleGridWorkTitleByDisplayWidth(fullTitle, maxWidth)
  return {
    line1: head,
    line2: tail,
    title: [head, tail].filter(Boolean).join('\n'),
  }
}

export function scheduleGridWorkDisplayName(item) {
  return scheduleGridWorkDisplayLines(item).title.replace('\n', ' / ')
}

/** 列見出し: schedule_column_index → category */
export function scheduleColumnHeadersFromTemplates(templates) {
  const headers = Array.from({ length: WORK_LARGE_SCHEDULE_COUNT }, () => '')
  for (const tpl of templates || []) {
    const index = parseScheduleColumnIndex(tpl?.schedule_column_index)
    if (index == null) continue
    headers[index] = String(tpl?.category ?? '').trim()
  }
  return headers
}

/** グリッドセル: schedule_column_index 基準で行を配置 */
export function buildScheduleRowsByColumnIndex(rows, templateById) {
  const cells = Array.from({ length: WORK_LARGE_SCHEDULE_COUNT }, () => null)
  for (const row of rows || []) {
    const templateId = row?.schedule_label_template_id
    const tpl = templateId != null && templateId !== ''
      ? templateById?.get(String(templateId))
      : null
    const index = parseScheduleColumnIndex(tpl?.schedule_column_index)
    if (index == null) continue
    cells[index] = row
  }
  return cells
}

function getStatusKeyFromOptions(statusId, statusOptions) {
  if (statusId == null || statusId === '') return null
  const st = (statusOptions || []).find((s) => Number(s.id) === Number(statusId))
  return st?.key ?? null
}

function rowHasStatusKey(row, key, statusOptions) {
  return (
    getStatusKeyFromOptions(row?.schedule_status_id, statusOptions) === key ||
    getStatusKeyFromOptions(row?.schedule_secondary_status_id, statusOptions) === key
  )
}

/** モーダルと同じセルハイライト */
export function getScheduleRowHighlightKey(row, statusOptions) {
  if (!row) return null
  if (rowHasStatusKey(row, 'none', statusOptions)) return 'none'
  if (rowHasStatusKey(row, 'completed', statusOptions)) return 'completed'
  if (rowHasStatusKey(row, 'removed', statusOptions)) return 'removed'
  if (rowHasStatusKey(row, 'requested', statusOptions)) return 'requested'
  return null
}

export function resolveScheduleStatusIdBySymbol(statusOptions, symbol) {
  const target = String(symbol ?? '').trim()
  if (!target) return null
  const row = (statusOptions || []).find(
    (st) => st?.is_active !== false && String(st.symbol ?? '').trim() === target,
  )
  const id = Number(row?.id)
  return Number.isInteger(id) ? id : null
}

/** 状態1進行: 空→〇→◎→●。変更なしは undefined */
export function nextScheduleStatus1IdForAdvance(currentStatusId, statusOptions) {
  const normalizedId =
    currentStatusId == null || currentStatusId === '' ? null : Number(currentStatusId)
  if (!Number.isInteger(normalizedId)) {
    return resolveScheduleStatusIdBySymbol(statusOptions, '〇')
  }
  const current = (statusOptions || []).find((st) => Number(st.id) === normalizedId)
  const symbol = String(current?.symbol ?? '').trim()
  if (symbol === '〇') {
    return resolveScheduleStatusIdBySymbol(statusOptions, '◎')
  }
  if (symbol === '◎') {
    return resolveScheduleStatusIdBySymbol(statusOptions, '●')
  }
  return undefined
}

/** 状態1後退: ●→◎→〇→空。変更なしは undefined */
export function prevScheduleStatus1IdForRetreat(currentStatusId, statusOptions) {
  const normalizedId =
    currentStatusId == null || currentStatusId === '' ? null : Number(currentStatusId)
  if (!Number.isInteger(normalizedId)) return undefined
  const current = (statusOptions || []).find((st) => Number(st.id) === normalizedId)
  const symbol = String(current?.symbol ?? '').trim()
  if (symbol === '●') {
    return resolveScheduleStatusIdBySymbol(statusOptions, '◎')
  }
  if (symbol === '◎') {
    return resolveScheduleStatusIdBySymbol(statusOptions, '〇')
  }
  if (symbol === '〇') {
    return null
  }
  return undefined
}

function formatScheduleDateSlash(value) {
  if (!value) return ''
  const match = String(value).trim().match(/^(\d{4})-(\d{2})-(\d{2})$/)
  if (!match) return ''
  return `${Number(match[2])}/${Number(match[3])}`
}

/** セル日付 suffix: 始のみ M/D～ / 始+至 M/D～M/D / 至のみ ～M/D（括弧なし） */
export function formatScheduleGridCellDateSuffix(row) {
  const start = formatScheduleDateSlash(row?.start_on)
  const end = formatScheduleDateSlash(row?.end_on)
  if (start && end) return `${start}～${end}`
  if (start) return `${start}～`
  if (end) return `～${end}`
  return ''
}

/** グリッドセル: 状態1・2（シンボル）・ラベル・始～至・備考を表示 */
export function formatScheduleGridCellFull(row, statusOptions) {
  if (!row) return ''
  const primary = (statusOptions || []).find(
    (st) => Number(st.id) === Number(row.schedule_status_id),
  )
  const secondary = (statusOptions || []).find(
    (st) => Number(st.id) === Number(row.schedule_secondary_status_id),
  )
  const label = String(row.label ?? '').trim()
  const dateSuffix = formatScheduleGridCellDateSuffix(row)
  const note = String(row.note ?? '').trim()
  const parts = [
    String(primary?.symbol ?? '').trim(),
    String(secondary?.symbol ?? '').trim(),
    label,
    dateSuffix,
    note,
  ].filter(Boolean)
  return parts.join('')
}

/** グリッド縮小表示: 【検査】/(閉鎖)団地名-号棟-号室 */
export function scheduleGridWorkCompactTitle(item, prefix = '') {
  const key = scheduleGridWorkPropertySearchKey(item)
  if (!key) return `Work ${item?.work_id ?? ''}`
  return prefix ? `${prefix}${key}` : key
}

export const SCHEDULE_GRID_COMPLETED_PROGRESSIVE_LABELS = ['工事完了', '鍵返却']

export function resolveCompletedProgressiveStatusIds(statuses) {
  return resolveProgressiveStatusIdsByLabels(statuses, SCHEDULE_GRID_COMPLETED_PROGRESSIVE_LABELS)
}

export function resolveProgressiveStatusIdsByLabels(statuses, labels) {
  const labelSet = new Set((labels || []).map((label) => String(label ?? '').trim()))
  return (statuses || [])
    .filter((st) => labelSet.has(String(st.label ?? '').trim()))
    .map((st) => Number(st.id))
    .filter((id) => Number.isInteger(id))
}

export function resolveLargeJkkStatusIdsByLabels(statuses, labels) {
  return resolveProgressiveStatusIdsByLabels(statuses, labels)
}

export function isScheduleGridWorkRowCompleted(item, completedStatusIds) {
  const id = Number(item?.large_progressive_status_id)
  return completedStatusIds.includes(id)
}

export function isScheduleGridWorkRowInspection(item, largeSteps) {
  const stepId = Number(item?.large_step_id)
  if (!Number.isInteger(stepId)) return false
  const step = (largeSteps || []).find((row) => Number(row.id) === stepId)
  return Boolean(step?.is_inspection)
}

export function isScheduleGridWorkRowClosed(item, largeSteps) {
  const stepId = Number(item?.large_step_id)
  if (!Number.isInteger(stepId)) return false
  const step = (largeSteps || []).find((row) => Number(row.id) === stepId)
  return String(step?.key ?? '') === 'closed'
}

/** 物件名先頭プレフィックス（【検査】 / (閉鎖)） */
export function scheduleGridWorkDisplayPrefix(item, largeSteps) {
  if (isScheduleGridWorkRowInspection(item, largeSteps)) return '【検査】'
  if (isScheduleGridWorkRowClosed(item, largeSteps)) return '(閉鎖)'
  return ''
}
