import { WORK_LARGE_SCHEDULE_COUNT } from '../constants/workLargeSchedule.js'

const EDIT_FIELDS = [
  'label',
  'schedule_label_template_id',
  'schedule_status_id',
  'schedule_secondary_status_id',
  'start_on',
  'end_on',
  'note',
]

export function normalizeScheduleCellValue(field, value) {
  if (field === 'start_on' || field === 'end_on') {
    return value == null || value === '' ? null : String(value)
  }
  if (field === 'label' || field === 'note') {
    return String(value ?? '')
  }
  if (field === 'schedule_label_template_id') {
    return value == null || value === '' ? null : String(value)
  }
  return value ?? null
}

export function cloneScheduleRowForUndo(row) {
  if (!row) return null
  return {
    id: row.id ?? null,
    sort_order: row.sort_order,
    ...Object.fromEntries(
      EDIT_FIELDS.map((field) => [field, normalizeScheduleCellValue(field, row[field])]),
    ),
  }
}

export function scheduleCellContentEqual(a, b) {
  const empty = {
    label: '',
    schedule_label_template_id: null,
    schedule_status_id: null,
    schedule_secondary_status_id: null,
    start_on: null,
    end_on: null,
    note: '',
  }
  const left = a == null ? empty : a
  const right = b == null ? empty : b
  for (const field of EDIT_FIELDS) {
    if (
      normalizeScheduleCellValue(field, left[field]) !== normalizeScheduleCellValue(field, right[field])
    ) {
      return false
    }
  }
  return true
}

export function collectCellChangesFromColumnCells(workId, previousCells, nextCells) {
  const wid = String(workId)
  const changes = []
  for (let col = 0; col < WORK_LARGE_SCHEDULE_COUNT; col++) {
    if (!scheduleCellContentEqual(previousCells[col], nextCells[col])) {
      changes.push({
        workId: wid,
        columnIndex: col,
        previousRow: cloneScheduleRowForUndo(previousCells[col]),
      })
    }
  }
  return changes
}

export function columnCellsDifferFromBaseline(currentCells, baselineCells) {
  for (let col = 0; col < WORK_LARGE_SCHEDULE_COUNT; col++) {
    if (!scheduleCellContentEqual(currentCells[col], baselineCells[col])) return true
  }
  return false
}

export function isCellDirtyAtColumn(columnIndex, currentCells, baselineCells) {
  const col = Number(columnIndex)
  if (col < 0 || col >= WORK_LARGE_SCHEDULE_COUNT) return false
  return !scheduleCellContentEqual(currentCells[col], baselineCells[col])
}
