<template>
  <div
    ref="panelRootRef"
    class="instruction-merge-panel"
    :class="{ 'instruction-merge-panel--compact-mobile': compactMobile }"
  >
    <p v-if="!rows.length" class="imp-empty">{{ emptyMessage }}</p>

    <!-- スマホ: ▶ / 依頼先 / 原本 / 内容 / 数量 -->
    <div v-else-if="compactMobile" class="imp-table-wrap">
      <table class="imp-table imp-table--mobile">
        <thead>
          <tr>
            <th colspan="3" class="imp-m5-thead">
              <div class="imp-m5-hgrid">
                <div class="imp-m5-hcell">▶</div>
                <div class="imp-m5-hcell">依頼先</div>
                <div class="imp-m5-hcell">原本</div>
                <div class="imp-m5-hcell">内容</div>
                <div class="imp-m5-hcell imp-m5-hcell-qty">数量</div>
              </div>
            </th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="(r, i) in rows"
            :key="`mm-${r.normCode || r.external_code}-${r._flatIndex ?? i}-${i}`"
            :class="['imp-m5-tr', mobileRowClass(r)]"
            :data-external-code="String(r.external_code || '').trim()"
          >
            <td colspan="3" class="imp-m5-td-wrap">
              <div class="imp-m5-bgrid">
                <div class="imp-m5-cell imp-m5-code">
                  <button
                    type="button"
                    class="imp-code-btn imp-m5-code-btn"
                    :class="{ 'imp-code-btn--reserved-range': isReservedNumericCode(r.external_code) }"
                    :title="`写真タブでこの行へ移動（画像: ${r.fileName || r.fileId}）`"
                    @click="emit('code-click', { fileId: r.fileId, rowIndex: r.rowIndex, external_code: r.external_code })"
                  >
                    ▶
                  </button>
                </div>
                <div class="imp-m5-cell imp-m5-readonly">{{ compactContractorLabel(r.contractorLabel) }}</div>
                <div
                  class="imp-m5-cell imp-m5-readonly"
                  :class="{ 'imp-template-cell--empty': rowOriginalTemplateEmpty(r) }"
                >{{ r.templateInstruction }}</div>
                <div class="imp-m5-cell imp-m5-readonly">{{ r.content }}</div>
                <div class="imp-m5-cell imp-m5-num" :class="{ 'imp-qty-x': r.is_quantity }">{{ formatQty(r) }}</div>
              </div>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- PC / タブレット -->
    <div v-else class="imp-table-wrap">
      <table class="imp-table">
        <colgroup>
          <col class="imp-col-code" />
          <col v-if="showMoveColumn" class="imp-col-move" />
          <col class="imp-col-desc" />
          <col class="imp-col-contractor" />
          <col v-if="showRoomColumn" class="imp-col-room" />
          <col class="imp-col-template" />
          <col class="imp-col-content" />
          <col class="imp-col-x" />
          <col class="imp-col-qty" />
          <col class="imp-col-plus" />
        </colgroup>
        <thead>
          <tr>
            <th>コード</th>
            <th v-if="showMoveColumn">移動</th>
            <th>概要/備考</th>
            <th>依頼先</th>
            <th v-if="showRoomColumn">部屋</th>
            <th>原本</th>
            <th>内容</th>
            <th>x</th>
            <th>数量</th>
            <th>＋</th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="(r, i) in rows"
            :key="`m-${r.normCode || r.external_code}-${r._flatIndex ?? i}-${i}`"
            :class="{ 'imp-row-no-contractor': shouldDimRow(r) }"
            :data-external-code="String(r.external_code || '').trim()"
          >
            <td class="imp-code">
              <button
                type="button"
                class="imp-code-btn"
                :class="{ 'imp-code-btn--reserved-range': isReservedNumericCode(r.external_code) }"
                :title="`写真タブでこの行へ移動（画像: ${r.fileName || r.fileId}）`"
                @click="emit('code-click', { fileId: r.fileId, rowIndex: r.rowIndex, external_code: r.external_code })"
              >
                {{ r.external_code }}
              </button>
            </td>
            <td v-if="showMoveColumn" class="imp-move-cell">
              <button
                type="button"
                class="imp-move-btn"
                :class="{ 'imp-move-btn--missing-billing': moveBtnMissingFromBilling(r) }"
                title="比較で該当コードへ移動"
                :disabled="!String(r.external_code || '').trim()"
                @click="onMoveToComparison(r)"
              >
                <span class="imp-move-glyph" aria-hidden="true">⇅</span>
              </button>
            </td>
            <td class="imp-readonly imp-muted-source-cell imp-desc-cell">
              <div class="imp-desc-stack">
                <span
                  class="imp-desc-line imp-desc-line--dblclick"
                  :class="{ 'imp-desc-line--desc-dblclick': rowDescStackShowBlueBorder(r) }"
                  :title="descriptionCellTitle(r)"
                  @dblclick="onDescriptionDblClick(r, $event)"
                  @click="onDescriptionClick(r, $event)"
                >{{ descriptionMain(r) }}</span>
                <span
                  v-if="descriptionAdd(r)"
                  class="imp-desc-line imp-desc-line-sub"
                  :title="descriptionAdd(r)"
                >{{ descriptionAdd(r) }}</span>
              </div>
            </td>
            <td class="imp-editable imp-contractor-cell">
              <select
                class="imp-input imp-select-contractor"
                :value="r.contractor_id ?? ''"
                @change="emitRowFieldUpdate(r, 'contractor_id', $event.target.value)"
              >
                <option value="">—</option>
                <option v-for="c in contractorsForSelectRow(r)" :key="String(c.id)" :value="String(c.id)">
                  {{ c.label }}
                </option>
                <option
                  v-if="hiddenContractorForRow(r)"
                  :key="'hidden-' + hiddenContractorForRow(r).id"
                  :value="String(hiddenContractorForRow(r).id)"
                  hidden
                >
                  {{ hiddenContractorForRow(r).label }}
                </option>
              </select>
            </td>
            <td v-if="showRoomColumn" class="imp-room-cell">
              <button
                type="button"
                class="imp-room-btn"
                :class="{
                  'imp-room-btn--bucket-label': roomBucketButtonLabel(r),
                  'imp-room-btn--supplement': isSupplementBucketRow(r),
                  'imp-room-btn--text-label': isSupplementBucketRow(r) || roomBucketButtonLabel(r),
                }"
                :title="roomButtonTitle(r)"
                @click="toggleRoomMenu(i, r, $event)"
              >
                <span v-if="isSupplementBucketRow(r)" class="imp-room-btn-label imp-room-btn-label--supplement">補足</span>
                <span v-else-if="roomBucketButtonLabel(r)" class="imp-room-btn-label">{{ roomBucketButtonLabel(r) }}</span>
                <svg v-else viewBox="0 0 24 24" width="14" height="14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                  <path d="M3 10.5L12 3l9 7.5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  <path d="M5 9.8V21h14V9.8" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  <path d="M9.5 21v-6h5v6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </button>
            </td>
            <td
              class="imp-readonly imp-muted-source-cell"
              :class="{ 'imp-template-cell--empty': rowOriginalTemplateEmpty(r) }"
            >{{ r.templateInstruction }}</td>
            <td class="imp-editable">
              <input
                class="imp-input imp-input-content"
                type="text"
                :value="r.content"
                @keydown.enter="blurInputOnEnterWhenNotComposing"
                @change="emitRowFieldUpdate(r, 'content', $event.target.value)"
              />
            </td>
            <td class="imp-x-cell">
              <button
                type="button"
                class="imp-mini-btn imp-x-btn"
                :class="{ active: r.is_quantity }"
                title="数量記載(x)を切替"
                @click="emitRowQuantityFlagToggle(r)"
              >
                x
              </button>
            </td>
            <td class="imp-num imp-editable">
              <input
                class="imp-input imp-input-qty"
                type="text"
                inputmode="decimal"
                :value="formatQty(r)"
                @keydown.enter="blurInputOnEnterWhenNotComposing"
                @change="emitRowFieldUpdate(r, 'quantity', $event.target.value)"
              />
            </td>
            <td class="imp-plus-cell">
              <button
                type="button"
                class="imp-mini-btn imp-plus-btn"
                title="短押しで数量を増やす、長押しで数量を空にする"
                @click="handleRowQuantityPlusClick(r)"
                @contextmenu.prevent
                @mousedown="startRowQuantityClearLongPress(r)"
                @mouseup="cancelRowQuantityClearLongPress"
                @mouseleave="cancelRowQuantityClearLongPress"
                @touchstart.passive="startRowQuantityClearLongPress(r)"
                @touchend.passive="cancelRowQuantityClearLongPress"
                @touchcancel.passive="cancelRowQuantityClearLongPress"
              >
                ＋
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
  <Teleport to="body">
    <div
      v-if="roomMenuRowIndex !== null && roomMenuTargetRow"
      ref="roomMenuRef"
      class="imp-room-menu imp-room-menu--teleport"
      :style="roomMenuStyle"
    >
      <div class="imp-room-menu-scroll">
        <button
          v-for="label in roomLabelOptions"
          :key="`room-teleport-${roomMenuRowIndex}-${label}`"
          type="button"
          class="imp-room-menu-item"
          @click="applyRoomLabelToRow(roomMenuTargetRow, label)"
        >
          {{ label }}
        </button>
      </div>
      <button type="button" class="imp-room-menu-item imp-room-menu-close" @click="closeRoomMenu">閉じる</button>
    </div>
  </Teleport>
</template>

<script setup>
import { ref, computed, nextTick, onMounted, onBeforeUnmount } from 'vue'
import {
  filterContractorsForSelect,
  getHiddenSelectedContractor
} from '../utils/contractorSelect'
import { isPhotoTabRoomOrder } from '../constants/roomLabelSlots.js'
import { positionTeleportMenuFromAnchor } from '../utils/teleportMenuPosition.js'
import { blurInputOnEnterWhenNotComposing } from '../utils/inputKeyboard.js'

const ROOM_ORDER_FILE_PREFIX = '__room_order__:'
const NULL_FILE_SLOT_ID = '__null_file__'

const props = defineProps({
  rows: { type: Array, default: () => [] },
  emptyMessage: { type: String, default: '結合表示する写真リンク行がありません' },
  contractors: { type: Array, default: () => [] },
  contractorSelectionIds: { type: Array, default: () => [] },
  /** 見積グリッド・スマホ: ▶ / 依頼先 / 原本 / 内容 / 数量（10/16/32/32/10） */
  compactMobile: { type: Boolean, default: false },
  /** タブレット: 概要セルのダブルタップで内容へ反映 */
  tabletDoubleTap: { type: Boolean, default: false },
  /** PC: コード列と概要/備考列の間に比較移動列 */
  showMoveColumn: { type: Boolean, default: false },
  /** PC・タブレット: 依頼先と原本の間に部屋列 */
  showRoomColumn: { type: Boolean, default: false },
  roomLabelOptions: { type: Array, default: () => [] },
  roomLabels: { type: Array, default: () => [] },
  /** 公側 billing に無いコードの移動ボタンをオレンジ表示 */
  comparisonIsCodeMissingFromBilling: { type: Function, default: null }
})

function parseRoomOrderFromFileId(fileId) {
  const s = String(fileId || '')
  if (!s.startsWith(ROOM_ORDER_FILE_PREFIX)) return null
  const n = parseInt(s.slice(ROOM_ORDER_FILE_PREFIX.length), 10)
  return Number.isFinite(n) ? n : null
}

function isSupplementBucketRow(row) {
  return String(row?.fileId || '') === NULL_FILE_SLOT_ID
}

/** sort_order 0〜9 の部屋バケット行: ルームラベル文字列（空なら SVG のまま） */
function roomBucketButtonLabel(row) {
  if (isSupplementBucketRow(row)) return ''
  const ord = parseRoomOrderFromFileId(row?.fileId)
  if (ord == null || !isPhotoTabRoomOrder(ord)) return ''
  const fromRow = String(row?.fileName || '').trim()
  if (fromRow && fromRow !== `label${ord}`) return fromRow
  const hit = (props.roomLabels || []).find((l) => Number(l?.sort_order) === ord)
  return String(hit?.label ?? '').trim()
}

function roomButtonTitle(row) {
  if (isSupplementBucketRow(row)) return '補足'
  return roomBucketButtonLabel(row) || '部屋を挿入'
}

function contractorsForSelectRow(r) {
  return filterContractorsForSelect(props.contractors, props.contractorSelectionIds)
}

function hiddenContractorForRow(r) {
  return getHiddenSelectedContractor(
    props.contractors,
    props.contractorSelectionIds,
    r?.contractor_id ?? ''
  )
}

const emit = defineEmits([
  'code-click',
  'update-row-field',
  'toggle-row-quantity-flag',
  'increment-row-quantity',
  'clear-row-quantity',
  'scroll-to-comparison'
])
const panelRootRef = ref(null)
const roomMenuRef = ref(null)
const roomMenuRowIndex = ref(null)
const roomMenuTargetRow = ref(null)
const roomMenuPos = ref({ top: 0, left: 0 })
const roomMenuStyle = computed(() => ({
  position: 'fixed',
  top: `${roomMenuPos.value.top}px`,
  left: `${roomMenuPos.value.left}px`
}))
const descCellTapPendingKey = ref('')
let descCellTapTimer = null
const DESC_CELL_DOUBLE_TAP_MS = 450

/** PhotoWorkLinksPanel の description 連結子と同じ（概要 / 備考） */
const DESC_COMBINE_SEP = ' / '

function splitStoredDescription(stored) {
  const t = String(stored ?? '').trim()
  if (!t) return { main: '', add: '' }
  const ix = t.indexOf(DESC_COMBINE_SEP)
  if (ix >= 0) {
    return {
      main: t.slice(0, ix).trim(),
      add: t.slice(ix + DESC_COMBINE_SEP.length).trim()
    }
  }
  return { main: t, add: '' }
}

function descriptionMain(r) {
  return splitStoredDescription(r?.description).main
}

function descriptionAdd(r) {
  return splitStoredDescription(r?.description).add
}

let instructionFlashTimer = null
let rowQuantityClearLongPressTimer = null
let rowQuantityClearLongPressTriggered = false
let rowQuantityClearLongPressAt = 0
const ROW_QUANTITY_CLEAR_LONG_PRESS_MS = 500

function hasContractor(r) {
  const id = r?.contractor_id
  return id != null && String(id).trim() !== ''
}

function hasOriginalOrContent(r) {
  return (
    String(r?.templateInstruction ?? '').trim().length > 0 ||
    String(r?.content ?? '').trim().length > 0
  )
}

function shouldDimRow(r) {
  return !hasContractor(r) || !hasOriginalOrContent(r)
}

function rowDescDblClickEnabled(r) {
  const code = String(r?.external_code ?? '').trim()
  if (!code) return false
  return !String(r?.templateInstruction ?? '').trim()
}

function rowDescStackShowBlueBorder(r) {
  return rowDescDblClickEnabled(r) && Boolean(descriptionMain(r))
}

function rowOriginalTemplateEmpty(r) {
  const code = String(r?.external_code ?? '').trim()
  if (!code) return false
  return !String(r?.templateInstruction ?? '').trim()
}

function descriptionCellTitle(r) {
  const desc = descriptionMain(r)
  if (!rowDescDblClickEnabled(r)) return desc || undefined
  const hint = props.tabletDoubleTap ? 'ダブルタップで内容欄へ入力' : 'ダブルクリックで内容欄へ入力'
  return desc ? `${desc}\n（${hint}）` : hint
}

function descCellTapKey(r) {
  return `${String(r?.fileId ?? '')}:${Number(r?.rowIndex)}:${String(r?.external_code ?? '')}`
}

function applyDescriptionToContent(r) {
  if (props.compactMobile) return
  if (!rowDescDblClickEnabled(r)) return
  const summary = descriptionMain(r)
  if (!summary) return
  emitRowFieldUpdate(r, 'content', summary)
}

/** PC: 概要のダブルクリックで内容欄へ上書き */
function onDescriptionDblClick(r, ev) {
  ev?.preventDefault?.()
  applyDescriptionToContent(r)
}

/** タブレット: 概要の2回タップで内容欄へ上書き */
function onDescriptionClick(r, ev) {
  if (!props.tabletDoubleTap) return
  if (props.compactMobile) return
  if (ev?.type === 'click' && Number(ev?.detail) >= 2) return
  if (!rowDescDblClickEnabled(r)) return
  const summary = descriptionMain(r)
  if (!summary) return
  ev?.preventDefault?.()
  const key = descCellTapKey(r)
  if (descCellTapPendingKey.value === key) {
    descCellTapPendingKey.value = ''
    if (descCellTapTimer) clearTimeout(descCellTapTimer)
    descCellTapTimer = null
    applyDescriptionToContent(r)
    return
  }
  descCellTapPendingKey.value = key
  if (descCellTapTimer) clearTimeout(descCellTapTimer)
  descCellTapTimer = setTimeout(() => {
    descCellTapPendingKey.value = ''
    descCellTapTimer = null
  }, DESC_CELL_DOUBLE_TAP_MS)
}

/** 数値として 0～1000 のコード（予約帯）: コードボタンを薄い赤系に */
function isReservedNumericCode(code) {
  const s = String(code ?? '').trim()
  if (s === '') return false
  const n = Number(s)
  return Number.isFinite(n) && n >= 0 && n <= 1000
}

function mobileRowClass(r) {
  return { 'imp-row-no-contractor': shouldDimRow(r) }
}

function formatQty(r) {
  if (r.quantity == null || r.quantity === '') return ''
  return String(r.quantity)
}

function rowPayload(r) {
  return {
    fileId: r?.fileId,
    rowIndex: r?.rowIndex,
    external_code: r?.external_code
  }
}

function emitRowFieldUpdate(r, field, value) {
  emit('update-row-field', {
    ...rowPayload(r),
    field,
    value
  })
}

function emitRowQuantityFlagToggle(r) {
  emit('toggle-row-quantity-flag', rowPayload(r))
}

function emitRowQuantityIncrement(r) {
  emit('increment-row-quantity', rowPayload(r))
}

function emitRowQuantityClear(r) {
  emit('clear-row-quantity', rowPayload(r))
}

function startRowQuantityClearLongPress(r) {
  cancelRowQuantityClearLongPress()
  rowQuantityClearLongPressTriggered = false
  rowQuantityClearLongPressTimer = setTimeout(() => {
    rowQuantityClearLongPressTriggered = true
    rowQuantityClearLongPressAt = Date.now()
    emitRowQuantityClear(r)
  }, ROW_QUANTITY_CLEAR_LONG_PRESS_MS)
}

function cancelRowQuantityClearLongPress() {
  if (!rowQuantityClearLongPressTimer) return
  clearTimeout(rowQuantityClearLongPressTimer)
  rowQuantityClearLongPressTimer = null
}

function handleRowQuantityPlusClick(r) {
  if (Date.now() - rowQuantityClearLongPressAt < 700) return
  if (rowQuantityClearLongPressTriggered) {
    rowQuantityClearLongPressTriggered = false
    return
  }
  emitRowQuantityIncrement(r)
}

function moveBtnMissingFromBilling(r) {
  const code = String(r?.external_code ?? '').trim()
  if (!code) return false
  if (typeof props.comparisonIsCodeMissingFromBilling === 'function') {
    return Boolean(props.comparisonIsCodeMissingFromBilling(code))
  }
  return false
}

function onMoveToComparison(r) {
  const code = String(r?.external_code ?? '').trim()
  if (!code) return
  emit('scroll-to-comparison', code)
}

function closeRoomMenu() {
  roomMenuRowIndex.value = null
  roomMenuTargetRow.value = null
}

async function updateRoomMenuPosition(ev = null) {
  if (roomMenuRowIndex.value == null) return
  let rect = null
  const targetEl = ev?.currentTarget || ev?.target
  if (targetEl && typeof targetEl.getBoundingClientRect === 'function') {
    rect = targetEl.getBoundingClientRect()
  } else if (typeof document !== 'undefined') {
    const btn = document.querySelectorAll('.imp-room-btn')[roomMenuRowIndex.value]
    if (btn && typeof btn.getBoundingClientRect === 'function') rect = btn.getBoundingClientRect()
  }
  if (!rect) return
  const anchorLeft = Math.round(rect.left + 2)
  const anchorBottomY = Math.round(rect.bottom - 2)
  roomMenuPos.value = { top: anchorBottomY, left: anchorLeft }
  await nextTick()
  const pos = positionTeleportMenuFromAnchor(roomMenuRef.value, anchorLeft, anchorBottomY)
  if (pos) roomMenuPos.value = { top: pos.top, left: pos.left }
}

async function toggleRoomMenu(idx, row, ev) {
  if (roomMenuRowIndex.value === idx) {
    closeRoomMenu()
    return
  }
  roomMenuRowIndex.value = idx
  roomMenuTargetRow.value = row
  await updateRoomMenuPosition(ev)
}

function applyRoomLabelToRow(row, label) {
  const nextLabel = String(label || '').trim()
  if (!nextLabel) return
  emitRowFieldUpdate(row, 'content', nextLabel)
  closeRoomMenu()
}

function handleDocumentPointerDown(ev) {
  if (roomMenuRowIndex.value == null) return
  const target = ev?.target
  if (!target || typeof target.closest !== 'function') {
    closeRoomMenu()
    return
  }
  if (target.closest('.imp-room-menu') || target.closest('.imp-room-btn')) return
  closeRoomMenu()
}

onMounted(() => {
  document.addEventListener('pointerdown', handleDocumentPointerDown, true)
})

onBeforeUnmount(() => {
  document.removeEventListener('pointerdown', handleDocumentPointerDown, true)
  closeRoomMenu()
})

/** 3文字以下はそのまま、4文字以上は先頭2文字＋… */
function compactContractorLabel(label) {
  const s = String(label || '')
  if (s.length <= 3) return s
  return `${s.slice(0, 2)}…`
}

function scrollToExternalCode(code, options = {}) {
  const c = String(code || '').trim()
  if (!c) return false
  const root = panelRootRef.value
  if (!root) return false
  const esc = typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(c) : c.replace(/"/g, '\\"')
  const rows = Array.from(root.querySelectorAll(`tr[data-external-code="${esc}"]`))
  if (!rows.length) return false
  const startAfterIndex = Number(options?.startAfterIndex)
  let pickedIndex = 0
  if (Number.isFinite(startAfterIndex) && startAfterIndex >= 0) {
    pickedIndex = startAfterIndex + 1
    if (pickedIndex >= rows.length) pickedIndex = 0
  }
  const row = rows[pickedIndex]
  if (!row) return false
  if (typeof row.scrollIntoView === 'function') {
    row.scrollIntoView({ behavior: 'smooth', block: 'center' })
  }
  row.classList.remove('imp-row-flash-blue')
  void row.offsetWidth
  row.classList.add('imp-row-flash-blue')
  if (instructionFlashTimer) clearTimeout(instructionFlashTimer)
  instructionFlashTimer = setTimeout(() => {
    row.classList.remove('imp-row-flash-blue')
    instructionFlashTimer = null
  }, 1200)
  return { found: true, index: pickedIndex }
}

function getPanelScrollTop() {
  const root = panelRootRef.value
  if (!root) return 0
  return root.scrollTop || 0
}

function setPanelScrollTop(top) {
  const root = panelRootRef.value
  if (!root) return false
  const t = Number(top)
  root.scrollTop = Number.isFinite(t) ? Math.max(0, t) : 0
  return true
}

defineExpose({
  scrollToExternalCode,
  getPanelScrollTop,
  setPanelScrollTop
})
</script>

<style scoped>
.instruction-merge-panel {
  padding: 0.75rem;
  height: 100%;
  overflow: auto;
  background: #fafafa;
}

/* スマホ: 親 flex 内で高さ制約に引っかかり中身が切れないよう、伸縮と縦スクロールを優先 */
.instruction-merge-panel.instruction-merge-panel--compact-mobile {
  height: 100%;
  min-height: 0;
  flex: 1 1 auto;
  overflow: auto;
}

.imp-empty {
  color: #6b7280;
