function estimateScheduleGridDisplayRowHeight(displayRow) {
  if (displayRow.type === 'mc-header') return SCHEDULE_GRID_MC_HEADER_ROW_HEIGHT
  const { line2 } = scheduleGridWorkDisplayLines(
    displayRow.item,
    scheduleGridWorkDisplayPrefix(displayRow.item, largeSteps.value),
