  return line2 ? SCHEDULE_GRID_TWO_LINE_ROW_HEIGHT : SCHEDULE_GRID_SINGLE_LINE_ROW_HEIGHT
}

function rowHeightForDisplayRow(displayRow) {
  const measured = displayRowHeightByKey.value.get(displayRow.key)
  if (typeof measured === 'number' && measured > 0) return measured
  return estimateScheduleGridDisplayRowHeight(displayRow)
}

function syncDisplayRowOffsetsFull() {
  const rows = displayRows.value
  displayRowOffsetRowKeys = rows.map((row) => row.key)
  displayRowOffsetHeights = new Array(rows.length)
  displayRowKeyToIndex = new Map(rows.map((row, index) => [row.key, index]))
  const offsets = new Array(rows.length + 1)
  offsets[0] = 0
  let total = 0
  for (let i = 0; i < rows.length; i++) {
    const height = rowHeightForDisplayRow(rows[i])
    displayRowOffsetHeights[i] = height
    total += height
    offsets[i + 1] = total
  }
  displayRowOffsets.value = offsets
}

function syncDisplayRowOffsetsFromIndex(fromIndex) {
  const rows = displayRows.value
  if (
    rows.length !== displayRowOffsetRowKeys.length ||
    rows.some((row, index) => row.key !== displayRowOffsetRowKeys[index])
  ) {
    syncDisplayRowOffsetsFull()
    return
  }

  const offsets = displayRowOffsets.value
  if (offsets.length !== rows.length + 1) {
    syncDisplayRowOffsetsFull()
    return
  }

  const from = Math.max(0, Math.min(fromIndex, rows.length))
  const nextOffsets = offsets.slice(0, from + 1)
  let total = from > 0 ? nextOffsets[from] : 0
  for (let i = from; i < rows.length; i++) {
    const height = rowHeightForDisplayRow(rows[i])
    displayRowOffsetHeights[i] = height
    total += height
    nextOffsets[i + 1] = total
  }
  displayRowOffsets.value = nextOffsets
}

function minDisplayRowIndexForKeys(keys) {
  const rows = displayRows.value
  let minIndex = rows.length
  for (const key of keys) {
    const index = displayRowKeyToIndex.get(key)
    if (index != null && index < minIndex) minIndex = index
  }
  return minIndex
}

function scheduleMeasureVisibleDisplayRowHeights() {
  clearTimeout(displayRowMeasureTimer)
  displayRowMeasureTimer = setTimeout(() => {
    displayRowMeasureTimer = null
    measureVisibleDisplayRowHeights()
  }, DISPLAY_ROW_MEASURE_DEBOUNCE_MS)
}

function measureVisibleDisplayRowHeights() {
  const container = gridFocusRef.value
  if (!container) return

  const elements = container.querySelectorAll('[data-display-row-key]')
  let changed = false
  const changedKeys = []
  const next = new Map(displayRowHeightByKey.value)
  for (const el of elements) {
    const key = el.dataset.displayRowKey
    if (!key) continue
    const height = Math.ceil(el.getBoundingClientRect().height)
    if (height > 0 && next.get(key) !== height) {
      next.set(key, height)
      changedKeys.push(key)
      changed = true
    }
  }
  if (changed) {
    displayRowHeightByKey.value = next
    const fromIndex = minDisplayRowIndexForKeys(changedKeys)
    syncDisplayRowOffsetsFromIndex(fromIndex < displayRows.value.length ? fromIndex : 0)
  }
}

function pruneDisplayRowHeightCache(rows) {
  const validKeys = new Set((rows || []).map((row) => row.key))
  const next = new Map()
  let minRemovedIndex = rows?.length ?? 0
  for (const [key, height] of displayRowHeightByKey.value) {
    if (validKeys.has(key)) {
      next.set(key, height)
      continue
    }
    const index = displayRowKeyToIndex.get(key)
    if (index != null && index < minRemovedIndex) minRemovedIndex = index
  }
  if (next.size === displayRowHeightByKey.value.size) return
  displayRowHeightByKey.value = next
  if (minRemovedIndex < (rows?.length ?? 0)) {
    syncDisplayRowOffsetsFromIndex(minRemovedIndex)
  }
}

function computeVisibleSliceIndices() {
  const rows = displayRows.value
  if (!containerHeight.value || rows.length === 0) {
    return { startIndex: 0, endIndex: rows.length }
  }

  const offsets = displayRowOffsets.value
  const overscanPx = SCHEDULE_GRID_VIRTUAL_OVERSCAN_PX
  const viewStart = scrollTop.value
  const viewEnd = scrollTop.value + containerHeight.value
  const startIndex = includeMcHeaderForSlice(
    rows,
    findFirstVisibleDisplayRowIndex(offsets, Math.max(0, viewStart - overscanPx)),
  )
  const endIndex = Math.min(
    rows.length,
    Math.max(
      startIndex + 1,
      findExclusiveEndDisplayRowIndex(offsets, viewEnd + overscanPx, startIndex),
    ),
  )
  return { startIndex, endIndex }
}

function pruneDisplayRowHeightCacheForVisibleRange() {
  const rows = displayRows.value
  if (!rows.length) return

  const current = displayRowHeightByKey.value
  if (current.size === 0) return

  const { startIndex, endIndex } = computeVisibleSliceIndices()
  const margin = DISPLAY_ROW_HEIGHT_CACHE_MARGIN_ROWS
  const keepFrom = Math.max(0, startIndex - margin)
  const keepTo = Math.min(rows.length, endIndex + margin)
  const keepKeys = new Set()
  for (let i = keepFrom; i < keepTo; i++) {
    keepKeys.add(rows[i].key)
  }

  let hasOutsideCache = false
  for (const key of current.keys()) {
    if (!keepKeys.has(key)) {
      hasOutsideCache = true
      break
    }
  }
  if (!hasOutsideCache) return

  const next = new Map()
  for (let i = 0; i < rows.length; i++) {
    const key = rows[i].key
    const height = current.get(key)
    if (height == null) continue
    if (keepKeys.has(key)) {
      next.set(key, height)
    }
  }

  displayRowHeightByKey.value = next
  let minChangedIndex = rows.length
  for (let i = 0; i < rows.length; i++) {
    const key = rows[i].key
    const removedHeight = current.get(key)
    if (removedHeight == null || keepKeys.has(key)) continue
    const estimate = estimateScheduleGridDisplayRowHeight(rows[i])
    if (removedHeight !== estimate && i < minChangedIndex) {
      minChangedIndex = i
    }
  }
  if (minChangedIndex < rows.length) {
    syncDisplayRowOffsetsFromIndex(minChangedIndex)
  }
}

function schedulePruneDisplayRowHeightCacheForVisibleRange() {
  clearTimeout(displayRowPruneTimer)
  displayRowPruneTimer = setTimeout(() => {
    displayRowPruneTimer = null
    pruneDisplayRowHeightCacheForVisibleRange()
  }, DISPLAY_ROW_HEIGHT_PRUNE_DEBOUNCE_MS)
}

function findFirstVisibleDisplayRowIndex(offsets, target) {
  const rowCount = offsets.length - 1
  if (rowCount <= 0) return 0
  let lo = 0
  let hi = rowCount - 1
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2)
    if (offsets[mid + 1] <= target) lo = mid + 1
    else hi = mid
  }
  return lo
}

function findExclusiveEndDisplayRowIndex(offsets, target, startIndex) {
  const rowCount = offsets.length - 1
  if (rowCount <= 0) return 0
  let lo = startIndex
  let hi = rowCount
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2)
    if (offsets[mid] < target) lo = mid + 1
    else hi = mid
  }
  return lo
}

function includeMcHeaderForSlice(rows, startIndex) {
  if (startIndex <= 0) return startIndex
  let index = startIndex
  while (index > 0 && rows[index]?.type !== 'mc-header') {
    index -= 1
  }
  return rows[index]?.type === 'mc-header' ? index : startIndex
}

const virtualSliceRange = computed(() => {
  const rows = displayRows.value
  if (!containerHeight.value || rows.length === 0) {
    return { startIndex: 0, endIndex: rows.length, topPadding: 0, bottomPadding: 0 }
  }

  const offsets = displayRowOffsets.value
  const contentHeight = offsets[rows.length] ?? 0
  const totalHeight = contentHeight + SCHEDULE_GRID_SCROLL_END_SPACER_HEIGHT
  const overscanPx = SCHEDULE_GRID_VIRTUAL_OVERSCAN_PX
  const viewStart = scrollTop.value
  const viewEnd = scrollTop.value + containerHeight.value

  const startIndex = includeMcHeaderForSlice(
    rows,
    findFirstVisibleDisplayRowIndex(offsets, Math.max(0, viewStart - overscanPx)),
  )
  const endIndex = Math.min(
    rows.length,
    Math.max(
      startIndex + 1,
      findExclusiveEndDisplayRowIndex(offsets, viewEnd + overscanPx, startIndex),
    ),
  )

  return {
    startIndex,
    endIndex,
    topPadding: offsets[startIndex] ?? 0,
    bottomPadding: totalHeight - (offsets[endIndex] ?? contentHeight),
  }
})

const virtualVisibleDisplayRows = computed(() => {
  const rows = displayRows.value
  if (!containerHeight.value) return rows
  const { startIndex, endIndex } = virtualSliceRange.value
  return rows.slice(startIndex, endIndex)
})

const virtualTopPadding = computed(() => virtualSliceRange.value.topPadding)
const virtualBottomPadding = computed(() => virtualSliceRange.value.bottomPadding)

function updateGridVirtualScrollContainerSize() {
  const container = gridFocusRef.value
  if (!container) return
  containerHeight.value = container.clientHeight
}

function getExpandPanelFieldsRoot() {
  return gridFocusRef.value?.parentElement?.querySelector('.expand-panel-fields') ?? null
}

function blurExpandPanelFieldsIfFocused() {
  const active = document.activeElement
  if (!(active instanceof HTMLElement)) return false
  if (!active.closest('.expand-panel-fields')) return false
  active.blur()
  return true
}

function blurAllExpandPanelFields() {
  const fieldset = getExpandPanelFieldsRoot()
  if (!fieldset) return
  suppressExpandFieldFocusOut = true
  for (const el of fieldset.querySelectorAll('input, select, textarea')) {
    if (el instanceof HTMLElement) el.blur()
  }
  suppressExpandFieldFocusOut = false
  hideExpandFieldPreview()
  hideActiveCellInputOverlay()
}

function cancelPendingScrollTopUpdate() {
  if (scrollTopRafId != null) {
    cancelAnimationFrame(scrollTopRafId)
    scrollTopRafId = null
  }
  pendingScrollTop = null
}

function scheduleScrollTopUpdate(nextTop) {
  pendingScrollTop = nextTop
  if (scrollTopRafId != null) return
  scrollTopRafId = requestAnimationFrame(() => {
    scrollTopRafId = null
    if (pendingScrollTop == null) return
    scrollTop.value = pendingScrollTop
    pendingScrollTop = null
    blurExpandPanelFieldsIfFocused()
    if (activeCellInputOverlay.value.visible) {
      updateActiveCellInputOverlayPosition()
    }
    schedulePruneDisplayRowHeightCacheForVisibleRange()
    scheduleMeasureVisibleDisplayRowHeights()
  })
}

function handleGridScroll(event) {
  scheduleScrollTopUpdate(event.target.scrollTop)
}

function syncGridScrollTopFromContainer() {
  cancelPendingScrollTopUpdate()
  const container = gridFocusRef.value
  if (!container) return
  scrollTop.value = container.scrollTop
}

function focusWithoutScroll(element) {
  if (!(element instanceof HTMLElement)) return
  try {
    element.focus({ preventScroll: true })
  } catch {
    element.focus()
  }
}

function handleGridWheel() {
  blurExpandPanelFieldsIfFocused()
}

function detachGridVirtualScroll() {
  gridScrollResizeObserver?.disconnect()
  gridScrollResizeObserver = null
  clearTimeout(displayRowMeasureTimer)
  displayRowMeasureTimer = null
  clearTimeout(displayRowPruneTimer)
  displayRowPruneTimer = null
  cancelPendingScrollTopUpdate()
  const container = gridFocusRef.value
  if (container && gridScrollWheelHandler) {
    container.removeEventListener('wheel', gridScrollWheelHandler)
  }
  gridScrollWheelHandler = null
}

function attachGridVirtualScroll() {
  const container = gridFocusRef.value
  if (!container) return

  detachGridVirtualScroll()
  updateGridVirtualScrollContainerSize()
  syncGridScrollTopFromContainer()

  gridScrollWheelHandler = handleGridWheel
  container.addEventListener('wheel', gridScrollWheelHandler, { passive: true })

  if (typeof ResizeObserver !== 'undefined') {
    gridScrollResizeObserver = new ResizeObserver(() => {
      updateGridVirtualScrollContainerSize()
      scheduleMeasureVisibleDisplayRowHeights()
    })
    gridScrollResizeObserver.observe(container)
  }

  syncDisplayRowOffsetsFull()
  scheduleMeasureVisibleDisplayRowHeights()
}

