  if (filters.value.showLatestFilter) {
    return `全件表示に切替（現在: 最新${filters.value.latestLimit}件＋追加条件）`
  }
  return `最新${filters.value.latestLimit}件＋追加条件で表示`
})

function resolveEmployeeDisplayName(employeeId) {
  if (employeeId == null || employeeId === '') return ''
  const emp = employees.value.find((row) => Number(row.id) === Number(employeeId))
  return String(emp?.last_name ?? '').trim()
}

function resolveEmployeeTooltip(employeeId) {
  const name = resolveEmployeeDisplayName(employeeId)
  return name || '未入力'
}

function workNameCellTitle(item) {
  const label = workDisplayTitle(item)
  if (props.isMobile) {
    return `${label}（タップで行選択、ダブルタップでホームで案件を表示）`
