  return `${label}（クリックで行選択、再クリックまたはダブルクリックでスケジュール編集）`
}

const SCHEDULE_CELL_DOUBLE_CLICK_MS = 400
const NAVIGATE_CLICK_SUPPRESS_MS = 450
const scheduleCellLastMouseDown = { workId: null, columnIndex: null, at: 0 }
let navigateClickSuppressHandler = null
let navigateClickSuppressTimer = null
/** PC/タブレット: 1回目で行選択＋武装、同セル再クリックで起動 */
const rowActionArmed = ref(null)

function isRowActionArmed(workId, kind) {
  const armed = rowActionArmed.value
  return armed?.workId === String(workId) && armed?.kind === kind
}

function clearRowActionArmed() {
  rowActionArmed.value = null
}

function removeNavigateClickSuppress() {
  if (navigateClickSuppressHandler) {
    document.removeEventListener('click', navigateClickSuppressHandler, true)
    document.removeEventListener('mousedown', navigateClickSuppressHandler, true)
    document.removeEventListener('mouseup', navigateClickSuppressHandler, true)
    navigateClickSuppressHandler = null
  }
  if (navigateClickSuppressTimer) {
    clearTimeout(navigateClickSuppressTimer)
    navigateClickSuppressTimer = null
  }
}

function suppressNavigateClickLeak() {
  removeNavigateClickSuppress()
  const suppressUntil = Date.now() + NAVIGATE_CLICK_SUPPRESS_MS
  navigateClickSuppressHandler = (event) => {
    if (Date.now() >= suppressUntil) {
      removeNavigateClickSuppress()
      return
    }
    event.preventDefault()
    event.stopPropagation()
    event.stopImmediatePropagation?.()
  }
  document.addEventListener('click', navigateClickSuppressHandler, true)
  document.addEventListener('mousedown', navigateClickSuppressHandler, true)
  document.addEventListener('mouseup', navigateClickSuppressHandler, true)
  navigateClickSuppressTimer = window.setTimeout(
    removeNavigateClickSuppress,
    NAVIGATE_CLICK_SUPPRESS_MS + 50,
  )
}

function triggerRowNameNavigate(workId, kind) {
  suppressNavigateClickLeak()
  if (kind === 'work') handleWorkNameDoubleClick(workId)
  else handleEmployeeDoubleClick(workId)
}

function selectionMemoForWorkRow(workId) {
  const bounds = selectionBounds()
  if (!bounds) return ''
  const row = workRowIndex(workId)
  if (row < 0) return ''
  if (row < bounds.minRow || row > bounds.maxRow) return ''
  return `${bounds.minCol}:${bounds.maxCol}`
}

const rowActionArmedMemoKey = computed(() => {
  const armed = rowActionArmed.value
  return armed ? `${armed.workId}:${armed.kind}` : ''
})

function activeCellMemoForWorkRow(workId) {
  const cell = activeCell.value
  if (!cell || cell.workId !== String(workId)) return ''
  return String(cell.columnIndex)
}

function scheduleGridWorkRowMemo(displayRow) {
  const wid = String(displayRow.item.work_id)
  return [
    wid,
    rowsRevisionByWorkId.value.get(wid) ?? 0,
    activeCellMemoForWorkRow(wid),
    selectionMemoForWorkRow(wid),
    rowActionArmedMemoKey.value,
  ]
}

function syncEditorTextDraftsFromRow(row) {
  editorLabelDraft.value = row?.label ?? ''
  editorNoteDraft.value = row?.note ?? ''
}

function applyEditorDraftsToExpandedRow() {
  if (!expandedEditor.value?.row) return
  expandedEditor.value.row.label = editorLabelDraft.value
  expandedEditor.value.row.note = editorNoteDraft.value
}

function recomputeExpandCellPreviewText() {
  if (!expandedEditor.value) return '—'
  const edited = editorRow.value
  const text = formatScheduleGridCellFull(
    {
      schedule_status_id: edited.schedule_status_id ?? null,
      schedule_secondary_status_id: edited.schedule_secondary_status_id ?? null,
      label: editorLabelDraft.value,
      start_on: edited.start_on || null,
      end_on: edited.end_on || null,
      note: editorNoteDraft.value,
    },
    statusOptions.value,
  )
  return text || '—'
}

function flushExpandCellPreviewUpdate() {
  clearTimeout(expandCellPreviewDebounceTimer)
  expandCellPreviewDebounceTimer = null
  expandCellPreviewText.value = recomputeExpandCellPreviewText()
  syncActiveCellInputOverlayPosition()
}

function scheduleExpandCellPreviewUpdate() {
  clearTimeout(expandCellPreviewDebounceTimer)
  expandCellPreviewDebounceTimer = setTimeout(() => {
    expandCellPreviewDebounceTimer = null
    expandCellPreviewText.value = recomputeExpandCellPreviewText()
    syncActiveCellInputOverlayPosition()
  }, EXPAND_CELL_PREVIEW_DEBOUNCE_MS)
}

function findActiveScheduleCellElement() {
  const container = gridFocusRef.value
  const cell = activeCell.value
  if (!container || !cell) return null

  const wid = String(cell.workId)
  const col = String(cell.columnIndex)
  for (const el of container.querySelectorAll('td.col-schedule[data-schedule-work-id][data-schedule-col]')) {
    if (!(el instanceof HTMLElement)) continue
    if (el.dataset.scheduleWorkId === wid && el.dataset.scheduleCol === col) {
      return el
    }
  }

  const fallback = container.querySelector('td.schedule-grid-cell--active')
  return fallback instanceof HTMLElement ? fallback : null
}

function syncActiveCellInputOverlayPosition() {
  if (!shouldShowActiveCellInputOverlay()) {
    hideActiveCellInputOverlay()
    return
  }
  nextTick(() => {
    if (!shouldShowActiveCellInputOverlay()) {
      hideActiveCellInputOverlay()
      return
    }
    const cell = findActiveScheduleCellElement()
    if (!cell) {
      hideActiveCellInputOverlay()
      return
    }
    const rect = cell.getBoundingClientRect()
    activeCellInputOverlay.value = {
      visible: true,
      x: rect.left,
      y: rect.top,
      width: rect.width,
      height: rect.height,
    }
  })
}

function updateActiveCellInputOverlayPosition() {
  syncActiveCellInputOverlayPosition()
}

function shouldShowActiveCellInputOverlay() {
  if (!activeCell.value || !expandedEditor.value) return false
  return isEditorInputFocused()
}

function hideActiveCellInputOverlay() {
  if (!activeCellInputOverlay.value.visible) return
  activeCellInputOverlay.value = { visible: false, x: 0, y: 0, width: 0, height: 0 }
}

function dismissInputPreviewsForActiveCellChange() {
  clearTimeout(expandCellPreviewDebounceTimer)
  expandCellPreviewDebounceTimer = null
  hideAllInputPreviews()
}

function onEditorTextDraftInput() {
  applyEditorDraftsToExpandedRow()
  scheduleExpandCellPreviewUpdate()
}

function clearEditorInputSelectionState() {
  blurAllExpandPanelFields()
  if (hiddenInput.value instanceof HTMLElement && document.activeElement === hiddenInput.value) {
    hiddenInput.value.blur()
  }
  resetHiddenNoteInputState()
}

function onExpandTextInputBlur() {
  flushScheduledEditorSync()
}

function onEditorLabelInputEnter(event) {
  if (event.isComposing) return
  event.preventDefault()
  event.stopPropagation()
  flushScheduledEditorSync()
  flushExpandCellPreviewUpdate()
  const target = event.target
  if (target instanceof HTMLInputElement) {
    target.blur()
  }
}

function onEditorNoteInputEnter(event) {
  if (event.isComposing) return
  event.preventDefault()
  event.stopPropagation()
  flushScheduledEditorSync()
  flushExpandCellPreviewUpdate()
  const target = event.target
  if (target instanceof HTMLInputElement) {
    target.blur()
  }
  resetHiddenNoteInputState()
  focusHiddenInput()
}

function onWorkRowNameClick(event, workId) {
  onRowNameTwoStepClick(workId, 'work', event)
}

function onEmployeeRowClick(event, workId) {
  onRowNameTwoStepClick(workId, 'employee', event)
}

function onRowNameTwoStepClick(workId, kind, event) {
  if (event?.detail >= 2) return

  const wid = String(workId)
  if (isRowActionArmed(wid, kind)) {
    clearRowActionArmed()
    triggerRowNameNavigate(workId, kind)
    return
  }
  selectWorkRowScheduleColumns(workId, { extend: Boolean(event?.shiftKey) })
  rowActionArmed.value = { workId: wid, kind }
}

function onRowNameDblClick(event, workId, kind) {
  if (props.isMobile) return
  event.preventDefault()
  event.stopPropagation()
  clearRowActionArmed()
  triggerRowNameNavigate(workId, kind)
}

function workDisplayPrefix(item) {
  return scheduleGridWorkDisplayPrefix(item, largeSteps.value)
}

function workDisplayLineRows(item) {
  const prefix = workDisplayPrefix(item)
  const { line1, line2 } = scheduleGridWorkDisplayLines(item, prefix)
  return [line1, line2].filter(Boolean)
}

function workDisplayTitle(item) {
  return scheduleGridWorkFullDisplayTitle(item, workDisplayPrefix(item))
}

function getRowsForWork(workId) {
  return rowsByWorkId.value.get(String(workId)) || padWorkLargeScheduleRows([])
}

let cellsByWorkIdCache = new Map()

function clearCellsByWorkIdCache() {
  cellsByWorkIdCache.clear()
}

function getCellsForWork(workId) {
  const wid = String(workId)
  const revision = rowsRevisionByWorkId.value.get(wid) ?? 0
  const cached = cellsByWorkIdCache.get(wid)
  if (cached?.revision === revision) return cached.cells
  const cells = buildScheduleRowsByColumnIndex(
    getRowsForWork(workId),
    scheduleLabelTemplateById(labelTemplatesForWorkId(workId)),
  )
  cellsByWorkIdCache.set(wid, { revision, cells })
  return cells
}

function cellDisplayText(workId, columnIndex) {
  return formatScheduleGridCellFull(getCellsForWork(workId)[columnIndex], statusOptions.value)
}

function workRowIndex(workId) {
  return gridRows.value.findIndex((item) => String(item.work_id) === String(workId))
}

function selectionBounds() {
  if (!selectionAnchor.value || !selectionEnd.value) return null
  const r1 = workRowIndex(selectionAnchor.value.workId)
  const r2 = workRowIndex(selectionEnd.value.workId)
  const c1 = selectionAnchor.value.columnIndex
  const c2 = selectionEnd.value.columnIndex
  if (r1 < 0 || r2 < 0) return null
  return {
    minRow: Math.min(r1, r2),
    maxRow: Math.max(r1, r2),
    minCol: Math.min(c1, c2),
    maxCol: Math.max(c1, c2),
  }
}

function isCellInSelection(workId, columnIndex) {
  const bounds = selectionBounds()
  if (!bounds) return false
  const row = workRowIndex(workId)
  if (row < 0) return false
  return (
    row >= bounds.minRow &&
    row <= bounds.maxRow &&
    columnIndex >= bounds.minCol &&
    columnIndex <= bounds.maxCol
  )
}

function isWorkRowInSelection(workId) {
  const bounds = selectionBounds()
  if (!bounds) return false
  const row = workRowIndex(workId)
  if (row < 0) return false
  return row >= bounds.minRow && row <= bounds.maxRow
}

function isActiveWorkRow(workId) {
  return activeCell.value?.workId === String(workId)
}

function isActiveCell(workId, columnIndex) {
  return (
    activeCell.value &&
    activeCell.value.workId === String(workId) &&
    activeCell.value.columnIndex === columnIndex
  )
}

function iterateSelectionCells(callback) {
  const bounds = selectionBounds()
  if (!bounds) return
  for (let r = bounds.minRow; r <= bounds.maxRow; r++) {
    const item = gridRows.value[r]
    if (!item) continue
    for (let c = bounds.minCol; c <= bounds.maxCol; c++) {
      callback(String(item.work_id), c)
    }
  }
}

function getColumnCellsForWork(workId, rows) {
  return buildScheduleRowsByColumnIndex(
    rows ?? getRowsForWork(workId),
    scheduleLabelTemplateById(labelTemplatesForWorkId(workId)),
  )
}

function collectCellChangesForWork(workId, previousRows, nextRows) {
  return collectCellChangesFromColumnCells(
    workId,
    getColumnCellsForWork(workId, previousRows),
    getColumnCellsForWork(workId, nextRows),
  )
}

function resolveRowIndexForColumnCell(workId, rows, columnIndex, cellRow, previousRow) {
  if (previousRow?.id != null && previousRow.id !== '') {
    const byId = rows.findIndex((row) => String(row.id) === String(previousRow.id))
    if (byId >= 0) return byId
  }
  if (cellRow?.id != null && cellRow.id !== '') {
    const byId = rows.findIndex((row) => String(row.id) === String(cellRow.id))
    if (byId >= 0) return byId
  }
  if (cellRow?.sort_order != null) {
    const byOrder = rows.findIndex((row) => Number(row.sort_order) === Number(cellRow.sort_order))
    if (byOrder >= 0) return byOrder
  }
  const templateById = scheduleLabelTemplateById(labelTemplatesForWorkId(workId))
  const col = Number(columnIndex)
  for (let i = 0; i < rows.length; i++) {
    const tplId = rows[i]?.schedule_label_template_id
    const tpl = tplId != null && tplId !== '' ? templateById.get(String(tplId)) : null
    if (parseScheduleColumnIndex(tpl?.schedule_column_index) === col) return i
  }
  return -1
}

function entryAffectsWorkId(entry, workId) {
  const wid = String(workId)
  if (entry.type === 'batch-cells') {
    return entry.changes.some((change) => String(change.workId) === wid)
  }
  if (entry.type === 'cell') {
    return String(entry.workId) === wid
  }
  return false
}

function setBaselineForWork(workId, rows) {
  const next = new Map(savedBaselineByWorkId.value)
  next.set(String(workId), cloneRows(rows))
  savedBaselineByWorkId.value = next
}

function applySavedScheduleBatch(savedItems) {
  if (!Array.isArray(savedItems) || savedItems.length === 0) {
    dirtyWorkIds.value = new Set()
    undoHistory.value = []
    return []
  }

  const affectedWorkIds = []
  const nextRowsByWorkId = new Map(rowsByWorkId.value)
  const nextBaseline = new Map(savedBaselineByWorkId.value)
  const gridItems = allGridItems.value
  const gridIndexByWorkId = new Map(
    gridItems.map((item, index) => [String(item.work_id), index]),
  )
  let nextAllGridItems = null

  for (const item of savedItems) {
    const wid = String(item.work_id)
    const savedRows = padWorkLargeScheduleRows(item.rows || [])
    nextRowsByWorkId.set(wid, cloneRows(savedRows))
    nextBaseline.set(wid, cloneRows(savedRows))
    affectedWorkIds.push(wid)

    const gridIndex = gridIndexByWorkId.get(wid)
    if (gridIndex != null) {
      if (!nextAllGridItems) nextAllGridItems = gridItems.slice()
      nextAllGridItems[gridIndex] = {
        ...nextAllGridItems[gridIndex],
        rows: item.rows || [],
      }
    }
  }

  dirtyWorkIds.value = new Set()
  undoHistory.value = []
  savedBaselineByWorkId.value = nextBaseline
  rowsByWorkId.value = nextRowsByWorkId
  clearCellsByWorkIdCache()
  if (nextAllGridItems) {
    allGridItems.value = nextAllGridItems
  }
  bumpRowsRevisionForWorkIds(affectedWorkIds)

  return savedItems.map((item) => ({
    workId: String(item.work_id),
    rows: item.rows || [],
  }))
}

function syncDirtyWorkIdForWork(workId) {
  const wid = String(workId)
  const baseline = savedBaselineByWorkId.value.get(wid)
  if (!baseline) return
  if (
    columnCellsDifferFromBaseline(
      getColumnCellsForWork(wid),
      getColumnCellsForWork(wid, baseline),
    )
  ) {
    dirtyWorkIds.value.add(wid)
  } else {
    dirtyWorkIds.value.delete(wid)
  }
}

function isCellDirty(workId, columnIndex) {
  const wid = String(workId)
  const baseline = savedBaselineByWorkId.value.get(wid)
  if (!baseline) return false
  return isCellDirtyAtColumn(
    columnIndex,
    getColumnCellsForWork(wid),
    getColumnCellsForWork(wid, baseline),
  )
}

function pushCellChangesUndo(changes) {
  if (!changes.length) return
  if (changes.length === 1) {
    pushUndo({ type: 'cell', ...changes[0] })
    return
  }
  pushUndo({
    type: 'batch-cells',
    changes: changes.map((change) => ({
      workId: String(change.workId),
      columnIndex: change.columnIndex,
      previousRow: cloneScheduleRowForUndo(change.previousRow),
    })),
  })
}

function applyCellUndo({ workId, columnIndex, previousRow }) {
  const wid = String(workId)
  const col = Number(columnIndex)
  const rows = cloneRows(getRowsForWork(wid))
  const currentCell = getColumnCellsForWork(wid, rows)[col]
  const targetIndex = resolveRowIndexForColumnCell(wid, rows, col, currentCell, previousRow)
  if (targetIndex < 0) return

  const cleared = {
    schedule_status_id: null,
    schedule_secondary_status_id: null,
    label: '',
    start_on: null,
    end_on: null,
    note: '',
  }
  rows[targetIndex] = previousRow
    ? {
        ...rows[targetIndex],
        ...cloneScheduleRowForUndo(previousRow),
        sort_order: rows[targetIndex].sort_order,
        id: previousRow.id ?? rows[targetIndex].id ?? null,
      }
    : {
        ...rows[targetIndex],
        ...cleared,
      }
  setRowsForWork(wid, rows)
}

function applyWorkChanges(workChanges) {
  const cellChanges = []
  for (const [wid, nextRows] of workChanges) {
    cellChanges.push(...collectCellChangesForWork(wid, getRowsForWork(wid), nextRows))
    setRowsForWork(wid, nextRows)
    syncDirtyWorkIdForWork(wid)
  }
  if (cellChanges.length) {
    pushCellChangesUndo(cellChanges)
    if (activeCell.value) refreshExpandedEditorFromRows(activeCell.value.workId)
  }
}

function cellClass(workId, columnIndex) {
  const row = getCellsForWork(workId)[columnIndex]
  const classes = []
  if (!row) {
    classes.push('schedule-grid-cell--empty')
  } else {
    const highlight = getScheduleRowHighlightKey(row, statusOptions.value)
    if (highlight) classes.push(`schedule-grid-cell--${highlight}`)
  }
  if (isCellInSelection(workId, columnIndex)) {
    classes.push('schedule-grid-cell--in-selection')
  }
  if (isActiveCell(workId, columnIndex)) {
    classes.push('schedule-grid-cell--active')
  }
  if (isCellDirty(workId, columnIndex)) {
    classes.push('schedule-grid-cell--dirty')
  }
  return classes
}

function isWorkRowCompleted(item) {
  return isScheduleGridWorkRowCompleted(item, completedProgressiveStatusIds.value)
}

function isWorkRowInspection(item) {
  return isScheduleGridWorkRowInspection(item, largeSteps.value)
}

function cloneRows(rows) {
  return padWorkLargeScheduleRows(rows).map((row) => ({ ...row }))
}

function pushUndo(entry) {
  undoHistory.value.push(entry)
  if (undoHistory.value.length > MAX_UNDO) undoHistory.value.shift()
}

function setRowsForWork(workId, rows) {
  const wid = String(workId)
  rowsByWorkId.value.set(wid, cloneRows(rows))
  bumpRowsRevisionForWorkIds([wid])
  scheduleMeasureVisibleDisplayRowHeights()
}

function bumpRowsRevisionForWorkIds(workIds) {
  for (const workId of workIds) {
    const wid = String(workId)
    rowsRevisionByWorkId.value.set(wid, (rowsRevisionByWorkId.value.get(wid) ?? 0) + 1)
  }
  triggerRef(rowsRevisionByWorkId)
}

function syncActiveCellEditor(workId, columnIndex) {
  const wid = String(workId)
  const row = getCellsForWork(workId)[columnIndex]
  if (row) {
    expandedEditor.value = {
      workId: wid,
      columnIndex,
      row: {
        ...row,
        label: row.label ?? '',
        start_on: row.start_on ?? '',
        end_on: row.end_on ?? '',
        note: row.note ?? '',
      },
    }
    syncEditorTextDraftsFromRow(expandedEditor.value.row)
    flushExpandCellPreviewUpdate()
  } else {
    expandedEditor.value = null
    syncEditorTextDraftsFromRow(null)
    expandCellPreviewText.value = '—'
  }
}

function resetHiddenNoteInputState() {
  hiddenNoteEditing.value = false
  hiddenNoteAppendBase.value = ''
  hiddenInputValue.value = ''
  isHiddenComposing.value = false
  hideActiveCellInputOverlay()
}

function beginHiddenNoteAppendSession() {
  if (hiddenNoteEditing.value) return
  hiddenNoteAppendBase.value = editorNoteDraft.value
  hiddenNoteEditing.value = true
}

function applyHiddenInputToNoteDraft(appendSegment) {
  beginHiddenNoteAppendSession()
  editorNoteDraft.value = hiddenNoteAppendBase.value + appendSegment
  scheduleExpandCellPreviewUpdate()
}

function canUseHiddenInput() {
  return (
    !props.isMobile &&
    props.isTabActive &&
    !saving.value &&
    activeCell.value &&
    expandedEditor.value &&
    !isEditorInputFocused()
  )
}

function canCaptureHiddenNoteInput() {
  return canUseHiddenInput() && !rowActionArmed.value
}

let suppressHiddenInputFocus = false

function isTouchPointerType(pointerType) {
  return pointerType === 'touch' || pointerType === 'pen'
}

function updateHiddenInputFocusModeFromPointer(event) {
  if (!event?.pointerType) return
  if (isTouchPointerType(event.pointerType)) {
    suppressHiddenInputFocus = true
  } else if (event.pointerType === 'mouse') {
    suppressHiddenInputFocus = false
  }
}

function onScheduleGridPointerDown(event) {
  if (props.isMobile) return
  updateHiddenInputFocusModeFromPointer(event)
}

function focusHiddenInput() {
  if (suppressHiddenInputFocus) return
  if (!canUseHiddenInput()) return
  nextTick(() => {
    focusWithoutScroll(hiddenInput.value)
  })
}

function onGridWrapFocus(event) {
  if (event.target === gridFocusRef.value) {
    focusHiddenInput()
  }
}

function focusEditorNoteInput() {
  if (!expandedEditor.value) return
  nextTick(() => {
    const input = editorNoteInputRef.value
    if (!(input instanceof HTMLInputElement)) return
    focusWithoutScroll(input)
    const len = input.value.length
    input.setSelectionRange(len, len)
    hiddenInputValue.value = ''
    hiddenNoteEditing.value = false
    hiddenNoteAppendBase.value = ''
    flushExpandCellPreviewUpdate()
  })
}

function handleHiddenCompositionStart() {
  if (!canCaptureHiddenNoteInput()) {
    isHiddenComposing.value = false
    hiddenInputValue.value = ''
    return
  }

  isHiddenComposing.value = true
  beginHiddenNoteAppendSession()
  scheduleExpandCellPreviewUpdate()
}

function handleHiddenCompositionUpdate(event) {
  if (!canCaptureHiddenNoteInput() || !isHiddenComposing.value) return
  applyHiddenInputToNoteDraft(event.data || '')
}

function handleHiddenCompositionEnd(event) {
  if (!canCaptureHiddenNoteInput()) {
    isHiddenComposing.value = false
    hiddenInputValue.value = ''
    return
  }

  isHiddenComposing.value = false
  applyHiddenInputToNoteDraft(event.data || hiddenInputValue.value)
  hiddenInputValue.value = ''
  focusEditorNoteInput()
}

function handleHiddenInput(event) {
  if (isHiddenComposing.value) return
  if (!canCaptureHiddenNoteInput()) {
    event.target.value = ''
    hiddenInputValue.value = ''
    return
  }

  const value = event.target.value
  if (!hiddenNoteEditing.value && !value) return

  applyHiddenInputToNoteDraft(value)
}

function handleHiddenKeyDown(event) {
  handleGridKeyDown(event)
}

function handleHiddenBlur(event) {
  if (props.isMobile) return
  if (contextMenu.value.visible) return

  if (event.relatedTarget instanceof Element) {
    const related = event.relatedTarget
    if (related.closest('.schedule-grid-context-menu')) return
    if (related.closest('.expand-panel-fields')) return
    if (related.closest('.modal-overlay') || related.closest('.modal-content')) return
    if (related.closest('.schedule-grid-filters')) return
    if (related.tagName === 'SELECT') return
  }

  setTimeout(() => {
    if (contextMenu.value.visible) return
    if (suppressHiddenInputFocus) return
    if (!canUseHiddenInput()) return
    const active = document.activeElement
    if (active instanceof Element) {
      if (active.closest('.schedule-grid-context-menu')) return
      if (active.closest('.expand-panel-fields')) return
      if (active.closest('.modal-overlay') || active.closest('.modal-content')) return
      if (active.closest('.schedule-grid-filters')) return
      if (active.tagName === 'SELECT') return
    }
    focusWithoutScroll(hiddenInput.value)
  }, 0)
}

function selectCell(workId, columnIndex, { extend = false } = {}) {
  closeContextMenu()
  flushArrowNavCoalesce()
  dismissInputPreviewsForActiveCellChange()
  clearEditorInputSelectionState()
  flushScheduledEditorSync()
  clearRowActionArmed()
  const wid = String(workId)
  activeCell.value = { workId: wid, columnIndex }
  if (extend && selectionAnchor.value) {
    selectionEnd.value = { workId: wid, columnIndex }
  } else {
    selectionAnchor.value = { workId: wid, columnIndex }
    selectionEnd.value = { workId: wid, columnIndex }
  }
  syncActiveCellEditor(workId, columnIndex)
  focusHiddenInput()
}

/** 物件名クリック: 列 0–13 を選択、アクティブセルは列 0 */
function selectWorkRowScheduleColumns(workId, { extend = false } = {}) {
