function hideExpandFieldPreview() {
  expandFieldPreviewAnchorEl = null
  expandFieldPreview.value = { visible: false, x: 0, y: 0 }
}

function hideAllInputPreviews() {
  hideExpandFieldPreview()
  hideActiveCellInputOverlay()
}

function adjustExpandFieldPreviewPosition(anchorX, anchorY) {
  const el = expandFieldPreviewRef.value
  if (!el || !expandFieldPreview.value.visible) return

  const rect = el.getBoundingClientRect()
  const padding = CONTEXT_MENU_VIEWPORT_PADDING
  const maxX = window.innerWidth - padding
  const maxY = window.innerHeight - padding

  let x = anchorX
  let y = anchorY - rect.height - 4

  if (y < padding) {
    y = Math.min(anchorY + 4, maxY - rect.height)
  }
  if (x + rect.width > maxX) {
    x = maxX - rect.width
  }
  x = Math.max(padding, x)

  expandFieldPreview.value = { visible: true, x, y }
}

function updateExpandFieldPreviewPosition(el) {
  if (!el?.getBoundingClientRect) return
  expandFieldPreviewAnchorEl = el
  const rect = el.getBoundingClientRect()
  expandFieldPreview.value = { visible: true, x: rect.left, y: rect.top }
  nextTick(() => {
    adjustExpandFieldPreviewPosition(rect.left, rect.top)
  })
}

function onExpandFieldFocusIn(event) {
  closeContextMenu()
  const target = event.target
  if (!(target instanceof HTMLSelectElement || target instanceof HTMLInputElement)) return
  updateExpandFieldPreviewPosition(target)
  flushExpandCellPreviewUpdate()
}

function onExpandFieldFocusOut(event) {
  if (suppressExpandFieldFocusOut) return
  const fieldset = event.currentTarget
  const next = event.relatedTarget
  if (next instanceof Node && fieldset.contains(next)) return
  flushScheduledEditorSync()
  hideExpandFieldPreview()
  hideActiveCellInputOverlay()
  if (!activeCell.value) return
  focusHiddenInput()
}

function onExpandFieldPreviewReposition() {
  if (expandFieldPreviewAnchorEl) {
    const rect = expandFieldPreviewAnchorEl.getBoundingClientRect()
    adjustExpandFieldPreviewPosition(rect.left, rect.top)
  }
  if (activeCellInputOverlay.value.visible) {
    updateActiveCellInputOverlayPosition()
  }
}

function clearExpandedEditor() {
  flushScheduledEditorSync()
  blurAllExpandPanelFields()
  hideAllInputPreviews()
  clearRowActionArmed()
  activeCell.value = null
  selectionAnchor.value = null
  selectionEnd.value = null
  isDraggingSelection.value = false
  expandedEditor.value = null
  syncEditorTextDraftsFromRow(null)
  expandCellPreviewText.value = '—'
  resetHiddenNoteInputState()
  closeContextMenu()
}

function flushScheduledEditorSync() {
  applyEditorDraftsToExpandedRow()
  syncEditorToRows()
  flushExpandCellPreviewUpdate()
}

function syncEditorToRows() {
  if (!expandedEditor.value) return
  const { workId, columnIndex, row: edited } = expandedEditor.value
  const wid = String(workId)
  const col = Number(columnIndex)
  const nextRows = cloneRows(getRowsForWork(wid))
  const currentCell = getColumnCellsForWork(wid, nextRows)[col]
  const targetIndex = resolveRowIndexForColumnCell(wid, nextRows, col, currentCell, edited)
  if (targetIndex < 0) return
  const target = nextRows[targetIndex]
  if (String(target.id) !== String(edited.id)) return

  const proposed = {
    ...target,
    schedule_status_id: edited.schedule_status_id ?? null,
    schedule_secondary_status_id: edited.schedule_secondary_status_id ?? null,
    label: editorLabelDraft.value ?? '',
    start_on: edited.start_on || null,
    end_on: edited.end_on || null,
    note: editorNoteDraft.value ?? '',
  }
  if (scheduleCellContentEqual(currentCell, proposed)) return

  pushCellChangesUndo([
    {
      workId: wid,
      columnIndex: col,
      previousRow: cloneScheduleRowForUndo(currentCell),
    },
  ])
  nextRows[targetIndex] = proposed
  setRowsForWork(wid, nextRows)
  syncDirtyWorkIdForWork(wid)
}

function refreshExpandedEditorFromRows(workId) {
  if (!activeCell.value || String(activeCell.value.workId) !== String(workId)) return
  syncActiveCellEditor(workId, activeCell.value.columnIndex)
}

function clearSelectedCells() {
  const bounds = selectionBounds()
  if (!bounds || saving.value) return

  const workChanges = new Map()
  iterateSelectionCells((workId, col) => {
    const cellRow = getCellsForWork(workId)[col]
    if (!cellRow) return
    if (!workChanges.has(workId)) {
      workChanges.set(workId, cloneRows(getRowsForWork(workId)))
    }
    const target = workChanges.get(workId).find((row) => String(row.id) === String(cellRow.id))
    if (!target) return
    target.schedule_status_id = null
    target.schedule_secondary_status_id = null
    target.label = ''
    target.start_on = null
    target.end_on = null
    target.note = ''
  })
  applyWorkChanges(workChanges)
}

function clearEditorCellFields() {
  clearSelectedCells()
}

function closeContextMenu() {
  contextMenu.value = { visible: false, x: 0, y: 0 }
}

function openContextMenu(event) {
  const clickX = event.clientX
  const clickY = event.clientY
  contextMenu.value = { visible: true, x: clickX, y: clickY }
  nextTick(() => {
    adjustContextMenuPosition(clickX, clickY)
  })
}

function adjustContextMenuPosition(clickX, clickY) {
  const el = contextMenuRef.value
  if (!el || !contextMenu.value.visible) return

  const rect = el.getBoundingClientRect()
  const padding = CONTEXT_MENU_VIEWPORT_PADDING
  const maxX = window.innerWidth - padding
  const maxY = window.innerHeight - padding

  let x = clickX
  let y = clickY

  if (x + rect.width > maxX) {
    x = clickX - rect.width
  }
  if (y + rect.height > maxY) {
    y = clickY - rect.height
  }

  x = Math.max(padding, Math.min(x, maxX - rect.width))
  y = Math.max(padding, Math.min(y, maxY - rect.height))

  contextMenu.value = { visible: true, x, y }
}

function isEditorInputFocused() {
  const el = document.activeElement
  return el?.closest?.('.expand-panel-fields') != null
}

function isExpandPanelTextInputFocused() {
  const el = document.activeElement
  return (
    el instanceof HTMLInputElement &&
    el.type === 'text' &&
    el.closest('.expand-panel-fields') != null
  )
}

function isScheduleGridKeyboardTargetFocused() {
  const active = document.activeElement
  if (active === hiddenInput.value) return true
  return gridFocusRef.value?.contains(active) ?? false
}

function isMultiCellSelection() {
  const bounds = selectionBounds()
  if (!bounds) return false
  return bounds.minRow !== bounds.maxRow || bounds.minCol !== bounds.maxCol
}

function applySelectionStatus1Transition(resolveNextStatusId) {
  const workChanges = new Map()
  iterateSelectionCells((workId, col) => {
    const cellRow = getCellsForWork(workId)[col]
    if (!cellRow) return

    const nextStatusId = resolveNextStatusId(
      cellRow.schedule_status_id,
      statusOptions.value,
    )
    if (nextStatusId === undefined) return

    const wid = String(workId)
    if (!workChanges.has(wid)) {
      workChanges.set(wid, cloneRows(getRowsForWork(wid)))
    }
    const target = workChanges
      .get(wid)
      .find((row) => String(row.id) === String(cellRow.id))
    if (target) target.schedule_status_id = nextStatusId
  })

  if (workChanges.size === 0) return
  applyWorkChanges(workChanges)
}

function cycleSelectionStatus1Advance() {
  applySelectionStatus1Transition(nextScheduleStatus1IdForAdvance)
}

function cycleSelectionStatus1Retreat() {
  applySelectionStatus1Transition(prevScheduleStatus1IdForRetreat)
}

async function copySelection() {
  const bounds = selectionBounds()
  if (!bounds) return
  const cells = []
  for (let r = bounds.minRow; r <= bounds.maxRow; r++) {
    const item = gridRows.value[r]
    const row = []
    for (let c = bounds.minCol; c <= bounds.maxCol; c++) {
      row.push(scheduleGridClipboardCell(getCellsForWork(item.work_id)[c]))
    }
    cells.push(row)
  }
  try {
    await navigator.clipboard.writeText(serializeScheduleGridClipboard(cells))
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] copy failed:', err)
  }
}

async function pasteFromClipboard() {
  if (!activeCell.value) return
  let text
  try {
    text = await navigator.clipboard.readText()
  } catch {
    return
  }
  const cells = parseScheduleGridClipboard(text)
  if (!cells?.length) return

  const workChanges = new Map()

  if (isSingleScheduleGridClipboardCell(cells)) {
    const clipCell = cells[0][0]
    const applyClipCell = (workId, col) => {
      const cellRow = getCellsForWork(workId)[col]
      if (!cellRow) return
      if (!workChanges.has(workId)) {
        workChanges.set(workId, cloneRows(getRowsForWork(workId)))
      }
      const target = workChanges
        .get(workId)
        .find((row) => String(row.id) === String(cellRow.id))
      if (target) applyScheduleGridClipboardCell(target, clipCell)
    }

    if (selectionBounds()) {
      iterateSelectionCells(applyClipCell)
    } else {
      applyClipCell(activeCell.value.workId, activeCell.value.columnIndex)
    }
  } else {
    const startRow = workRowIndex(activeCell.value.workId)
    const startCol = activeCell.value.columnIndex
    if (startRow < 0) return

    for (let dr = 0; dr < cells.length; dr++) {
      const gridRowIndex = startRow + dr
      if (gridRowIndex >= gridRows.value.length) break
      const item = gridRows.value[gridRowIndex]
      const wid = String(item.work_id)
      const clipRow = cells[dr]
      if (!Array.isArray(clipRow)) continue

      for (let dc = 0; dc < clipRow.length; dc++) {
        const col = startCol + dc
        if (col >= WORK_LARGE_SCHEDULE_COUNT) break
        const targetCell = getCellsForWork(wid)[col]
        if (!targetCell) continue

        if (!workChanges.has(wid)) {
          workChanges.set(wid, cloneRows(getRowsForWork(wid)))
        }
        const nextRows = workChanges.get(wid)
        const target = nextRows.find((row) => String(row.id) === String(targetCell.id))
        if (target) applyScheduleGridClipboardCell(target, clipRow[dc])
      }
    }
  }

  applyWorkChanges(workChanges)
}

function bulkApplyStatus1(statusId) {
  const workChanges = new Map()
  iterateSelectionCells((workId, col) => {
    const cellRow = getCellsForWork(workId)[col]
    if (!cellRow) return
    if (!workChanges.has(workId)) {
      workChanges.set(workId, cloneRows(getRowsForWork(workId)))
    }
    const target = workChanges.get(workId).find((row) => String(row.id) === String(cellRow.id))
    if (target) target.schedule_status_id = statusId
  })
  applyWorkChanges(workChanges)
}

function flushArrowNavCoalesce() {
  clearTimeout(arrowNavCoalesceTimer)
  arrowNavCoalesceTimer = null
  const pending = arrowNavPending
  arrowNavPending = null
  if (!pending) return

  if (gridRows.value.length === 0) return

  const { baseWorkId, baseCol, baseRowIndex, anchor, deltaCol, deltaRow, extend, lastAxisKey } =
    pending

  if (baseWorkId == null) {
    selectCell(gridRows.value[0].work_id, 0)
    nextTick(() => scrollActiveCellIntoView(lastAxisKey))
    return
  }

  if (deltaCol === 0 && deltaRow === 0) return

  const col = Math.max(0, Math.min(WORK_LARGE_SCHEDULE_COUNT - 1, baseCol + deltaCol))
  const rowIndex = Math.max(
    0,
    Math.min(gridRows.value.length - 1, baseRowIndex + deltaRow),
  )
  const nextItem = gridRows.value[rowIndex]
  if (!nextItem) return

  const wid = String(nextItem.work_id)
  if (extend && anchor) {
    selectionAnchor.value = { ...anchor }
  }

  selectCell(wid, col, { extend })
  nextTick(() => scrollActiveCellIntoView(lastAxisKey))
}

function queueArrowNavMove(key, extend) {
  if (arrowNavPending && arrowNavPending.extend !== extend) {
    flushArrowNavCoalesce()
  }

  if (!arrowNavPending) {
    const baseWorkId = activeCell.value?.workId ?? null
    let baseRowIndex = baseWorkId != null ? workRowIndex(baseWorkId) : 0
    if (baseRowIndex < 0) baseRowIndex = 0
    arrowNavPending = {
      baseWorkId,
      baseCol: activeCell.value?.columnIndex ?? 0,
      baseRowIndex,
      anchor: selectionAnchor.value ? { ...selectionAnchor.value } : null,
      deltaCol: 0,
      deltaRow: 0,
      extend,
      lastAxisKey: key,
    }
  }

  if (key === 'ArrowLeft') arrowNavPending.deltaCol -= 1
  else if (key === 'ArrowRight') arrowNavPending.deltaCol += 1
  else if (key === 'ArrowUp') arrowNavPending.deltaRow -= 1
  else if (key === 'ArrowDown') arrowNavPending.deltaRow += 1
  arrowNavPending.lastAxisKey = key

  clearTimeout(arrowNavCoalesceTimer)
  arrowNavCoalesceTimer = setTimeout(flushArrowNavCoalesce, ARROW_NAV_COALESCE_MS)
}

function findDisplayRowIndexForWorkId(workId) {
  const wid = String(workId)
  return displayRows.value.findIndex(
    (row) => row.type === 'work' && String(row.item.work_id) === wid,
  )
}

function scrollActiveCellIntoView(preferredAxis) {
  if (!activeCell.value) return
  const container = gridFocusRef.value
  if (!container) return
  cancelPendingScrollTopUpdate()

  const padding = 4
  const stickyHeaderEl = container.querySelector('.schedule-grid-mc-header-row')
  const stickyHeaderHeight = stickyHeaderEl
    ? stickyHeaderEl.getBoundingClientRect().height
    : SCHEDULE_GRID_MC_HEADER_ROW_HEIGHT

  const cell = container.querySelector('td.schedule-grid-cell--active')
  if (cell) {
    const containerRect = container.getBoundingClientRect()
    const cellRect = cell.getBoundingClientRect()
    const visibleTop = containerRect.top + stickyHeaderHeight + padding
    const visibleBottom = containerRect.bottom - padding
    let nextTop = container.scrollTop

    const checkUp = preferredAxis !== 'ArrowDown'
    const checkDown = preferredAxis !== 'ArrowUp'

    if (checkUp && cellRect.top < visibleTop) {
      nextTop -= visibleTop - cellRect.top
    } else if (checkDown && cellRect.bottom > visibleBottom) {
      nextTop += cellRect.bottom - visibleBottom
    }

    nextTop = Math.max(0, nextTop)
    if (nextTop !== container.scrollTop) {
      container.scrollTop = nextTop
      scrollTop.value = nextTop
    }
    return
  }

  scrollActiveCellIntoViewByOffset(preferredAxis)
}

function scrollActiveCellIntoViewByOffset(preferredAxis) {
  if (!activeCell.value) return
  const container = gridFocusRef.value
  if (!container) return
  cancelPendingScrollTopUpdate()

  const displayIndex = findDisplayRowIndexForWorkId(activeCell.value.workId)
  if (displayIndex < 0) return

  const offsets = displayRowOffsets.value
  const rowTop = offsets[displayIndex] ?? 0
  const rowBottom = offsets[displayIndex + 1] ?? rowTop
  const stickyHeaderHeight = SCHEDULE_GRID_MC_HEADER_ROW_HEIGHT
  const viewTop = container.scrollTop
  const viewBottom = viewTop + container.clientHeight
  const visibleTop = viewTop + stickyHeaderHeight
  const padding = 4

  const checkUp = preferredAxis !== 'ArrowDown'
  const checkDown = preferredAxis !== 'ArrowUp'

  if (checkUp && rowTop < visibleTop + padding) {
    container.scrollTop = Math.max(0, container.scrollTop - (visibleTop + padding - rowTop))
  } else if (checkDown && rowBottom > viewBottom - padding) {
    container.scrollTop = Math.max(
      0,
      container.scrollTop + (rowBottom - (viewBottom - padding)),
    )
  }
  scrollTop.value = container.scrollTop
}

function handleGridKeyDown(event) {
  if (props.isMobile || !props.isTabActive || saving.value) return

  const isArrowKey =
    event.key === 'ArrowLeft' ||
    event.key === 'ArrowRight' ||
    event.key === 'ArrowUp' ||
    event.key === 'ArrowDown'
  if (!isArrowKey) {
    flushArrowNavCoalesce()
  }

  if ((event.ctrlKey || event.metaKey) && event.key === 'z' && !event.shiftKey) {
    event.preventDefault()
    handleUndo()
    return
  }

  if (isEditorInputFocused()) {
    if ((event.ctrlKey || event.metaKey) && (event.key === 'c' || event.key === 'v')) return
    const allowGridShortcut =
      (event.key === 'Delete' || event.key === 'Enter') && !isExpandPanelTextInputFocused()
    if (!allowGridShortcut) return
  }

  if ((event.ctrlKey || event.metaKey) && event.key === 'c') {
    event.preventDefault()
    copySelection()
    return
  }
  if ((event.ctrlKey || event.metaKey) && event.key === 'v') {
    event.preventDefault()
    pasteFromClipboard()
    return
  }
  if (event.key === 'Delete') {
    event.preventDefault()
    clearSelectedCells()
    return
  }
  if (event.key === 'Backspace') {
    if (!activeCell.value || rowActionArmed.value || !expandedEditor.value) return
    if (hiddenNoteEditing.value) return
    event.preventDefault()
    hiddenInputValue.value = ''
    applyHiddenInputToNoteDraft('')
    focusEditorNoteInput()
    return
  }
  if (event.key === 'Enter') {
    if (!activeCell.value || rowActionArmed.value) return
    event.preventDefault()
    hiddenInputValue.value = ''
    hiddenNoteEditing.value = false
    hiddenNoteAppendBase.value = ''
    if (event.shiftKey) {
      cycleSelectionStatus1Retreat()
      return
    }
    cycleSelectionStatus1Advance()
    return
  }
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    event.preventDefault()
    queueArrowNavMove(event.key, event.shiftKey)
    return
  }
  if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
    event.preventDefault()
    queueArrowNavMove(event.key, event.shiftKey)
  }
}

function onDocumentKeyDown(event) {
  if (!props.isTabActive) return
  if (isScheduleGridKeyboardTargetFocused()) return
  handleGridKeyDown(event)
}

function isMouseLikePointerEvent(event) {
  const type = event.pointerType
  return type == null || type === '' || type === 'mouse'
}

function onCellPointerDown(event, workId, columnIndex) {
  if (event.button !== 0) {
    updateHiddenInputFocusModeFromPointer(event)
    return
  }
  event.preventDefault()
  updateHiddenInputFocusModeFromPointer(event)

  const wid = String(workId)
  const now = Date.now()
  if (
    scheduleCellLastMouseDown.workId === wid &&
    scheduleCellLastMouseDown.columnIndex === columnIndex &&
    now - scheduleCellLastMouseDown.at <= SCHEDULE_CELL_DOUBLE_CLICK_MS
  ) {
    scheduleCellLastMouseDown.workId = null
    scheduleCellLastMouseDown.columnIndex = null
    scheduleCellLastMouseDown.at = 0
    isDraggingSelection.value = false
    if (!isCellInSelection(workId, columnIndex) || !isMultiCellSelection()) {
      selectCell(workId, columnIndex)
    }
    flushScheduledEditorSync()
    focusEditorNoteInput()
    return
  }

  scheduleCellLastMouseDown.workId = wid
  scheduleCellLastMouseDown.columnIndex = columnIndex
  scheduleCellLastMouseDown.at = now
  isDraggingSelection.value = event.pointerType === 'mouse'
  selectCell(workId, columnIndex, { extend: event.shiftKey })
}

function onCellMouseEnter(event, workId, columnIndex) {
  if (!isDraggingSelection.value) return
  if (!isMouseLikePointerEvent(event)) return
  if ((event.buttons & 1) === 0) return
  selectionEnd.value = { workId: String(workId), columnIndex }
}

function isWorkRowFullyInSelection(workId) {
  for (let c = 0; c <= WORK_LARGE_SCHEDULE_ORDER_MAX; c++) {
    if (!isCellInSelection(workId, c)) return false
  }
  return true
}

function onWorkNameContextMenu(event, workId) {
