}

function mergeRowsFromServerItems(items) {
  const nextMap = new Map(rowsByWorkId.value)
  const updatedWorkIds = []
  const validIds = new Set((items || []).map((item) => String(item.work_id)))
  for (const item of items || []) {
    const wid = String(item.work_id)
    if (!dirtyWorkIds.value.has(wid)) {
      const rows = cloneRows(padWorkLargeScheduleRows(item.rows || []))
      nextMap.set(wid, rows)
      setBaselineForWork(wid, rows)
      updatedWorkIds.push(wid)
    } else if (!nextMap.has(wid)) {
      const rows = cloneRows(padWorkLargeScheduleRows(item.rows || []))
      nextMap.set(wid, rows)
      setBaselineForWork(wid, rows)
      updatedWorkIds.push(wid)
    }
  }
  for (const key of nextMap.keys()) {
    if (!validIds.has(key) && !dirtyWorkIds.value.has(key)) {
      nextMap.delete(key)
      const nextBaseline = new Map(savedBaselineByWorkId.value)
      nextBaseline.delete(key)
      savedBaselineByWorkId.value = nextBaseline
    }
  }
  rowsByWorkId.value = nextMap
  clearCellsByWorkIdCache()
  if (updatedWorkIds.length) bumpRowsRevisionForWorkIds(updatedWorkIds)
}

function updateAllGridItemRows(workId, rows) {
  const wid = String(workId)
  const index = allGridItems.value.findIndex((item) => String(item.work_id) === wid)
  if (index < 0) return
  allGridItems.value[index] = {
    ...allGridItems.value[index],
    rows: rows || [],
  }
}

async function reloadList() {
  if (loading.value) return
  loading.value = true
  error.value = null
  try {
    await loadMasterData()
    const result = await supabaseService.fetchWorkLargeScheduleList({})
    allGridItems.value = result.items || []
    mergeRowsFromServerItems(allGridItems.value)
    sanitizeCurrentFilters()
    saveScheduleGridFilters(filters.value)
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] reload failed:', err)
    error.value = err.message || '読み込みに失敗しました'
  } finally {
    loading.value = false
    if (props.isTabActive) {
      nextTick(() => attachGridVirtualScroll())
    }
  }
}

function persistFilters() {
  sanitizeCurrentFilters()
  saveScheduleGridFilters(filters.value)
}

function onPropertySearchInput() {
  clearTimeout(propertySearchSaveTimer)
  propertySearchSaveTimer = setTimeout(() => persistFilters(), 300)
}

function toggleSortDirection() {
  filters.value.sortAscending = !filters.value.sortAscending
  persistFilters()
}

function toggleShowLatestFilter() {
  const next = !filters.value.showLatestFilter
  filters.value.showLatestFilter = next
  if (next) {
    filters.value = resetScheduleGridLatestLockedFilters(filters.value)
  }
  persistFilters()
}

function onLatestLimitChange(event) {
  filters.value.latestLimit = Number(event.target.value)
  persistFilters()
}

function onSortKeyChange(event) {
  filters.value.sortKey = event.target.value
  persistFilters()
}

function resetAllGridFiltersToSelectAll() {
  clearTimeout(propertySearchSaveTimer)
  filters.value = resetScheduleGridFiltersToSelectAll(filters.value)
  persistFilters()
}

function openFilterModal(kind) {
  if (filters.value.showLatestFilter && isScheduleGridLatestLockedFilterKind(kind)) return
  filterModalKind.value = kind
  const options = filterModalOptions.value
  const allValues = optionValuesFromList(options)
  if (kind === 'mc') {
    filterModalSelected.value = expandScheduleGridMultiFilterForModal(filters.value.mcIds, allValues)
  } else if (kind === 'registrationYear') {
    filterModalSelected.value = expandScheduleGridMultiFilterForModal(
      filters.value.registrationYears,
      allValues,
    )
  } else if (kind === 'instructionYear') {
    filterModalSelected.value = expandScheduleGridMultiFilterForModal(
      filters.value.instructionYears,
      allValues,
    )
  } else if (kind === 'employee') {
    filterModalSelected.value = expandScheduleGridMultiFilterForModal(
      filters.value.employeeFilterValues,
      allValues,
    )
  } else if (kind === 'progressive') {
    filterModalSelected.value = expandScheduleGridMultiFilterForModal(
      filters.value.progressiveStatusIds,
      allValues,
    )
  } else {
    filterModalSelected.value = expandScheduleGridMultiFilterForModal(
      filters.value.jkkStatusIds,
      allValues,
    )
  }
  filterModalOpen.value = true
}

function applyFilterModal(values) {
  const allValues = optionValuesFromList(filterModalOptions.value)
  if (filterModalKind.value === 'employee') {
    filters.value.employeeFilterValues = applyScheduleGridMultiFilter(values || [], allValues)
      .map((value) => {
        if (value === SCHEDULE_GRID_EMPLOYEE_UNASSIGNED) return SCHEDULE_GRID_EMPLOYEE_UNASSIGNED
        const n = Number(value)
        return Number.isInteger(n) ? n : null
      })
      .filter((value) => value != null)
  } else {
    const normalized = applyScheduleGridMultiFilter(values || [], allValues)
      .map(Number)
      .filter((n) => Number.isInteger(n))
    if (filterModalKind.value === 'mc') filters.value.mcIds = normalized
    else if (filterModalKind.value === 'registrationYear') filters.value.registrationYears = normalized
    else if (filterModalKind.value === 'instructionYear') filters.value.instructionYears = normalized
    else if (filterModalKind.value === 'progressive') filters.value.progressiveStatusIds = normalized
    else filters.value.jkkStatusIds = normalized
  }
  persistFilters()
}

function applyMobileSettings(nextFilters) {
  filters.value = {
    ...filters.value,
    ...nextFilters,
  }
  persistFilters()
}

function handleWorkNameDoubleClick(workId) {
  emit('open-work-in-home', workId)
}

function handleEmployeeDoubleClick(workId) {
  openWorkLargeScheduleModalForWork(workId)
}

async function openWorkLargeScheduleModalForWork(workId) {
  if (saving.value || workLargeScheduleSaving.value) return
  const wid = String(workId)
  modalWorkId.value = wid
  const mcId = gridItemMcId(workId)
  const mcTemplates = await supabaseService.getScheduleLabelTemplatesForMc(mcId)
  if (mcTemplates.length > 0) {
    const rest = labelTemplates.value.filter((row) => Number(row.mc_id) !== Number(mcId))
    labelTemplates.value = [...rest, ...mcTemplates].sort((a, b) => {
      const mcDiff = Number(a.mc_id) - Number(b.mc_id)
      if (mcDiff !== 0) return mcDiff
      return Number(a.sort_order) - Number(b.sort_order)
    })
  }
  let rows = cloneRows(getRowsForWork(wid))
  workLargeScheduleCanDelete.value = rows.some((row) => row.id != null && row.id !== '')
  if (!workLargeScheduleCanDelete.value) {
    const result = await supabaseService.getWorkLargeSchedules(wid).catch(() => ({ rows: [] }))
    const savedRows = result.rows || []
    workLargeScheduleCanDelete.value = savedRows.length > 0
    if (savedRows.length > 0) {
      rows = padWorkLargeScheduleRows(savedRows)
    } else if (!rows.some((row) => row.schedule_label_template_id)) {
      rows = buildWorkLargeScheduleRowsFromTemplate(mcTemplates)
    }
  }
  workLargeScheduleRows.value = rows
  isWorkLargeScheduleModalOpen.value = true
}

function closeWorkLargeScheduleModal() {
  isWorkLargeScheduleModalOpen.value = false
  modalWorkId.value = null
}

async function saveWorkLargeScheduleFromModal(payload) {
  if (!modalWorkId.value) return
  const rows = Array.isArray(payload) ? payload : payload?.rows
  const scheduleCreatedAt = Array.isArray(payload) ? null : payload?.schedule_created_at
  const wid = String(modalWorkId.value)
  workLargeScheduleSaving.value = true
  try {
    const result = await supabaseService.upsertWorkLargeSchedules(wid, rows, {
      schedule_created_at: scheduleCreatedAt,
    })
    const savedRows = padWorkLargeScheduleRows(result.rows || [])
    setRowsForWork(wid, savedRows)
    updateAllGridItemRows(wid, result.rows || [])
    await supabaseService.cacheWorkLargeSchedulesForWork(wid, savedRows)
    workLargeScheduleCanDelete.value = savedRows.length > 0
    dirtyWorkIds.value.delete(wid)
    setBaselineForWork(wid, savedRows)
    undoHistory.value = undoHistory.value.filter((entry) => !entryAffectsWorkId(entry, wid))
    refreshExpandedEditorFromRows(wid)
    closeWorkLargeScheduleModal()
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] modal save failed:', err)
    await dialog.alert(`工程スケジュールの保存に失敗しました: ${err.message}`, { title: 'エラー' })
  } finally {
    workLargeScheduleSaving.value = false
  }
}

async function deleteWorkLargeScheduleFromModal() {
  if (!modalWorkId.value || !workLargeScheduleCanDelete.value) return
  const ok = await dialog.confirm(
    'この案件の進捗状況をすべて削除します。\nこの操作は取り消せません。よろしいですか？',
    { title: '確認' },
  )
  if (!ok) return
  const wid = String(modalWorkId.value)
  workLargeScheduleDeleting.value = true
  try {
    await supabaseService.deleteWorkLargeSchedules(wid)
    allGridItems.value = allGridItems.value.filter((item) => String(item.work_id) !== wid)
    const rows = buildWorkLargeScheduleRowsFromTemplate(labelTemplatesForWorkId(wid))
    setRowsForWork(wid, rows)
    await supabaseService.cacheWorkLargeSchedulesForWork(wid, [])
    workLargeScheduleCanDelete.value = false
    dirtyWorkIds.value.delete(wid)
    setBaselineForWork(wid, rows)
    undoHistory.value = undoHistory.value.filter((entry) => !entryAffectsWorkId(entry, wid))
    refreshExpandedEditorFromRows(wid)
    closeWorkLargeScheduleModal()
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] modal delete failed:', err)
    await dialog.alert(`工程スケジュールの削除に失敗しました: ${err.message}`, { title: 'エラー' })
  } finally {
    workLargeScheduleDeleting.value = false
  }
}

async function handleSave() {
  flushScheduledEditorSync()
  if (!hasUnsavedChanges.value || saving.value) return
  saving.value = true
  error.value = null
  try {
    const items = Array.from(dirtyWorkIds.value).map((workId) => ({
      work_id: workId,
      rows: getRowsForWork(workId).map((row) => ({
        sort_order: row.sort_order,
        label: row.label ?? '',
        schedule_label_template_id: row.schedule_label_template_id ?? null,
        schedule_status_id: row.schedule_status_id ?? null,
        schedule_secondary_status_id: row.schedule_secondary_status_id ?? null,
        start_on: row.start_on || null,
        end_on: row.end_on || null,
        note: row.note || null,
      })),
    }))
    const saved = await supabaseService.batchUpsertWorkLargeSchedules(items)
    const cacheEntries = applySavedScheduleBatch(saved.items || [])
    void supabaseService.cacheWorkLargeSchedulesBatch(cacheEntries).catch((err) => {
      console.error('[WorkLargeScheduleGrid] cache after save failed:', err)
    })
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] save failed:', err)
    error.value = err.message || '保存に失敗しました'
  } finally {
    saving.value = false
  }
}

function handleUndo() {
  const entry = undoHistory.value.pop()
  if (!entry) return

  if (entry.type === 'batch-cells') {
    const affected = new Set()
    for (const change of entry.changes) {
      applyCellUndo(change)
      affected.add(String(change.workId))
    }
    for (const wid of affected) {
      refreshExpandedEditorFromRows(wid)
      syncDirtyWorkIdForWork(wid)
    }
    return
  }

  if (entry.type === 'cell') {
    applyCellUndo(entry)
    refreshExpandedEditorFromRows(entry.workId)
    syncDirtyWorkIdForWork(entry.workId)
  }
}

watch(expandCellPreviewText, () => {
  if (!expandFieldPreview.value.visible) return
  nextTick(onExpandFieldPreviewReposition)
})

watch(displayRows, (rows) => {
  pruneDisplayRowHeightCache(rows)
  syncDisplayRowOffsetsFull()
})

watch(
  () => props.isTabActive,
  (active) => {
    if (active) {
      reloadList()
      nextTick(() => attachGridVirtualScroll())
    } else {
      detachGridVirtualScroll()
    }
  },
  { immediate: true },
)

onMounted(() => {
  filters.value = loadScheduleGridFilters()
  document.addEventListener('keydown', onDocumentKeyDown)
  document.addEventListener('mouseup', onDocumentMouseUp)
  window.addEventListener('scroll', onExpandFieldPreviewReposition, true)
  window.addEventListener('resize', onExpandFieldPreviewReposition)
  nextTick(() => attachGridVirtualScroll())
})

onUnmounted(() => {
  removeNavigateClickSuppress()
  clearTimeout(propertySearchSaveTimer)
  clearTimeout(displayRowMeasureTimer)
  clearTimeout(expandCellPreviewDebounceTimer)
  flushArrowNavCoalesce()
  detachGridVirtualScroll()
  document.removeEventListener('keydown', onDocumentKeyDown)
  document.removeEventListener('mouseup', onDocumentMouseUp)
  window.removeEventListener('scroll', onExpandFieldPreviewReposition, true)
  window.removeEventListener('resize', onExpandFieldPreviewReposition)
})

defineExpose({
  hasUnsavedChanges: () => hasUnsavedChanges.value,
  reloadList,
  reloadScheduleLabelTemplates,
  discardUnsavedChanges: async () => {
    const nextMap = new Map()
    for (const item of allGridItems.value) {
      const wid = String(item.work_id)
      const baseline = savedBaselineByWorkId.value.get(wid)
      nextMap.set(
        wid,
        cloneRows(baseline ?? padWorkLargeScheduleRows(item.rows || [])),
      )
    }
    rowsByWorkId.value = nextMap
    clearCellsByWorkIdCache()
    bumpRowsRevisionForWorkIds(nextMap.keys())
    dirtyWorkIds.value = new Set()
    undoHistory.value = []
    clearExpandedEditor()
  },
})
