              <!-- このカテゴリーに属するファイルを表示 -->
              <div v-if="isMobile || showTouchUpload || hasFilesInCategory(category.id)" class="phase-files-grid" :style="{ gridTemplateColumns: `repeat(auto-fill, minmax(${gridColumnSize}px, 1fr))` }">
                <button
                  v-if="isMobile || showTouchUpload"
