                  @click="handleFileClick(file, { sectionFiles: filesByCategoryWithoutPhase[category.id] || [] })"
                >
                  <div class="file-thumbnail-small" :class="{ 'non-standard-aspect': !file.is_standard_aspect_ratio }" :style="{ width: `${thumbnailSize.width}px`, height: `${thumbnailSize.height}px` }">
                    <img
                      v-if="imageUrls[file.id]"
                      :src="imageUrls[file.id]"
