        >
          <span class="upload-board">仮黒板</span>
        </button>
        <div
          v-for="file in unassignedFilesWithoutCategory"
          :key="file.id"
          :data-file-id="String(file.id)"
          class="file-item"
          :class="{
            'assign-selected': isMobile && assignModeFileId === file.id,
            'file-item--thumb-selected': desktopImageTwoClickFileId === String(file.id),
            'comparison-target-highlight': isComparisonTargetFile(file.id),
            'file-item--thumb-bacmp-assigned': isAllTabAssignedFile(file.id)
