          @click="handleFileClick(file, { sectionFiles: unassignedFilesWithoutCategory })"
        >
          <div class="file-thumbnail" :class="{ 'non-standard-aspect': !file.is_standard_aspect_ratio }" :style="{ width: `${thumbnailSize.width}px`, height: `${thumbnailSize.height}px` }">
            <img
              v-if="imageUrls[file.id]"
              :src="imageUrls[file.id]"
              :alt="file.original_name || '画像'"
              :style="{ transform: `rotate(${file.rotation || 0}deg)`, opacity: file.is_standard_aspect_ratio !== false ? 1 : 0.3, ...getImageStyle(file) }"
              draggable="false"
              @error="handleImageError"
            />
            <div v-else class="file-placeholder">
              <span>📄</span>
            </div>
            <div
              v-if="!file.is_standard_aspect_ratio"
              class="non-standard-mark"
              title="標準アスペクト比ではありません"
            >
              ✕
            </div>
            <button
              class="file-delete-btn"
              @click.stop="handleDeleteFile(file.id)"
              title="ファイルを削除"
            >
              ✕
            </button>
          </div>
          <div class="file-info">
            <div class="file-name" :title="file.original_name">
              {{ file.original_name || '無名ファイル' }}
            </div>
          </div>
        </div>
      </div>
    </div>

    <div v-if="files.length === 0 && !isDragOver && (!workCategories || workCategories.length === 0)" class="empty-message">
      未割当ファイルはありません<br>
      <span v-if="!isMobile" class="upload-hint">ファイルをドラッグ&ドロップでアップロード</span>
    </div>
    </template>

    <!-- 比較モード -->
    <template v-if="leftPanelMode === 'comparison'">
      <BillingComparisonList 
        :billing-items="billingItems"
        :loading="billingItemsLoading"
        :before-category-id="comparisonBeforeCategoryId"
        :before-category-files="comparisonBeforeCategoryFiles"
        :photo-work-links-by-file-id="photoWorkLinksByFileId"
        :selected-comparison-item-id="selectedComparisonItemId"
        :billing-pick-mode-active="Boolean(bacmpBillingPickTargetSlotId)"
        :is-mobile="isMobile"
        @update-selected-comparison-item-id="selectedComparisonItemId = $event"
        @jump-to-all-by-code="emit('jump-to-all-by-code', $event)"
        @billing-item-append="emit('comparison-billing-item-append', $event)"
      />
    </template>

    <!-- 類似モード（スマホでも表示） -->
    <template v-if="leftPanelMode === 'similar'">
      <div class="similar-panel">
        <div class="similar-base-meta">
          <div class="similar-base-title">登録工事項目（基準画像）</div>
          <div v-if="!similarBaseFileId" class="similar-empty-message">スロットの類似ボタンから対象画像を選択してください</div>
          <template v-else>
            <div
              v-if="sortedSimilarBaseLinks.length === 0 && sortedSimilarBacmpBillingRows.length === 0"
              class="similar-empty-message"
            >
              比較リンクがありません
            </div>
            <div v-if="sortedSimilarBaseLinks.length > 0" class="comparison-items-list">
              <div
                v-for="(row, idx) in sortedSimilarBaseLinks"
                :key="`${row.external_code || 'empty'}-${idx}`"
                class="comparison-item"
                :data-comparison-code="String(row.external_code || '').trim()"
                :draggable="Boolean(row.external_code)"
                @dragstart="handleSimilarLinkDragStart($event, row)"
                @dblclick="handleSimilarLinkDblClick($event, row)"
              >
                <div class="comparison-content">
                  <div class="sort-order">{{ row.sortOrderLabel }}</div>
                  <div class="code" :class="{ 'code-alert': isTemporaryCode(row.external_code) }">{{ row.external_code || '' }}</div>
                  <div class="description">{{ row.description || '' }}</div>
                  <div class="quantity">{{ formatQuantity(row.quantity) }}</div>
                  <div class="unit">{{ row.unit || '-' }}</div>
                </div>
              </div>
            </div>
            <div
              v-if="!isMobile && sortedSimilarBacmpBillingRows.length > 0"
              class="similar-bacmp-billing-extra"
            >
              <div
                v-if="sortedSimilarBaseLinks.length > 0"
                class="similar-base-subtitle"
              >
                前後モード追加項目
              </div>
              <div class="comparison-items-list">
                <div
                  v-for="row in sortedSimilarBacmpBillingRows"
                  :key="row.key"
                  class="comparison-item comparison-item--bacmp-extra"
                  :data-comparison-code="String(row.external_code || '').trim()"
                  :draggable="Boolean(row.external_code || row.description)"
                  @dragstart="handleSimilarLinkDragStart($event, row)"
                  @dblclick="handleSimilarLinkDblClick($event, row)"
                >
                  <div class="comparison-content">
                    <div class="sort-order">{{ row.sortOrderLabel }}</div>
                    <div class="code" :class="{ 'code-alert': isTemporaryCode(row.external_code) }">{{ row.external_code || '' }}</div>
                    <div class="description">{{ row.description || '' }}</div>
                    <div class="quantity">{{ formatQuantity(row.quantity) }}</div>
                    <div class="unit">{{ row.unit || '-' }}</div>
                  </div>
                </div>
              </div>
            </div>
          </template>
        </div>
        <div class="similar-result-header-row">
          <button
            class="similar-generate-btn"
            :disabled="similarEmbeddingGenerating || !similarEmbeddingPendingCount"
            @click="emit('generate-similar-missing')"
            :title="similarEmbeddingPendingCount ? `未生成 ${similarEmbeddingPendingCount} 件を生成` : '未生成はありません'"
          >
            {{ similarEmbeddingGenerating ? '生成中' : `一括特徴値生成(${similarEmbeddingPendingCount})` }}
          </button>
          <div class="similar-result-header">類似画像（施工後）</div>
        </div>
        <div v-if="(similarFiles || []).length === 0" class="similar-empty-message">施工後フォルダ内に対象画像がありません</div>
        <div
          v-else
          class="files-grid similar-files-grid"
          :style="{ gridTemplateColumns: `repeat(auto-fill, minmax(${gridColumnSize}px, 1fr))` }"
        >
          <div
            v-for="file in similarFiles"
            :key="file.id"
            class="file-item"
            :class="{
              'file-item--thumb-selected': !isMobile && desktopImageTwoClickFileId === String(file.id),
              'file-item--thumb-bacmp-paired-red':
                comparePairedRedHighlightActive &&
                comparePairedRedFileIdSetForSimilar.has(String(file.id)),
              'file-item--thumb-bacmp-assigned':
                compareAssignedFileIdSetForSimilar.has(String(file.id)) &&
                !(
                  comparePairedRedHighlightActive &&
                  comparePairedRedFileIdSetForSimilar.has(String(file.id))
                )
            }"
            :draggable="!isMobile"
            @dragstart="handleDragStart($event, file)"
            @click="handleFileClick(file, { sectionFiles: similarFiles || [] })"
          >
            <div class="file-thumbnail" :class="{ 'non-standard-aspect': !file.is_standard_aspect_ratio }" :style="{ width: `${thumbnailSize.width}px`, height: `${thumbnailSize.height}px` }">
              <img
                v-if="imageUrls[file.id]"
                :src="imageUrls[file.id]"
                :alt="file.original_name || '画像'"
                :style="{ transform: `rotate(${file.rotation || 0}deg)`, opacity: file.is_standard_aspect_ratio !== false ? 1 : 0.3, ...getImageStyle(file) }"
                draggable="false"
                @error="handleImageError"
              />
              <div v-else class="file-placeholder"><span>📄</span></div>
            </div>
            <div class="file-info">
              <div class="file-name" :title="file.original_name">{{ file.original_name || '無名ファイル' }}</div>
              <div class="file-meta">一致度: {{ formatSimilarity(similarityByFileId?.[file.id]) }}</div>
            </div>
          </div>
        </div>
      </div>
    </template>
    
    <!-- スマホ／タブレットタッチ用: ファイル選択（未割当にアップロード） -->
    <input
      v-if="isMobile || showTouchUpload"
      ref="mobileFileInputRef"
      type="file"
      accept="image/*,.heic,.heif"
      multiple
      class="mobile-file-input"
      @change="handleMobileFileSelected"
    />

  </div>
</template>

<script setup>
import { ref, computed, defineProps, defineEmits, watch, onMounted, onUnmounted, nextTick, defineExpose } from 'vue'
import BillingComparisonList from './BillingComparisonList.vue'
import PhotoUploadSvgrepoIcon from './PhotoUploadSvgrepoIcon.vue'
import { useDialog } from '../composables/useDialog'
import { blurInputOnEnterWhenNotComposing } from '../utils/inputKeyboard.js'
import {
  inspectExternalDrop,
  readFlatFolderFiles,
  validateDroppedFolderName,
  partitionSlotImageUploadFiles,
  confirmContinueWithoutExcluded,
  FOLDER_DROP_MESSAGES
} from '../utils/folderDropUpload'

const props = defineProps({
  files: {
    type: Array,
    required: true
  },
  imageUrls: {
    type: Object,
    default: () => ({})
  },
  workId: {
    type: String,
    required: true
  },
  workCategories: {
    type: Array,
    default: () => []
  },
  allFiles: {
    type: Array,
    default: () => []
  },
  deletedCategories: {
    type: Array,
    default: () => []
  },
  thumbnailSizeMultiplier: {
    type: String,
    default: '4' // デフォルトは×4
  },
  billingItems: {
    type: Array,
    default: () => []
  },
  billingItemsLoading: {
    type: Boolean,
    default: false
  },
  leftPanelMode: {
    type: String,
    default: 'files' // 'files', 'all', 'comparison', 'similar'
  },
  isMobile: {
    type: Boolean,
    default: false
  },
  /** タブレット編集（左パネル表示）などでスマホ同様の＋アップロードを出す */
  showTouchUpload: {
    type: Boolean,
    default: false
  },
  assignModeFileId: {
    type: String,
    default: null
  },
  reverseAssignModeSlotId: {
    type: String,
    default: null
  },
  loading: {
    type: Boolean,
    default: false
  },
  isUploading: { 
    type: Boolean, 
    default: false 
  },
  similarBaseFileId: {
    type: [String, Number],
    default: null
  },
  similarBaseLinks: {
    type: Array,
    default: () => []
  },
  similarBaseBacmpBillingLines: {
    type: Array,
    default: () => []
  },
  similarFiles: {
    type: Array,
    default: () => []
  },
  similarityByFileId: {
    type: Object,
    default: () => ({})
  },
  similarEmbeddingPendingCount: {
    type: Number,
    default: 0
  },
  similarEmbeddingGenerating: {
    type: Boolean,
    default: false
  },
  /** 類似タブ: 割当済み（薄灰カード）— 前後モードは比較の前後 file_id、非前後は通常スロットの file_id */
  compareAssignedFileIdsForSimilar: {
    type: Array,
    default: () => []
  },
  /** 類似タブ薄赤用: 非前後モードで、similarBase（施工前）にサーバ slot_before_after_compare で対応する施工後 file_id のみ */
  comparePairedRedFileIdsForSimilar: {
    type: Array,
    default: () => []
  },
  comparePairedRedHighlightActive: {
    type: Boolean,
    default: false
  },
  photoWorkLinksByFileId: {
    type: Object,
    default: () => ({})
  },
  bacmpBillingPickTargetSlotId: {
    type: [String, Number],
    default: null
  }
})

const emit = defineEmits([
  'assign', 
  'upload', 
  'file-click', 
  'start-assign',
  'update-file-category', 
  'move-file-category',
  'remove-category', 
  'delete-file',
  'add-category',
  'update-category',
  'delete-category',
  'open-board-capture',
  'generate-similar-missing',
  'jump-to-all-by-code',
  'comparison-billing-item-append'
])

const dialog = useDialog()

const isDragOver = ref(false)
const isDraggingFromUnassigned = ref(false)
const dragOverCategoryId = ref(null)
const collapsedCategories = ref(new Set()) // 折りたたまれたカテゴリーのIDを保持
const collapsedUnassigned = ref(false) // 未分類ファイルの折りたたみ状態
const unassignedFilesContainer = ref(null)
const scrollInterval = ref(null)
const highlightedComparisonFileIds = ref(new Set())
const selectedComparisonItemId = ref('')
const modeScrollPositions = ref({
  filesAll: 0,
  similar: 0,
  comparison: 0
})

/** PC・タブレット・スマホ未割当: 1回目で選択、2回目で詳細モーダル（選択中は右上✕＝削除が表示） */
const desktopImageTwoClickFileId = ref(null)

const compareAssignedFileIdSetForSimilar = computed(() => {
  const arr = props.compareAssignedFileIdsForSimilar
  if (!Array.isArray(arr) || arr.length === 0) return new Set()
  return new Set(arr.map((id) => String(id)))
})

const comparePairedRedFileIdSetForSimilar = computed(() => {
  const arr = props.comparePairedRedFileIdsForSimilar
  if (!Array.isArray(arr) || arr.length === 0) return new Set()
  return new Set(arr.map((id) => String(id)))
})

function isAllTabAssignedFile(fileId) {
  if (props.leftPanelMode !== 'all') return false
  return compareAssignedFileIdSetForSimilar.value.has(String(fileId))
}

function clearDesktopImageTwoClickSelection() {
  desktopImageTwoClickFileId.value = null
}

// スマホ: 長押しで「割当モード」開始（サムネは2タップで詳細モーダル）
let longPressTimer = null
const longPressTriggered = ref(false)
const LONG_PRESS_MS = 900

function onMobileLongPressStart(file) {
  if (!props.isMobile) return
  // 割り当てモード中は新しい割り当てモードを起動しない
  if (props.assignModeFileId || props.reverseAssignModeSlotId) return
  longPressTriggered.value = false
  if (longPressTimer) clearTimeout(longPressTimer)
  longPressTimer = setTimeout(() => {
    longPressTriggered.value = true
    clearDesktopImageTwoClickSelection()
    emit('start-assign', file)
  }, LONG_PRESS_MS)
}

function onMobileLongPressEnd() {
  if (longPressTimer) {
    clearTimeout(longPressTimer)
    longPressTimer = null
  }
}

// スマホ用ファイル選択（未割当へアップロード）
const mobileFileInputRef = ref(null)
const mobileUploadTarget = ref({ categoryId: null })

function openMobileFilePicker(target = { categoryId: null }) {
  mobileUploadTarget.value = target || { categoryId: null }
  mobileFileInputRef.value?.click?.()
}

function handleMobileFileSelected(e) {
  const input = e.target
  const allFiles = Array.from(input?.files || [])
  if (input) input.value = ''
  if (allFiles.length === 0) return

  // 50個を超える場合はアラートを表示してキャンセル
  if (allFiles.length > 100) {
    void dialog.alert('一度にアップロードできるファイルは100個までです。', { title: 'エラー' })
    return
  }

  const files = allFiles.slice(0, 100)
  const { categoryId } = mobileUploadTarget.value || {}

  // 未分類（カテゴリなし）はオプション無しでアップロード
  if (!categoryId) {
    emit('upload', files)
    return
  }

  emit('upload', files, null, {
    work_category_id: categoryId
  })
}

