      const code = String(row?.external_code || '').trim()
      const bill = (props.billingItems || []).find((b) => String(b?.external_code || '').trim() === code)
      const hasSort = bill?.sort_order != null && bill?.sort_order !== ''
      return {
        ...row,
        unit: bill?.unit || '',
        sortOrder: hasSort ? Number(bill.sort_order) : Number.POSITIVE_INFINITY,
        sortOrderLabel: hasSort ? String(Number(bill.sort_order) + 1) : '（空）'
      }
    })
    .sort((a, b) => {
      if (a.sortOrder !== b.sortOrder) return a.sortOrder - b.sortOrder
      return String(a.external_code || '').localeCompare(String(b.external_code || ''))
    })
})

function parseSimilarBacmpBillingLine(line) {
  const s = String(line ?? '').trim()
  if (!s) return { code: '', desc: '', content: '' }
  if (s.includes('\t')) {
    const parts = s.split('\t')
    return {
      code: (parts[0] || '').trim(),
      desc: (parts[1] || '').trim(),
      content: (parts[2] || '').trim()
    }
  }
  const tokens = s.split(/\s+/).filter(Boolean)
  if (tokens.length >= 2) {
    return { code: tokens[0], desc: tokens.slice(1).join(' '), content: '' }
  }
  return { code: '', desc: s, content: '' }
}

function formatSimilarBacmpBillingDescription(parsed) {
  const { desc, content } = parsed
  if (!desc && !content) return ''
  if (content) return desc ? `${desc} 内容:${content}` : `内容:${content}`
  return desc
}

const sortedSimilarBacmpBillingRows = computed(() => {
  const lines = Array.isArray(props.similarBaseBacmpBillingLines) ? props.similarBaseBacmpBillingLines : []
  return lines
    .map((line, idx) => {
      const parsed = parseSimilarBacmpBillingLine(line)
      const code = parsed.code
      const bill = code
        ? (props.billingItems || []).find((b) => String(b?.external_code || '').trim() === code)
        : null
      return {
        key: `bacmp-billing-${idx}`,
        external_code: code,
        description: formatSimilarBacmpBillingDescription(parsed),
        content: parsed.content,
        quantity: bill?.quantity ?? '',
        unit: bill?.unit || '',
        sortOrderLabel: '＋'
      }
    })
    .filter((row) => row.external_code || row.description)
})

