function handleDragStart(event, file) {
  if (props.isMobile) return
  clearDesktopImageTwoClickSelection()
  isDraggingFromUnassigned.value = true
  event.dataTransfer.effectAllowed = 'copyMove' // moveとcopyの両方を許可
  event.dataTransfer.setData('text/plain', JSON.stringify({
    type: 'file',
    fileId: file.id
  }))
  // 未割当ファイル内でのドラッグ時にスクロールを開始
  startAutoScroll(event)
}

function handleDragOver(event) {
  if (props.isMobile) return
  // 未割当ファイルからのドラッグの場合は反応しない
  if (isDraggingFromUnassigned.value) {
    return
  }
  
  // 外部からのファイルドロップ（アップロード）の場合のみ反応
  if (event.dataTransfer.types.includes('Files')) {
    event.preventDefault()
    isDragOver.value = true
    event.dataTransfer.dropEffect = 'copy'
  }
}

function handleDragLeave(event) {
  if (props.isMobile) return
  // 未割当エリアから離れたときに、isDragOverをfalseに戻す
  // relatedTargetが未割当エリアの子要素でない場合のみfalseにする
  const relatedTarget = event.relatedTarget
  if (!relatedTarget || !event.currentTarget.contains(relatedTarget)) {
    isDragOver.value = false
  }
}

function handleDragEnd(event) {
  if (props.isMobile) return
  // ドラッグが終了したときに、すべてのドラッグ状態をリセット
  resetDragState()
}

function resetDragState() {
  isDragOver.value = false
  isDraggingFromUnassigned.value = false
  dragOverCategoryId.value = null
  stopAutoScroll()
  document.removeEventListener('dragover', handleGlobalDragOver)
}

function handleGlobalDragOver(event) {
  if (props.isMobile) return
  if (!isDraggingFromUnassigned.value || !unassignedFilesContainer.value) return
  
  const container = unassignedFilesContainer.value
  const containerRect = container.getBoundingClientRect()
  const mouseY = event.clientY
  
  // コンテナの範囲内かチェック
  const OUTSIDE_MARGIN = 40
  if (mouseY < containerRect.top - OUTSIDE_MARGIN || mouseY > containerRect.bottom + OUTSIDE_MARGIN) {
    return
  }
  
  // スクロール処理
  const scrollSpeed = 10
  const scrollThreshold = Math.min(75, Math.max(28, Math.floor(containerRect.height * 0.12)))
  
  const relativeY = mouseY - containerRect.top
  
  if (relativeY < scrollThreshold) {
    container.scrollTop -= scrollSpeed
  } else if (relativeY > containerRect.height - scrollThreshold) {
    container.scrollTop += scrollSpeed
  }
}

function handleScroll(event) {
  // スクロールイベント（必要に応じて処理を追加）
}

function startAutoScroll(event) {
  document.addEventListener('dragover', handleGlobalDragOver)
}

function stopAutoScroll() {
  // グローバルイベントリスナーで処理するため、ここでは何もしない
}

function handleDrop(event) {
  if (props.isMobile) return
  event.preventDefault()
  resetDragState()
  void handleExternalDropUpload(event, { parentIdForFolderResolve: null })
}

async function handleExternalDropUpload(event, { parentIdForFolderResolve = null, rejectFolderOnCategory = false } = {}) {
  const inspected = inspectExternalDrop(event.dataTransfer)
  if (inspected.dropKind === 'error') {
    await dialog.alert(inspected.message, { title: 'エラー' })
    return
  }

  if (inspected.dropKind === 'folder') {
    if (rejectFolderOnCategory) {
      await dialog.alert(FOLDER_DROP_MESSAGES.CATEGORY_ZONE, { title: 'エラー' })
      return
    }
    await handleFolderDropUpload(inspected.entry, parentIdForFolderResolve)
    return
  }

  const files = Array.from(event.dataTransfer.files)
  if (files.length > 0) {
    const uploadOptions = parentIdForFolderResolve
      ? { work_category_id: parentIdForFolderResolve }
      : {}
    emit('upload', files, null, uploadOptions)
    return
  }

  try {
    const data = JSON.parse(event.dataTransfer.getData('text/plain'))
    if (data.type === 'file' && data.fileId) {
      emit('move-file-category', data.fileId, parentIdForFolderResolve)
    }
  } catch (err) {
    console.error('Drop error:', err)
  }
}

async function handleFolderDropUpload(dirEntry, parentIdForFolderResolve) {
  const readResult = await readFlatFolderFiles(dirEntry)
  if (readResult.error) {
    await dialog.alert(readResult.error, { title: 'エラー' })
    return
  }

  const nameValidation = validateDroppedFolderName(dirEntry.name)
  if (!nameValidation.ok) {
    await dialog.alert(nameValidation.message, { title: 'エラー' })
    return
  }

  const { valid, excluded } = partitionSlotImageUploadFiles(readResult.files)
  if (valid.length === 0) {
    await dialog.alert(FOLDER_DROP_MESSAGES.NO_UPLOADABLE_FILES, { title: 'エラー' })
    return
  }

  const shouldContinue = await confirmContinueWithoutExcluded(dialog, excluded)
  if (!shouldContinue) return

  emit('upload', valid, null, {
    ensure_folder: {
      name: nameValidation.name,
      parent_id: parentIdForFolderResolve
    }
  })
}

