function restoreScrollPosition(mode) {
  const scroller = getScrollContainerForMode(mode)
  if (!scroller || typeof scroller.scrollTop !== 'number') return
  const key = getScrollModeKey(mode)
  scroller.scrollTop = Number(modeScrollPositions.value[key] || 0)
}

