})

// カテゴリーごとにファイルをグループ化（フォルダ直下）
const filesByCategoryWithoutPhase = computed(() => {
  const grouped = {}
  
  validWorkCategories.value.forEach(category => {
    grouped[category.id] = []
  })
  
  // ファイルをカテゴリー（work_category_id）で分類（削除予定フォルダ配下は除外済み）
  visibleFiles.value.forEach(file => {
    const categoryId = file.work_category_id
    if (categoryId) {
      if (!grouped[categoryId]) {
        grouped[categoryId] = []
      }
      grouped[categoryId].push(file)
    }
  })
  
  return grouped
})

