function escapeSelectorValue(value) {
  const s = String(value || '')
  if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
    return CSS.escape(s)
  }
  return s.replace(/["\\]/g, '\\$&')
}

async function focusByComparisonCode(payload) {
  const categoryId = payload?.categoryId
  const fileIds = Array.isArray(payload?.fileIds) ? payload.fileIds.map((id) => String(id)) : []
  if (!categoryId || fileIds.length === 0) return false

  const allCategoryIds = (validWorkCategories.value || []).map((cat) => cat.id).filter(Boolean)
  collapsedCategories.value = new Set(allCategoryIds.filter((id) => id !== categoryId))
  collapsedUnassigned.value = true
  highlightedComparisonFileIds.value = new Set(fileIds)

  await nextTick()
  if (unassignedFilesContainer.value && typeof unassignedFilesContainer.value.scrollTop === 'number') {
    const firstTargetId = fileIds[0]
    const targetEl = firstTargetId
      ? unassignedFilesContainer.value.querySelector(
          `.comparison-target-highlight[data-file-id="${escapeSelectorValue(firstTargetId)}"]`
        )
      : null
    if (targetEl && typeof targetEl.offsetTop === 'number') {
      const baseTop = typeof unassignedFilesContainer.value.offsetTop === 'number' ? unassignedFilesContainer.value.offsetTop : 0
      unassignedFilesContainer.value.scrollTop = Math.max(0, targetEl.offsetTop - baseTop - 8)
    } else {
      unassignedFilesContainer.value.scrollTop = 0
    }
    modeScrollPositions.value.filesAll = unassignedFilesContainer.value.scrollTop
  }
  return true
}

