function formatFileSize(bytes) {
  if (!bytes) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

function getImageStyle(file) {
  if (!file || !file.width || !file.height) {
    return {
      width: '100%',
      height: '100%',
      objectFit: 'contain',
      objectPosition: 'center'
    }
  }
  
  // オリジナルの画像サイズで判断（回転は考慮しない）
  // 縦長（height > width）: width: 100%
  // 横長（width > height）: height: 100%
  if (file.height > file.width) {
    // オリジナル縦長画像: width: 100%
    return {
      width: '100%',
      objectFit: 'contain',
      objectPosition: 'center'
    }
  } else {
    // オリジナル横長画像: height: 100%
    return {
      height: '100%',
      objectFit: 'contain',
      objectPosition: 'center'
    }
  }
}

function handleRemoveCategory(fileId) {
  emit('remove-category', fileId)
}

function handleDeleteFile(fileId) {
  if (String(desktopImageTwoClickFileId.value) === String(fileId)) {
    clearDesktopImageTwoClickSelection()
  }
  // アラートなしで直接削除
  emit('delete-file', fileId)
}

async function handleDeleteAllInCategory(categoryId) {
  const allFilesInCategory = filesByCategoryWithoutPhase.value[categoryId] || []
  if (allFilesInCategory.length === 0) return

  const ok = await dialog.confirm(`このカテゴリー内の\n${allFilesInCategory.length}件のファイルをすべて削除しますか？`, { title: '確認' })
  if (!ok) return
  allFilesInCategory.forEach(file => {
    emit('delete-file', file.id)
  })
}

async function handleDeleteAllUnassigned() {
  if (unassignedFilesWithoutCategory.value.length === 0) return

  const ok = await dialog.confirm(`未分類ファイル\n${unassignedFilesWithoutCategory.value.length}件をすべて削除しますか？`, { title: '確認' })
  if (!ok) return
  unassignedFilesWithoutCategory.value.forEach(file => {
    emit('delete-file', file.id)
  })
}

// アップロード中はスクロールを無効化

function handleWindowDropOrDragEnd() {
  resetDragState()
}

/** 施工後など @drop.stop 先で window に届かない場合の解除（SlotItem から発火） */
const CLEAR_UNASSIGNED_FILE_DRAG_EVENT = 'clear-unassigned-file-drag-state'
function handleClearUnassignedFileDragFromOutside() {
  resetDragState()
}

function handleDocumentDragLeave(event) {
  // ウィンドウ外へドラッグが抜けたケースで残留ハイライトを解除
  if (!event.relatedTarget && (event.clientX <= 0 || event.clientY <= 0)) {
    resetDragState()
  }
}

onMounted(() => {
  window.addEventListener('drop', handleWindowDropOrDragEnd)
  window.addEventListener('dragend', handleWindowDropOrDragEnd)
  window.addEventListener(CLEAR_UNASSIGNED_FILE_DRAG_EVENT, handleClearUnassignedFileDragFromOutside)
  document.addEventListener('dragleave', handleDocumentDragLeave)
  nextTick(() => {
    restoreScrollPosition(props.leftPanelMode)
  })
})

onUnmounted(() => {
  resetDragState()
  window.removeEventListener('drop', handleWindowDropOrDragEnd)
  window.removeEventListener('dragend', handleWindowDropOrDragEnd)
  window.removeEventListener(CLEAR_UNASSIGNED_FILE_DRAG_EVENT, handleClearUnassignedFileDragFromOutside)
  document.removeEventListener('dragleave', handleDocumentDragLeave)
  document.body.style.overflow = ''
})
